(window.GIM_TS=window.GIM_TS||{})["Shabbat.5"]={"from":120,"a":[["\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' אושעיא אומר\u0004 בענין הקמיע: \u0003ובלבד שלא יאחזנו בידו ויעבירנו ארבע אמות ברשות הרבים,\u0004 הרי שאף בקמיע אנו מחלקים בענין זה,","\u0003אלא\u0004 יש לתרץ כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003ב\u0004קמיע ה\u0003מחופה\u0004 ב\u0003עור,\u0004 שכיון שהכתב עצמו מכוסה שוב אין בכך בזיון השם אם נכנס לבית הכסא עמו.","ומקשים: \u0003והרי תפילין\u0004 שאף בהן הכתב \u0003מחופה\u0004 ב\u0003עור\u0004 בתי התפילין \u0003ותניא\u0004 \u0005[ו\u0006בכל זאת \u0005שנינו]\u0006 כי \u0003הנכנס לבית הכסא\u0004 כשהוא עטור בתפילין — \u0003חולץ\u0004 את ה\u0003תפילין ברחוק ארבע אמות\u0004 מבית הכסא, \u0003ונכנס.\u0004 הרי שאין הבדל להלכה אם הכתב מחופה או אינו מחופה!","ודוחים: \u0003התם\u0004 \u0005[שם,\u0006 בתפילין\u0005]\u0006 אין האיסור משום הכתב שבתוך התפילין אלא \u0003משום שי\"ן\u0004 הבולטת בעור בתי התפילין עצמן. ושי\"ן זו חייבת להיות בכל תפילין, וכפי ש\u0003אמר אביי שי\"ן של תפילין\u0004 מקור חובתה ב\u0003הלכה למשה מסיני. ו\u0004כן \u0003אמר אביי: דל\"ת של תפילין\u0004 שקושרים בצורה זו את רצועות תפילין של ראש מקור חובתה ב\u0003הלכה למשה מסיני. ו\u0004כן \u0003אמר\u0004 עוד \u0003אביי: יו\"ד של תפילין\u0004 מקור חובתה ב\u0003הלכה למשה מסיני.\u0004 ומפני אותיות אלה נזהרים בקדושת התפילין ואין נכנסים עמם לבית הכסא.","שנינו במשנה שלא יצא אדם בשבת לצאת \u0003לא בשריון ולא בקסדא ולא במגפיים.\u0004","מלים אלה לא היו מובנות, ועל כן הסבירו אותן: \u0003שריון\u0004 הוא \u0003זרדא,\u0004 והוא שריון עשוי קשקשים. \u0003קסדא\u0004 — \u0003אמר רב\u0004 שהוא \u0003סנוארתא,\u0004 מעין כובע של עור תחת כובע המתכת. ו\u0003מגפיים\u0004 — \u0003אמר רב\u0004 שהם \u0003פזמקי,\u0004 כעין מגפי ברזל למלחמה.","\u0003לא תצא אשה\u0004 לרשות הרבים \u0003במחט הנקובה\u0004 (מחט רגילה שיש בקצה נקב), \u0003ולא בטבעת שיש עליה חותם, ולא בכוליאר, ולא בכובלת\u0004 שעל מהותם יהא עוד דיון בגמרא, \u0003ולא בצלוחית של פלייטון\u0004 (בושם).","\u0003ואם יצתה\u0004 (יצאה) — \u0003חייבת חטאת,\u0004 אלו \u0003דברי ר' מאיר\u0004 הסבור כי המוציאתם עוברת משום נשיאת משא ביום השבת. \u0003וחכמים פוטרין\u0004 את היוצאת בשבת \u0003בכובלת ובצלוחית של פלייטון,\u0004 שלדעתם אלה הן תכשיטים, ולכן מותרים הם בטלטול מעיקר הדין.","על מה ששנינו במשנה כי אשה אסורה לצאת בשבת \u0003בטבעת בעלת חותם, ומשמע שבטבעת ללא חותם מותרת לצאת, אמר עולא: ו\u0004דינים אלה ביחס לאשה \u0003חילופיהן באיש,\u0004 שאיש שטלטל טבעת שיש בה חותם — פטור, ואם טלטל טבעת שאין בה חותם כיון שאינה נחשבת לו כתכשיט אסור בטלטולה והריהו חייב חטאת. ורוצים להסיק, \u0003אלמא קסבר\u0004 \u0005[מכאן שסבור]\u0006 \u0003עולא\u0004 כי \u0003כל מידי דחזי\u0004 \u0005[דבר שראוי]\u0006 \u0003לאיש לא חזי\u0004 \u0005[אינו ראוי]\u0006 \u0003לאשה, ומידי דחזי\u0004 \u0005[ודבר שראוי]\u0006 \u0003לאשה לא חזי\u0004 \u0005[אינו ראוי]\u0006 \u0003לאיש.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב יוסף\u0004 ממה ששנינו בתוספתא: \u0003הרועים יוצאין\u0004 בשבת \u0003בשקין. ולא\u0004 על \u0003הרועים בלבד אמרו\u0004 חכמים שמותרים לצאת בשקים בשבת, \u0003אלא\u0004 אף \u0003כל אדם. אלא\u0004 אמרו חכמים בלשון זו מפני \u0003שדרכן של הרועים לצאת בשקין.\u0004 הרי אף שהשק אינו מלבוש רגיל לכל אדם, כיון שהכל עשויים להשתמש בו, מותר הוא בלבישה אף למי שאינו רועה ואינו רגיל בשק. ועל פי אותו עיקרון נאמר שתכשיטי נשים וגברים, אף שאין רגילים להחליפם, מכל מקום כיון שאפשר שלעתים ישתמש האיש בשל אשה ולהיפך, הריהם מותרים!","\u0003אלא אמר רב יוסף: קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003עולא\u0004 כי \u0003נשים עם בפני עצמן הן.\u0004 וההבדל בין מנהגי נשים וגברים גדול מן ההבדל שבין בעלי מקצועות שונים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003המוצא תפילין\u0004 מחוץ לעיר בשבת — הריהו \u0003מכניסן זוג זוג, אחד האיש ואחד האשה. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003נשים עם בפני עצמן הן, והא\u0004 \u0005[והרי]\u0006 התפילין \u0003מצות עשה שהזמן גרמא הוא,\u0004 שיש זמנים שחייבים בה ויש זמנים שפטורים ממנה. \u0003ו\u0004כלל בידינו כי \u0003כל מצוות עשה שהזמן גרמא נשים פטורות\u0004 מהן. ואם נחזיק בשיטה שבגדי גבר ותכשיטיו אינם ראויים בשום פנים לאשה, משום מה מותר לאשה להניח את התפילין בשבת ולהכניסם העירה? והלא אין הם ראויים לנשים, והריהם כשאר משאות!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בענין תפילין \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' מאיר: לילה זמן תפילין הוא, ו\u0004כן \u0003שבת\u0004 ויום טוב \u0003זמן תפילין הוא,\u0004 ואם כן \u0003הוה ליה\u0004 \u0005[נעשית לה]\u0006 מצות התפילין \u0003מצות עשה שלא הזמן גרמא,\u0004 שלשיטה זו, מצוה תמיד להניח תפילין, ואין מצוות התפילין מוגבלת בזמן, \u0003ו\u0004לכן דינה כ\u0003כל מצות עשה שלא הזמן גרמא\u0004 — \u0003נשים חייבות,\u0004 ולכן מותר לנשים להניח את התפילין ולטלטלן.","על עיקר הדין במשנה שלדעת ר' מאיר מן התורה אשה המוציאה טבעת שיש עליה חותם חייבת, שואלים: \u0003והא\u0004 \u0005[הרי]\u0006 \u0003הוצאה כלאחר יד הוא!\u0004 שהרי טבעת שיש עליה חותם לאשה אינה תכשיט אלא חפץ כשאר החפצים, ודרך טלטול חפצים כרגיל הריהי בנשיאתם בידו, ואילו נשיאת חפץ על גבי האצבע אין זו דרך הולכה רגילה, והריהו טלטול שלא בדרך הראויה לכך (\"כלאחר יד\") וכל מלאכה שנעשתה כלאחר יד ולא כדרך עשייתה אין בה איסור מן התורה!","\u0003אמר ר' ירמיה\u0004 יש לומר כי \u0003באשה גזברית עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ואשה כזו דרכה אף בחול לענוד על אצבעה טבעת שיש עליה חותם. \u0003אמר רבא בר בר חנא\u0004 שכך \u0003אמר ר' יוחנן: תרצת\u0004 והסברת מדוע ובאיזה אופן \u0003האשה\u0004 תתחייב חטאת, ואולם \u0003איש\u0004 הנושא טבעת שאין עליה חותם \u0003מאי איכא למימר\u0004 \u0005[מה\u0006 יש \u0005לומר]?\u0006 מדוע יחויב?","\u0003אלא אמר רבא\u0004 שהטעם הוא אחר: \u0003פעמים שאדם נותן לאשתו טבעת שיש עליה חותם להוליכה לקופסא\u0004 שבביתו כדי לשומרה שם, \u0003ו\u0004כדי שלא תאבד את הטבעת \u0003מניחתה\u0004 האשה \u0003בידה\u0004 על אצבעה, \u0003עד שמגעת לקופסא. ו\u0004כן \u0003פעמים שהאשה נותנת לבעלה טבעת שאין עליה חותם להוליכה אצל אומן לתקן, ומניחה\u0004 הבעל \u0003בידו עד שמגיע אצל\u0004 ה\u0003אומן.\u0004 ולכן אף שאין מחליפים את סוגי הטבעות לקישוט, בכל זאת אחת הדרכים הרגילות והמקובלות לטלטל טבעת הריהי בענידתה על האצבע.","שנינו במשנה שלא תצא אשה בשבת \u0003לא בכוליאר ולא בכובלת.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003כוליאר\u0004 זה? \u0003אמר רב:\u0004 הוא \u0003מכבנתא\u0004 — סיכה שבה פורפת אשה את צואר בגדה. \u0003כובלת\u0004 — \u0003אמר רב\u0004 שהוא \u0003חומרתא דפילון\u0004 \u0005[צרור של בושם].\u0006 \u0003וכן אמר רב אסי\u0004 כדברי רב שהוא \u0003חומרתא דפילון\u0004 \u0005[צרור של בושם].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003לא תצא אשה\u0004 בשבת \u0003בכובלת, ואם יצתה\u0004 (יצאה) — \u0003חייבת חטאת,\u0004 שיש בכך איסור מן התורה, אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 אמנם \u0003לא תצא\u0004 לכתחילה, \u0003ו\u0004אולם \u0003אם יצתה\u0004 — \u0003פטורה. ר' אליעזר אומר: יוצאת אשה בכובלת\u0004 אף \u0003לכתחלה.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון \u0005הם חולקים]?\u0006 \u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 כי \u0003משאוי\u0004 (משא) \u0003הוא\u0004 ולכן המוציאו לרשות הרבים בשבת חייב חטאת. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי אמנם \u0003תכשיט הוא ו\u0004אולם אסרו לצאת בו לכתחילה מתוך החשש \u0003דילמא שלפא ומחויא ואתיא לאיתוייה\u0004 \u0005[שמא תוציא\u0006 את הכובלת ממקומה \u0005ותראנה\u0006 לחברתה \u0005ותבוא להביאה,\u0006 לטלטלה\u0005]\u0006 ברשות הרבים. \u0003ור' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003מאן\u0004 \u0005[מי]\u0006 \u0003דרכה למירמי\u0004 \u0005[מי דרכה ללבוש]\u0006 בשמים אלה — \u0003אשה שריחה רע,\u0004 ו\u0003אשה שריחה רע לא שלפא ומחויא, ולא אתיא לאתוייה\u0004 \u0005[אינה מוציאה ומראה ואינה\u0006 עשויה \u0005להביאו,\u0006 לטלטלו\u0005]\u0006 \u0003ארבע אמות ברשות הרבים,\u0004 שכן אם תוציאו יהיה ניכר ריחה הרע ובודאי אינה רוצה להראות ברבים שריחה רע. בברייתא זו סוכם כי ר' אליעזר מתיר מלכתחילה לצאת בכובלת.","ותוהים על כך: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במקום אחר כי \u0003ר' אליעזר פוטר\u0004 את האשה היוצאת בשבת \u0003בכובלת ובצלוחית של פלייטון.\u0004 ובדיני שבת \"פוטר\" משמעו שאמנם יש בכך איסור לכתחילה, אלא שאין בכך חיוב מן התורה!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 אלא \u0003הא כי קאי\u0004 \u0005[זה כשהוא עומד,\u0006 מוסב\u0005],\u0006 על דברי \u0003ר' מאיר,\u0004 ואילו \u0003הא כי קאי אדרבנן\u0004 \u0005[זה כשהוא מוסב על\u0006 דברי \u0005חכמים].\u0006 ובפירוט: \u0003כי קאי\u0004 \u0005[כאשר הוא עומד]\u0006 על דברי \u0003ר' מאיר\u0004 ש\u0003אמר\u0004 שהוא \u0003חייב חטאת, אמר ליה\u0004 \u0005[לומר]\u0006 שהוא \u0003פטור. ו\u0004אולם \u0003כי קאי אדרבנן דאמרי\u0004 \u0005[כאשר הוא עומד,\u0006 מתייחס לדברי \u0005חכמים האומרים],\u0006 שאם עשה כן הריהו \u0003פטור, אבל\u0004 מלכתחילה \u0003אסור\u0004 לעשות כן, \u0003אמר איהו\u0004 \u0005[הוא]\u0006 ש\u0003מותר\u0004 אף \u0003לכתחלה.\u0004"],["\u0003ומאי\u0004 \u0005[מה,\u0006 היכן\u0005]\u0006 אמר זאת \u0003ר' מאיר? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003לא תצא אשה\u0004 בשבת \u0003במפתח שבידה, ואם יצאת\u0004 (יצאה) — הריהי \u0003חייבת חטאת,\u0004 אלו \u0003דברי ר' מאיר. ר' אליעזר פוטר בכובלת ובצלוחית של פלייטון.\u0004","על עצם הלשון תוהים: \u0003כובלת מאן דכר\u0004 \u0005[מי הזכיר]\u0006 את \u0003שמה?\u0004 שהרי לא דיבר ר' מאיר בכובלת, ומדוע בא ר' אליעזר לומר בה דבר?","ומשיבים: \u0003חסורי מחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך יש לשנותה]:\u0006 \u0003וכן בכובלת וכן בצלוחית של פלייטון לא תצא, ואם יצאה\u0004 — \u0003חייבת חטאת,\u0004 אלו \u0003דברי ר' מאיר. ר' אליעזר פוטר בכובלת ובצלוחית של פלייטון. במה דברים אמורים\u0004 שפוטר בהם ר' אליעזר — \u0003כשיש בהם בושם, אבל\u0004 כאשר \u0003אין בהם בושם\u0004 — \u0003חייבת\u0004 משום הוצאת כלי בשבת.","\u0003אמר רב אדא בר אהבה: זאת אומרת\u0004 ש\u0003המוציא אוכלין פחות מכשיעור\u0004 שחייבים עליו משום הוצאה בשבת \u0003בכלי\u0004 — \u0003חייב,\u0004 כי אף שאינו חייב משום הוצאת האוכלים, הריהו מתחייב משום הוצאת הכלי. ואין אנו אומרים שהכלי טפל לאוכל שבו ואין הוצאתו נחשבת. והוכחה לכך ממה שאמרנו \u0003דהא\u0004 \u0005[שהרי]\u0006 צלוחית ש\u0003אין בה בושם, כפחות מכשיעור בכלי דמי\u0004 \u0005[נחשבת]\u0006 \u0003וקתני\u0004 \u0005[ושנינו]\u0006 ש\u0003חייבת\u0004 אף שיש ריח בושם בכלי.","\u0003רב אשי אמר:\u0004 אין להוכיח מכאן, כי \u0003בעלמא אימא\u0004 \u0005[בכלל אומר]\u0006 \u0003לך\u0004 שבמקרה כגון זה \u0003פטור, ושאני הכא דליתיה לממשא\u0004 \u0005[ו\u0006אולם \u0005שונה כאן שאין לממשו\u0006 של הבושם\u0005]\u0006 \u0003כלל\u0004 והכלי ריק לגמרי ולכן אסור הוא בטלטול.","כיון שהוזכר הפלייטון הביאו כמה דברים הקשורים בו. נאמר: \"השותים במזרקי יין \u0003וראשית שמנים ימשחו\u0004 ולא נחלו על שבר יוסף\" (עמוס ו, ו), ו\"ראשית שמנים ימשחו\" \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: זה פלייטון.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף\u0004 ממה ששנינו בתוספתא: \u0003אף על פלייטון גזר ר' יהודה בן בבא\u0004 שלא ישתמשו בו משום אבילות החורבן, \u0003ולא הודו לו\u0004 חכמים. \u0003ואי אמרת\u0004 \u0005[ואם אמרת]\u0006 שפלייטון הוא הכתוב בפסוק זה, ושיש בו \u0003משום תענוג, אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא הודו לו?\u0004 והרי בפסוק זה מגנים את אלה שאינם סובלים את כאבה של האומה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 \u0003הא דכתיב\u0004 \u0005[זה שנאמר]\u0006 באותו פסוק \u0003\"השתים במזרקי יין\",\u0004 ונחלקו \u0003ר' אמי ור' אסי\u0004 מה הם מזרקי יין אלה, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהם \u0003קנישקנין\u0004 (כלי יין שיש לו כמה פיות ואפשר לשתות מאחדים מהם יחד), \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר שמזרקין\u0004 (זורקים) \u0003כוסותיהן זה לזה\u0004 בשמחה ובדיחות דעת. אם כן \u0003הכי נמי דאסיר\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאסור]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה בר רב הונא איקלע לבי ריש גלותא\u0004 \u0005[הזדמן לבית ראש הגולה]\u0006 \u0003ו\u0004ראה ש\u0003שתה\u0004 ראש הגולה \u0003בקנישקנין, ולא אמר ליה\u0004 \u0005[לו]\u0006 רבה בר רב הונא \u0003ולא מידי\u0004 \u0005[דבר]!\u0006","\u0003אלא\u0004 יש לומר כי הכלל בזה הוא: \u0003כל מידי דאית ביה\u0004 \u0005[דבר שיש בו]\u0006 \u0003תענוג ואית ביה\u0004 \u0005[ויש בו]\u0006 \u0003שמחה\u0004 — \u0003גזרו\u0004 בו \u0003רבנן\u0004 \u0005[חכמים]\u0006 שלא לעשותו מפני אבל החורבן, \u0003אבל מידי דאית ביה\u0004 \u0005[שיש\u0006 \u0003בו] תענוג ולית ביה\u0004 \u0005[ואין בו]\u0006 \u0003שמחה\u0004 — \u0003לא גזרו\u0004 בו \u0003רבנן\u0004 \u0005[חכמים],\u0006 והפלייטון, כיון שאין בו משום שמחה, אף שהוא דבר יקר ומענג — לא אסרוהו. כיון שהוזכרו פסוקים אלה בגנות גדולי שומרון באים עתה לפרש מקצתם.","נאמר: \u0003\"השכבים על מטות שן וסרחים על ערשתם\u0004 ואוכלים כרים מצאן ועגלים מתוך מרבק\u0003\"\u0004 (עמוס ו, ד). \u0003אמר ר' יוסי בר' חנינא:\u0004 פסוק זה \u0003מלמד\u0004 שחטאם \u0003שהיו משתינין מים בפני מטותיהן ערומים.\u0004","\u0003מגדף בה\u0004 \u0005[לועג,\u0006 דוחה \u0005זאת]\u0006 \u0003ר' אבהו: אי הכי\u0004 \u0005אם כך\u0006 שלשון \"סרוחים\" מלמד על כך, אם כן \u0003היינו דכתיב\u0004 \u0005[זהו\u0006 לכאורה גם פירוש מה \u0005שנאמר]\u0006 \u0003\"לכן עתה יגלו בראש גלים\u0004 וסר מרזח סרוחים\u0003\"\u0004 (עמוס ו, ז), והדבר תמוה, שכן \u0003משום\u0004 ש\u0003משתינין מים בפ ני מטותיהם\u0004 כשהם \u0003ערומים יגלו בראש גולים?!\u0004 שאף שהוא מנהג מגונה, מכל מקום עונש חמור זה ודאי אינו מגיע בשל כך!","\u0003אלא אמר ר' אבהו:\u0004 פסוק זה עוסק בחטא חמור, ויש לומר ש\u0003אלו בני אדם שהיו אוכלים ושותים זה עם זה ודובקין\u0004 (מצמידים) \u0003מטותיהן זו בזו ומחליפין נשותיהן זה עם זה ומסריחין ערסותם\u0004 (מיטותיהם) \u0003בשכבת זרע שאינו שלהן,\u0004 והוא שנאמר: \"וסרוחים על ערשותם\", ובשל עבירות חמורות אלו נענשו ש\"יגלו בראש גולים\".","אגב הדברים שהוזכרו קודם \u0003אמר ר' אבהו, ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים\u0006 כי \u0005בברייתא\u0006 היא \u0005שנויה]:\u0006 \u0003שלושה דברים מביאין את האדם לידי עניות,\u0004 שנענשים עליהן משמים, \u0003ואלו הן\u0004: \u0003המשתין מים בפני מטתו ערום, ו\u0004זה ש\u0003מזלזל בנטילת ידים, ושאשתו מקללתו בפניו.\u0004","ומבארים: \u0003\"המשתין מים בפני מטתו ערום\", אמר רבא: לא אמרן\u0004 \u0005[אמרנו]\u0006 איסור זה \u0003אלא\u0004 בכגון \u0003דמהדר אפיה לפורייה\u0004 \u0005[שמיסב פניו למטתו]\u0006 ומטיל מימיו לעברה, \u0003אבל\u0004 אם מיסב פניו ומטיל מימיו \u0003לבראי\u0004 \u0005[לחוץ]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור חמור כל כך.","\u0003ו\u0004כן גם כאשר הוא \u0003מהדר אפיה לפורייה\u0004 \u0005[מיסב פניו למיטתו]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 איסור זה \u0003אלא\u0004 כאשר מטיל מימיו \u0003לארעא\u0004 \u0005[לארץ],\u0006 \u0003אבל\u0004 כאשר מטיל \u0003מימו במנא\u0004 \u0005[בכלי]\u0006 \u0003— לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור, שאין הדבר מגונה כל כך.","\u0003ו\u0004לענין ה\u0003מזלזל בנטילת ידים, אמר רבא: לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 בכגון שהוא \u0003לא משא ידיה\u0004 \u0005[רוחץ ידיו]\u0006 \u0003כלל, אבל\u0004 אם \u0003משא\u0004 \u0005[רוחץ]\u0006 \u0003ולא משא\u0004 \u0005[רוחץ]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 חשש זה.","ומעירים בגמרא: \u0003ולאו מלתא היא\u0004 \u0005[ואין זה דבר\u0006 נכון\u0005],\u0006 שכן \u0003אמר רב חסדא: אנא משאי\u0004 \u0005[אני רחצתי]\u0006 \u0003מלא חפני מיא\u0004 \u0005[מים]\u0006 \u0003ויהבו\u0004 \u0005[ונתנו]\u0006 \u0003לי מלא חפני טיבותא\u0004 \u0005[טובה],\u0006 ומכאן נלמד שלענין הסגולה שבדבר ראוי להרבות במים.","\u0003ו\u0004על מה שאמרו \u0003שאשתו מקללתו בפניו, אמר רבא:\u0004 מדובר כאן כשמקללתו \u0003על עסקי תכשיטיה,\u0004 שמתאוננת על שאינו נותן לה תכשיטים. ומעירים: \u0003והני מילי הוא דאית ליה ולא עביד\u0004 \u0005[ודברים אלה הם\u0006 דווקא \u0005כשיש לו\u0006 כסף \u0005ואינו עושה]\u0006 עבורה תכשיטים, אבל אם אין לו כסף, אין בכך חשש.","כיון שדובר בחטאים שבימי בית המקדש הראשון מוסיפים לבאר פסוקים אחרים שיש בהם מעין זה. \u0003דרש רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עילאי, מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ויאמר ה' יען כי גבהו בנות ציון\u0004 ותלכנה נטויות גרון ומשקרות עיניים הלוך וטפוף תלכנה וברגליהן תעכסנה\" (ישעיהו ג, טז) — \"יען כי גבהו בנות ציון\" הכוונה: \u0003שהיו מהלכות בקומה זקופה\u0004 ומגביהות עצמן שלא בדרך צניעות. על האמור \u0003\"ותלכנה נטויות גרון\"\u0004 מסביר הוא ש\u0003היו מהלכות\u0004 פסיעות קטנות \u0003עקב בצד גודל,\u0004 כדי להראות עצמן יותר. ו\u0003\"משקרות עינים\"\u0004 — \u0003דהוה מלאן כוחלא לעינייהו ומרמזן\u0004 \u0005[שהיו ממלאות כחול בעיניהן ומרמזות].\u0006 \u0003\"הלוך וטפוף\"\u0004 — \u0003שהיו מהלכות\u0004 העשירות שבהן אשה \u0003ארוכה בצד\u0004 אשה \u0003קצרה\u0004 כדי שתראה הגבוהה יותר בולטת (צפה = טפה) בגובהה. \u0003\"וברגליהן תעכסנה\"\u0004 — \u0003אמר ר' יצחק דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אמי: מלמד שמטילות\u0004 היו בשמי \u0003מור ואפרסמון במנעליהן ומהלכות בשוקי ירושלים, וכיון שמגיעות אצל בחורי ישראל\u0004 היו \u0003בועטות בקרקע ומתיזות עליהם\u0004 מן הבושם \u0003ומכניסות בהן יצר הרע כארס בכעוס\u0004 (של נחש).","\u0003מאי\u0004 \u0005[מה]\u0006 \u0003פורענותיהם\u0004 על חטאים אלה? — \u0003כדדריש\u0004 \u0005[כפי שדרש]\u0006 \u0003רבה בר עולא: \"והיה תחת בשם מק יהיה\u0004 ותחת חגורה נקפה ותחת מעשה מקשה קרחה ותחת פתיגיל מחגרת שק, כי תחת יופי\". (ישעיהו ג, כד), ומפרש: \"והיה תחת בושם מק יהיה\" — \u0003מקום שהיו מתבשמות בו נעשה נמקים נמקים\u0004 (רקבון), \u0003\"ותחת חגורה נקפה\"\u0004 — \u0003מקום שהיו חגורות בצלצול\u0004 (שרוך) \u0003נעשה נקפים נקפים\u0004 (פצעים). \u0003\"ותחת מעשה מקשה קרחה\"\u0004 — \u0003מקום שהיו מתקשטות בו\u0004 בשערן \u0003נעשה קרחים קרחים. \"ותחת פתיגיל מחגרת שק\"\u0004 — \u0003פתחים המביאין לידי גילה\u0004 שהוא הרחבה של המלה \"פתיגיל\", \u0003יהיו למחגרת שק. \"כי תחת יפי\"\u0004 — \u0003אמר רבא: היינו דאמרי אינשי\u0004 \u0005[זה שאומרים בני אדם],\u0006 כפתגם עממי: \u0003חלופי שופרא\u0004 \u0005[במקום יופי]\u0006 — \u0003כיבא\u0004 \u0005[מוגלה].\u0006","ועוד על פסוק אחר: \u0003\"ושפח ה' קדקד בנות ציון\u0004 וה' פתהן יערה \u0003\".\u0004 \"ושיפח ה' קדקד בנות ציון\" — \u0003אמר ר' יוסי בר' חנינא: מלמד שפרחה בהן צרעת.\u0004 וראיה לכך: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"ושפח\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בין סוגי הצרעת: \"ו \u0003לשאת ולספחת\u0004 ולבהרת\u0003\"\u0004 (ויקרא יד, נו).","ובפירוש דברי הכתוב \u0003\"וה' פתהן יערה\"\u0004 נחלקו \u0003רב ושמואל, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: שנשפכו,\u0004 כלומר, שפכו דם \u0003כקיתון. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: שנעשו פתחיהן\u0004 (ערוותן) מלאים שער \u0003כיער.\u0004","וכיון שדובר בחטאי ירושלים ובשפע שהיה בה קודם חורבנה, \u0003אמר ר' יהודה\u0004 שכך \u0003אמר רב: אנשי ירושלים אנשי שחץ\u0004 (גסות) \u0003היו. אדם אומר לחברו: במה סעדת היום? בפת עמילה\u0004 (שנילושה יפה), \u0003או בפת שאינה עמילה? ביין גורדלי\u0004 (שהיה לבן), \u0003או\u0004"],["\u0003ביין חרדלי\u0004 \u0005[שהיה שחור]?\u0006 \u0003במסב\u0004 (מטה לשבת עליה) \u0003רחב, או במסב קצר\u0004 (צר)? \u0003בחבר טוב, או בחבר רע?\u0004 ו\u0003אמר רב חסדא: וכולן\u0004 רמז הם \u0003לזנות.\u0004 שבכל אלה רמזו לענייני נשים מסוגים שונים. ש\"פת עמילה\" משמעו — בעולה, \"יין גורדלי\" — נערה בהירה, \"מסב רחב\" — אשה שמנה.","וכיון שדובר בירושלים, \u0003אמר רחבה\u0004 שכך \u0003אמר ר' יהודה: עצי ירושלים של קינמון היו, ובשעה שהיו מסיקין מהם ריחן\u0004 היה \u0003נודף בכל ארץ ישראל. ומשחרבה ירושלים נגנזו\u0004 עצי בושם אלה, \u0003ולא נשתייר\u0004 מהם \u0003אלא כשעורה, ומשתכח בגזאי דצימצמאי מלכתא\u0004 \u0005[ונמצא באוצר המלכה צימצמאי].\u0006","כשם שיש דברים המיוחדים לאשה שאסור לה להוציאם, כך אמרו ש\u0003לא יצא האיש\u0004 בשבת \u0003לא בסייף\u0004 (בחרב) \u0003ולא בקשת ולא בתריס\u0004 (מגן) \u0003ולא באלה ולא ברומח. ואם יצא\u0004 באחד מכלים אלה לרשות הרבים — \u0003חייב חטאת.\u0004","\u0003ר' אליעזר אומר:\u0004 כלי נשק אצל האיש \u0003תכשיטין הן לו,\u0004 וכשם שמותר לאיש לצאת בתכשיטים אחרים, מותר לו לצאת בכלי נשק.","\u0003וחכמים אומרים:\u0004 כלי נשק \u0003אינן אלא לגנאי\u0004 ועתידים להתבטל לעתיד לבוא, וכפי \u0003שנאמר: \"וכתתו חרבותם לאתים וחניתותיהם למזמרות לא ישא גוי אל גוי חרב ולא ילמדו עוד מלחמה\"\u0004 (ישעיהו ב, ד).","ובענין תכשיטי נשים הוסיפו שה\u0003בירית\u0004 ששמים על הרגל להחזיק את הגרביים הריהי \u0003טהורה\u0004 מלקבל טומאה ככלי, \u0003ו\u0004אף \u0003יוצאין בה בשבת.\u0004","ואילו ה\u0003כבלים\u0004 שאף הם היו מתכשיטי נשים — הריהם \u0003טמאים\u0004 (מקבלים טומאה), \u0003ואין יוצאין בהן בשבת .\u0004","מתחילה באים לברר פירושה של מלה שהוזכרה, ומסבירים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"אלה\"\u0004 זו — הוא המקל הקרוי \u0003\"קולפא\".\u0004","שנינו במשנה ש\u0003ר' אליעזר אומר\u0004 שכלי נשק \u0003תכשיטין הן לו\u0004 לאיש. \u0003תניא\u0004 \u0005[שנויא\u0006 ברייתא\u0005]\u0006 העוסקת בענין זה בהרחבה: \u0003אמרו לו\u0004 חכמים \u0003לר' אליעזר: וכי מאחר\u0004 ש\u0003תכשיטין הן לו,\u0004 לדעתך \u0003מפני מה הן בטלין לימות המשיח? אמר להן\u0004 ר' אליעזר: לא מפני שאינם לנוי אלא \u0003לפי שאינן צריכים\u0004 עוד באותו זמן, וכפי \u0003שנאמר\u0004 שם: \u0003\"לא ישא גוי אל גוי חרב \"\u0004ולכן לא ינהגו עוד בסוג זה של תכשיט. ושואלים: \u0003ותהוי\u0004 \u0005[ושיהיה]\u0006 הנשק \u0003לנוי בעלמא\u0004 \u0005[בלבד],\u0006 שאף שלא ישתמשו בנשק לצורך מלחמה, ישתמשו בו לנוי! \u0003אמר אביי: מידי דהוה אשרגא בטיהרא\u0004 \u0005[כדרך שהוא\u0006 ביחס \u0005לנר בצהרים],\u0006 שכיון שאין נזקקים לאורו, אף איננו משמש לנוי. וכן כלי נשק, כאשר אינם נחוצים לתפקידם, אינם משמשים עוד לנוי.","\u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 ברייתא זו על דעת \u0003שמואל.\u0004 ש\u0003אמר שמואל: אין בין העולם הזה לימות המשיח אלא שיעבוד גליות בלבד\u0004 שיסור מישראל, אבל סדרי העולם בכל שאר התחומים ישארו כמו שהם, וכפי \u0003שנאמר: \"כי לא יחדל אביון מקרב הארץ\"\u0004 (דברים טו, יא), שאף סדרי החברה לא ישתנו, ויהיו מלחמות בעולם.","וברייתא זו \u0003מסייע ליה\u0004 \u0005[מסייעת לו\u0006 לשיטתו\u0005]\u0006 של \u0003ר' חייא בר אבא\u0004 השונה משל שמואל. ש\u0003אמר ר' חייא בר אבא: כל הנביאים לא נתנבאו אלא לימות המשיח\u0004 ולזמן זה נאמרו בשורותיהם, \u0003אבל לעולם הבא\u0004 כבר נאמר: \u0003\"עין לא ראתה אלהים זולתך\u0004 יעשה למחכה לו\u0003\"\u0004 (ישעיהו סד, ג), ומה שיהא בעולם הבא אינו ניתן לתיאור אפילו בדרך הנבואה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]\u0006 שמחלוקת ר' אליעזר וחכמים היתה באופן שונה במקצת: \u0003אמרו לו\u0004 חכמים \u0003לר' אליעזר: וכי מאחר\u0004 ש\u0003תכשיטין הן לו,\u0004 לדעתך \u0003מפני מה הן בטלים לימות המשיח? אמר להן\u0004 ר' אליעזר: \u0003אף לימות המשיח אינן בטלין.\u0004 ו\u0003היינו\u0004 \u0005[זהו]\u0006 מעין הרעיון של \u0003שמואל\u0004 שלא ישתנה העולם, \u0003ופליגא\u0004 \u0005[וחלוק]\u0006 הוא על \u0003ר' חייא בר אבא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב דימי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003לרב אויא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יוסף לרב דימי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת רב יוסף \u0003לרב אויא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003אביי לרב יוסף: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר\u0004 ש\u0003אמר\u0004 שכלי נשק \u0003תכשיטין הן לו\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"חגור חרבך על ירך גבור הודך והדרך\"\u0004 (תהילים מה, ד), הרי שהחרב נחשבת כקישוט.","מסופר שלאחר זמן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא למר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא:\u0004 וכי הוכחה היא זו? והלא \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003בדברי תורה כתיב\u0004 \u0005[נאמר]\u0006 וכוונתו סמלית! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אף על פי כן \u0003אין מקרא יוצא מידי פשוטו,\u0004 ואף שניתן להידרש בדרכים שונות, אין לעוקרו לגמרי ממשמעותו הפשוטה.","ו\u0003אמר רב כהנא\u0004 על כך: \u0003כד הוינא בר תמני סרי שנין והוה גמירנא ליה לכוליה תלמודא,\u0004 \u0005[כאשר הייתי בן שמונה עשרה שנה ולמדתי\u0006 כבר \u0005את כל התלמוד],\u0006 \u0003ו\u0004עם כל זה \u0003לא הוה ידענא\u0004 \u0005[ידעתי]\u0006 ש\u0003אין מקרא יוצא מידי פשוטו עד השתא\u0004 \u0005[עכשיו].\u0006 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 רב כהנא כשסיפר זאת? ומשיבים: בא ללמדנו \u0003דליגמר איניש והדר ליסבר\u0004 \u0005[שילמד אדם\u0006 תחילה, \u0005ואחר כך\u0006 ישתדל \u0005להבין].\u0006","\u0003סימן \"זרות\".\u0004 אותו פסוק שנאמר בתהלים והובא קודם נקרש כאן בכמה פנים.","ש\u0003אמר ר' ירמיה\u0004 שכך \u0003אמר ר' אלעזר: שני תלמידי חכמים המחדדין זה\u0004 את \u0003זה בהלכה הקדוש ברוך הוא מצליח להם,\u0004 וכפי \u0003שנאמר: \"והדרך צלח\u0004 רכב על דבר אמת וענוה צדק ותורך נוראות ימינך\u0003\"\u0004 (תהלים מה, \u0005ה), ואמרו חכמים:\u0006 \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"והדרך\" אלא\u0004 בשינוי מבטא האותיות וצורתן \u0003\"וחדדך\",\u0004 לומר שהמחודד סופו שמצליח. \u0003ולא עוד אלא ש\u0004אותם הנוהגים כן \u0003עולין לגדולה,\u0004 וכפי \u0003שנאמר: \"צלח רכב\". יכול אפילו\u0004 אם למדו \u0003שלא לשמה\u0004 — \u0003תלמוד לומר: \"על דבר אמת \".\u0004 יכול יצליח ה' דרכו אפילו \u0003אם הגיס דעתו\u0004 (התגאה) — \u0003תלמוד לומר: \"וענוה צדק\". ואם עושין כן\u0004 כראוי \u0003— זוכין לתורה שניתנה בימין\u0004 של הקדוש ברוך הוא, וכפי \u0003שנאמר: \"ותורך נוראות ימינך\".\u0004","\u0003רב נחמן בר יצחק אמר: זוכין לדברים שנאמרו בימינה של תורה.\u0004 וכפי ש\u0003אמר רבא בר רב שילא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב יוסף בר חמא\u0004 שכך \u0003אמר רב ששת: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ארך ימים בימינה בשמאלה עשר וכבוד\"\u0004 (משלי ג, טז), שכן הדבר תמוה: \u0003אלא בימינה ארך ימים איכא\u0004 \u0005[יש],\u0006 ואילו \u0003עושר וכבוד ליכא\u0004 \u0005[אין]?\u0006 \u0003אלא\u0004 יש להבין זאת כך: \u0003למיימינין בה,\u0004 העוסקים בתורה לשמה ובכוונת הלב — \u0003אורך ימים איכא\u0004 \u0005[יש]\u0006 להם, \u0003וכל שכן\u0004 שיש להם \u0003עושר וכבוד.\u0004 ואילו \u0003למשמאילים בה\u0004 — \u0003עושר וכבוד איכא\u0004 \u0005[יש]\u0006 להם, \u0003ואולם אורך ימים ליכא\u0004 \u0005[אין]\u0006 להם.","\u0003אמר ר' ירמיה\u0004 שכך \u0003אמר ר' שמעון בן לקיש: שני תלמידי חכמים הנוחין זה לזה בהלכה הקדוש ברוך הוא מקשיב להן, שנאמר: \"אז נדברו יראי ה'\u0004 איש אל רעהו ויקשב ה' וישמע \u0003ויכתב ספר זכרון לפניו ליראי ה' ולחושבי שמו\"\u0004 (מלאכי ג, טז) ו\u0003אין\u0004 משמעות לשון \u0003\"דיבור\" אלא נחת, שנאמר: \"ידבר עמים תחתינו\"\u0004 (תהלים מז, ד), שמשעמו שיכניע, ישקיט את העמים תחת עם ישראל, ואף כאן \"דיבור\" משמעו בבהכנעה ובנחת.","וכיון שנדרש חלק מהפסוק, שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות \u0003\"ולחושבי שמו \"? אמר ר' אמי:\u0004 לומר \u0003שאפילו\u0004 אם רק \u0003חישב לעשות מצוה, ו\u0004בסופו של דבר \u0003נאנס ולא עשאה, מעלה עליו הכתוב כאילו עשאה.\u0004","ועוד בשבחם של בעלי מצוות \u0003אמר רב חיננא בר אידי: כל העושה מצוה כמאמרה\u0004 (כראוי) \u0003אין מבשרין אותו בשורות רעות, שנאמר: \"שומר מצוה לא ידע דבר רע\"\u0004 (קהלת ח, ה)\u0003.\u0004","והוסיף ו\u0003אמר רב אסי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חנינא: אפילו הקדוש ברוך הוא גוזר גזירה\u0004 — \u0003הוא מבטלה,\u0004 וכפי \u0003שנאמר: \"באשר דבר מלך שלטון ומי יאמר לו מה תעשה\"\u0004 (קהלת ח, ד), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 שאף שדבר מלך, הוא הקדוש ברוך הוא גוזר גזירה מכל מקום \u0003\"שומר מצוה לא ידע דבר רע\"\u0004 (קהלת ח, ה), ששומר המצוה יכול לבטל דבר זה ולא ידע דבר רע\".","\u0003אמר ר' אבא\u0004 שכך \u0003אמר ר' שמעון בן לקיש: שני תלמידי חכמים המקשיבים זה לזה בהלכה הקדוש ברוך הוא שומע לקולן, שנאמר: \"היושבת בגנים חברים מקשיבים לקולך השמיעני\"\u0004 (שיר השירים ח, יג),","\u0003ואם אין עושין כן,\u0004 שאינם מקשיבים זה לזה — הריהם \u0003גורמין\u0004 בכך \u0003לשכינה שמסתלקת מישראל, שנאמר: \"ברח דודי ודמה\u0004 לך לצבי או לעופר האילים על הרי בשמים\u0003\"\u0004 (שיר השירים ח, יד).","\u0003אמר ר' אבא\u0004 שכך \u0003אמר ר' שמעון בן לקיש: שני תלמידי חכמים\u0004 בודדים \u0003המדגילים\u0004 \u0005[המשבשים,\u0006 מטעים, (תוספות)\u0005]\u0006 \u0003זה לזה בהלכה\u0004 בכל זאת \u0003הקדוש ברוך הוא אוהבם, שנאמר: \"ודגלו עלי אהבה\"\u0004 (שיר השירים ב, ד). \u0003אמר רבא: והוא\u0004 דווקא בכגון \u0003דידעי צורתא דשמעתא\u0004 \u0005[ש\u0006הם \u0005יודעים\u0006 את \u0005יסוד ההלכה]\u0006 וטעותם נובעת מחסרון ידיעה מתקדמת יותר. \u0003והוא\u0004 דווקא בכגון \u0003דלית להו רבה במתא למיגמר מיניה\u0004 \u0005[שאין להם\u0006 אדם \u0005גדול בעיר ללמוד ממנו].\u0006","\u0005ועוד\u0006 \u0003אמר ר' אבא\u0004 שכך \u0003אמר ר' שמעון בן לקיש: גדול המלוה\u0004 לחבירו כסף \u0003יותר מן העושה צדקה. ו\u0004זה ה\u0003מטיל בכיס,\u0004 שנותן כספים לאדם הנזקק לכך ועושה עמו שותפות \u0003יותר מכולם,\u0004 כיון שאז אין המקבל מתבייש בקבלת החסד.","ועוד \u0003אמר ר' אבא\u0004 שכך \u0003אמר ר' שמעון בן לקיש: אם תלמיד חכם נוקם ונוטר כנחש הוא,\u0004 בכל זאת \u0003חגריהו על מתניך,\u0004 שיש בידו לפחות זכות התורה. ולהיפך, \u0003אם עם הארץ הוא חסיד\u0004 בכל זאת \u0003אל תדור בשכונתו,\u0004 שאינו יוצא מגדר עם הארץ למרות חסידותו.","ו\u0003אמר רב כהנא\u0004 שכך \u0003אמר ר' שמעון בן לקיש, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אסי\u0004 שכך \u0003אמר ריש לקיש, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' אבא\u0004 שכך \u0003אמר ר' שמעון בן לקיש: כל המגדל כלב רע בתוך ביתו\u0004 הרי בכך הוא \u0003מונע חסד מתוך ביתו,\u0004 שחוששים עניים להכנס לביתו, וכפי \u0003שנאמר: \"למס\u0004"],["\u0003מרעהו חסד\u0004 ויראת שדי יעזוב\u0003\"\u0004 (איוב ו, יד), \u0003שכן בלשון יונית קוראין לכלב \"למס\". רב נחמן בר יצחק אמר:\u0004 המחזיק כלב רע \u0003אף פורק ממנו יראת שמים,\u0004 וכפי \u0003שנאמר\u0004 בסוף אותו פסוק \u0003\"ויראת שדי יעזוב\".\u0004","ומסופר: \u0003ההיא איתתא דעיילא לההוא ביתא למיפא\u0004 \u0005[אשה אחת\u0006 שהיתה הרה \u0005נכנסה לבית אחד לאפות]\u0006 בתנור שבאותו בית. \u0003נבח בה כלבא\u0004 \u0005[כלב]\u0006 שהיה באותו בית, \u0003איתעקר\u0004 \u0005[\u0006ו\u0005נעקר]\u0006 \u0003ולדה. אמר לה מרי דביתא\u0004 \u0005[בעל\u0006 \u0003הבית]: לא תידחלי, דשקילי ניביה ושקילין טופריה\u0004 \u0005[אל תפחדי, שניטלו שיניו וניטלו צפרניו].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003שקולא טיבותיך ושדיא אחיזרי\u0004 \u0005[נטולה טובתך וזרוקה על הקוצים],\u0006 כלומר, עתה כבר אין תועלת בדברי העידוד שלך כי \u0003כבר נד\u0004 ה\u0003ולד\u0004 ממקומו וימות.","בקשר לדברים שנאמרו קודם מביאים את מה ש\u0003אמר רב הונא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"שמח בחור בילדותך ויטיבך לבך בימי בחורותיך והלך בדרכי לבך ובמראה עיניך ודע כי על כל אלה יביאך האלהים במשפט\"\u0004 (קהלת יא, ט) — \u0003עד כאן,\u0004 כלומר, עד המלה \"ודע\" — \u0003דברי יצר הרע, מכאן ואילך\u0004 הם \u0003דברי\u0004 ה\u0003יצר\u0004 ה\u0003טוב.\u0004","\u0003ריש לקיש אמר: עד כאן לדברי תורה,\u0004 שנותנים לאדם ללמוד ולעסוק בתורה ולשמוח בחידושיה, \u0003מכאן ואילך\u0004 \"ודע כי על כל אלה יביאך האלהים במשפט\" הוא \u0003למעשים טובים,\u0004 שעתיד אדם לתת את הדין אם למד דבר ולא קיימו.","שנינו במשנה שה\u0003בירית טהורה\u0004 (אינה מקבלת טומאה). \u0003אמר רב יהודה: בירית זו אצעדה\u0004 (צמיד שעל הזרוע).","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב יוסף:\u0004 הרי נאמר כאן ש\u0003בירית טהורה ויוצא בה בשבת, ואילו אצעדה טמאה היא,\u0004 כפי שאכן נאמר בכתוב במפורש בענין השלל אשר ניטל מהמדיינים \"ונקרב את קרבן ה' איש אשר מצא כלי זהב\" וכו' (במדבר לא, נא) ולפני כן נאמר ביחס לדברים הניטלים כשלל \"תתחטאו ביום השלישי וביום השביעי אתם ושביכם\" (במדבר לא, יט), והרי שאצעדה היא מהדברים המקבלים טומאה!","אלא \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 התכוון לומר\u0005]:\u0006 \u0003בירית\u0004 ברגל \u0003תחת\u0004 (במקום) \u0003אצעדה\u0004 בזרוע היא \u0003עומדת,\u0004 שתפקידה ברגל להחזיק את הגרביים דומה לזה של האצעדה בזרוע, ואינה תכשיט המקבל טומאה, ואינה אלא כמשמשת את הגרביים, וטהורה.","מסופר: \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003רבין ורב הונא קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' ירמיה, ויתיב\u0004 \u0005[וישב]\u0006 \u0003ר' ירמיה וקא\u0004 \u0005[והיה]\u0006 \u0003מנמנם,\u0004 וכיון שנמנם שוחחו תלמידיו אלה ביניהם. \u0003ויתיב\u0004 \u0005[וישב]\u0006 \u0003רבין וקאמר\u0004 \u0005[ואמר]:\u0006 מה ההבדל בין הבירית והכבלים — ש\u0003בירית ב\u0004רגל \u0003אחת,\u0004 ו\u0003כבלים בשתים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא\u0004: \u0003אלו ואלו,\u0004 גם הבירית וגם הכבלים, \u0003בשתים,\u0004 וההבדל הוא כאשר יש ביריות \u0003ומטילין שלשלת ביניהן ונעשו כבלים.\u0004","ושואל רבין: \u0003ו\u0004כי ה\u0003שלשלת שבו משויא ליה מנא\u0004 \u0005[עושה אותו לכלי]?\u0006 שאם בלא השלשלת אין הביריות נחשבות ככלי, מדוע תיחשבנה בתוספת שלשלת לכלי המקבל טומאה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שטעם הדבר הוא \u0003כר' שמואל בר נחמני,\u0004 ש\u0003אמר ר' שמואל בר נחמני\u0004 שכך \u0003אמר ר' יוחנן: מניין למשמיע קול\u0004 (כלי שמלאכתו להשמיע קול) \u0003בכלי מתכות שהוא טמא\u0004 (מקבל טומאה) כתורת כלי — \u0003שנאמר\u0004 בדיני טומאת כלים: \u0003\"כל דבר אשר יבא באש\u0004 תעבירו באש וטהר\u0003\"\u0004 (במדבר לא, כג), ומלשון \"דבר\" למדו כי \u0003אפילו דיבור במשמע,\u0004 שכלי שמשמיע קול (\"דיבור\") אף הוא טמא.","ואולם אין הדבר דומה, כי \u0003בשלמא התם\u0004 \u0005[נניח שם]\u0006 — \u0003קא בעו לה לקלא, וקעביד\u0004 \u0005[צריכים אותו,\u0006 את הכלי \u0005ל\u0006צורך \u0005קולו והוא עושה]\u0006 \u0003מעשה,\u0004 ואולם \u0003הכא מאי\u0004 \u0005[מה,\u0006 איזה\u0005]\u0006 \u0003מעשה קעביד\u0004 \u0005[היא\u0006 השלשלת \u0005עושה]?\u0006 שאמנם היא משמיעה קול, ואולם אינה משמשת לצורך כלשהו!","אמר לו: \u0003הכא נמי קעביד\u0004 \u0005[כאן גם כן היא\u0006 השלשלת \u0005עושה]\u0006 \u0003מעשה\u0004 לתועלת, וכפי ש\u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר ר' יוחנן: משפחה אחת היתה בירושלים שהיו פסיעותיהן\u0004 של בנותיה \u0003גסות\u0004 (גדולות) \u0003והיו בתולותיהן נושרות,\u0004 וכדי לפתור בעיה זו \u0003עשו להן כבלים והטילו שלשלת ביניהן\u0004 כדי \u0003שלא יהיו פסיעותיהן גסות ו\u0004אכן לאחר מכן \u0003לא היו בתולותיהן נושרות.\u0004 בינתיים \u0003איתער בהו\u0004 \u0005[התעורר בהם,\u0006 מקולם\u0005]\u0006 \u0003ר' ירמיה\u0004 ו\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003יישר\u0004 (נכון), יפה אמרתם, \u0003וכן אמר ר' יוחנן\u0004 בענין זה.","כיון שדובר בכמה ענייני טומאה, מסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: מניין לאריג\u0004 בגודל \u0003כל שהוא שהוא טמא\u0004 (מקבל טומאה), שאין לכך שיעור מסויים — למדים הלכה זו \u0003מ\u0004ן ה\u0003ציץ\u0004 של הכהן הגדול, הנחשב למרות קטנותו לכלי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ו\u0004כי \u0003ציץ אריג הוא?! והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ציץ\u0004 עשוי \u0003כמין טס\u0004 (חתיכה חלקה) \u0003של זהב, ורוחב\u0004 הציץ \u0003שתי אצבעות, ומוקף\u0004 (מונח על המצח בהיקף הראש) \u0003מאוזן לאוזן, וכתוב עליו בשתי שיטין\u0004 (שורות) \u0003\"יו\"ד ה\"א\"\u0004 (שם הויה) \u0003למעלה ו\"קודש למ\"ד\" למטה.\u0004 שעל הציץ צריך לחקוק \"קודש לה'\", וכדי לכבד את השם היו כותבים אותו גבוה יותר מאשר המלה \"קודש\".","\u0003ואמר ר' אליעזר בר' יוסי: אני ראיתיו\u0004 באוצר הקיסר \u0003בעיר רומי וכתוב\u0004 עליו \u0003\"קודש לה'\" בשיטה\u0004 (שורה) \u0003אחת.\u0004 ועל כל פנים אחר שהציץ הוא טס של זהב כיצד אפשר להביא ראיה ממנו לדיני אריג!","\u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003רב דימי לנהרדעא שלח להו\u0004 \u0005[להם]\u0006 לבני הישיבה: \u0003דברים שאמרתי לכם\u0004 בענין אריג שהוא מקבל טומאה בכלשהו \u0003טעות הם בידי, ברם\u0004 (אבל) \u0003כך אמרו משום\u0004 (בשם) \u0003ר' יוחנן: מניין לתכשיט כל שהוא שהוא טמא\u0004 (מקבל טומאה) — נלמד הדבר \u0003מ\u0004ן ה\u0003ציץ. ומניין לאריג כל שהוא שהוא טמא\u0004 — ממה שנאמר: \u0003\"או בגד\u0004 או עור או שק כל כלי אשר יעשה מלאכה בהם במים יובא וטמא עד הערב וטהר\u0003\"\u0004 (ויקרא יא, לב) ומלשון הריבוי של \"או בגד\" למדים שכל בגד, אפילו קטן ביותר, נכנס בהגדרה זו.","בדומה לזו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אריג כל שהוא\u0004 — \u0003טמא, ותכשיט כל שהוא\u0004 — \u0003טמא.\u0004 דבר שחציו \u0003אריג ו\u0004חציו \u0003תכשיט כל שהוא\u0004 — \u0003טמא.\u0004 ו\u0003מוסף\u0004 גם ה\u0003שק על הבגד ש\u0004אף הוא \u0003טמא משום אריג.\u0004","\u0003אמר רבא\u0004 בביאור דברי הברייתא: \u0003אריג כל שהוא טמא,\u0004 — \u0003מ\u0004מה שנאמר \u0003\"או בגד\", תכשיט כל שהוא\u0004 — \u0003טמא,\u0004 ונלמדת ההלכה \u0003מ\u0004דין \u0003ציץ. אריג ותכשיט כל שהוא\u0004 — \u0003טמא,\u0004 ודבר זה נלמד \u0003מ\u0004מה שנאמר: \u0003\"\u0004ויקח משה ואלעזר הכהן את הזהב מאתם \u0003כל כלי מעשה\"\u0004 (במדבר לא, נא), וכל חפץ, כיון שמשמש הוא למעשה כלשהו, נכנס להגדרה של \"כל כלי מעשה\".","\u0003אמר ליה ההוא מרבנן\u0004 \u0005[לו אחד החכמים]\u0006 \u0003לרבא:\u0004 והלא אותו מקרא \u0003במדין כתיב\u0004 \u0005[נאמר],\u0006 ושם דובר רק בדיני טומאת מת, וכיצד לומד אתה מכאן לדיני טומאה בכלל?","\u0003אמר ליה גמר\u0004 \u0005[למד]\u0006 בדרך גזירה שווה"],["\u0003\"כלי\" \"כלי\" מהתם\u0004 \u0005[משם],\u0006 שגם בדיני מת וגם בדיני טומאות אחרות נזכרה המלה \"כלי\", ואנו למדים הלכה מהלכה.","שנינו בברייתא הקודמת ש\u0003מוסף שק על הבגד שטמא משום אריג.\u0004 ותוהים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003בגד לאו\u0004 \u0005[לא]\u0006 \u0003אריג הוא?!\u0004 אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 כך יש לתקן ולומר: \u0003מוסף\u0004 דין ה\u0003שק\u0004 העשוי משערות עזים \u0003על הבגד,\u0004 ש\u0003אף על פי שאינו אריג\u0004 — הריהו \u0003טמא.\u0004 ושואלים: דבר העשוי משערות עזים ואפילו בלתי ארוג, \u0003למאי חזי\u0004 \u0005[למה ראוי]?\u0006 \u0003אמר ר' יוחנן: שכן עני קולע שלש נימין\u0004 (שערות) עזים \u0003ותולה בצואר בתו\u0004 לקישוט.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת מדרש הלכה מפורט בענין אותו כתוב. מה שנאמר \u0003\"שק\" אין לי\u0004 ללמוד מכך \u0003אלא\u0004 ש\u0003שק\u0004 שלם יקבל טומאה, \u0003מניין לרבות\u0004 לקבלת טומאה אף \u0003את הקילקלי\u0004 (מושכות) \u0003ואת החבק\u0004 (רצועה שקושרים לסוס תחת בטנו) — \u0003תלמוד לומר: \"או שק\",\u0004 שבאה המלה \"או\" ללמדנו שאין המדובר רק בשק, אלא אף בדברים אחרים הדומים לו. \u0003יכול שאני מרבה\u0004 על ידי הוספה זו אף \u0003את החבלים ואת המשיחות\u0004 (חבלים דקים) — \u0003תלמוד לומר: \"שק\".\u0004 ואנו למדים: \u0003מה שק\u0004 הינו \u0003טווי ואריג\u0004 — \u0003אף כל\u0004 שהוא \u0003טווי ואריג,\u0004 והחבלים והמשיחות אינם עשויים מחוטים טוויים, וודאי שאינם ארוגים.","\u0003הרי הוא אומר ב\u0004דיני טומאת מת: \u0003\"\u0004וכל בגד \u0003וכל כלי עור וכל מעשה עזים\u0004 וכל כלי עץ \u0003תתחטאו\"\u0004 (במדבר לא, כ) ובא הפסוק \u0003לרבות\u0004 לקבלת טומאה גם את \u0003הקילקלי ואת החבק\u0004 שאף הם בכלל מעשה עיזים.","\u0003יכול שאני מרבה אף את החבלים ואת המשיחות\u0004 שאף הם מעשי עיזים? ודנים תחילה בדרך סברה: \u0003ודין הוא\u0004 שלא יהיה החבל טמא, שכן \u0003טימא\u0004 הכתוב דבר הנוגע \u0003בשרץ, וטימא\u0004 דבר הנוגע \u0003במת.\u0004 ו\u0003מה כשטימא בשרץ לא טימא אלא\u0004 את ה\u0003טווי ואריג\u0004 כפי שאמרנו, \u0003אף כשטימא במת לא טימא אלא\u0004 את ה\u0003טווי ואריג.\u0004","ואולם אפשר לדחות: \u0003הן\u0004 (אמנם) \u0003אם היקל בטמא שרץ שהיא\u0004 טומאה \u0003קלה\u0004 ואמר שבה אין החבלים מקבלים טומאה, האם \u0003נקיל\u0004 גם \u0003בטומאת המת שהיא חמורה?!\u0004 ושמא כיון שטומאת מת חמורה יותר, יטמא בה אף דבר שאיננו טווי וארוג ובכלל זה אף החבלים — \u0003תלמוד לומר\u0004 המילים \u0003\"בגד\" ו\"עור\", \"בגד\" ו\"עור\" לגזירה שוה,\u0004 שילמד אחד על חבירו. ש\u0003נאמר \"בגד\" ו\"עור\" ב\u0004טומאת \u0003שרץ\u0004 (\"וכל אשר יפול עליו מהם במותם יטמאו מכל כלי עץ או בגד או עור או שק כל כלי אשר יעשה מלאכה בהם במים יובא וטמא עד הערב וטהר\".","ויקרא יא, לב), \u0003ונאמר \"בגד\" ו\"עור\" ו\u0004כן \u0003נאמר \"בגד\" ו\"עור\" ב\u0004טומאת \u0003מת.\u0004 ואנו למדים: \u0003מה בגד ועור האמור ב\u0004טומאת \u0003שרץ לא טימא\u0004 אותם \u0003אלא\u0004 כאשר הם \u0003טווי ואריג, אף בגד ועור האמור ב\u0004טומאת \u0003מת לא טימא אלא\u0004 כאשר \u0003הם טווי ואריג.\u0004","ועל ידי גזירה שווה זו אפשר להמשיך ולומר: \u0003ומה בגד ועור האמור במת טמא כל\u0004 שהוא \u0003מעשה עזים\u0004 — \u0003אף בגד ועור האמור בשרץ טמא כל\u0004 שהוא \u0003מעשה עזים.\u0004","\u0003אין לי\u0004 ללמוד מגזירה שווה זו לקבלת טומאה \u0003אלא דבר הבא מן העזים\u0004 בלבד, \u0003מנין לרבות דבר הבא\u0004 (שנעשה) \u0003מזנב הסוס ומזנב הפרה\u0004 שאף הוא מקבל טומאה? — \u0003תלמוד לומר: \"או שק\",\u0004 כלומר, שק וכל הדומה לו, ובכלל זה גם העשוי מזנב הסוס וזנב הפרה.","על כך תוהים: \u0003והא אפיקתיה\u0004 \u0005[והרי הוצאת אותו,\u0006 השתמשת בו\u0005],\u0006 בריבוי זה ללמוד \u0003ל\u0004טומאת \u0003קילקלי וחבק,\u0004 וכיצד ניתן ללמוד מכאן לענין זנב סוס ופרה?","ומשיבים: \u0003הני מילי מקמי דליתיה\u0004 \u0005[דברים אלו\u0006 אמרנו \u0005לפני שבאה]\u0006 ה\u0003גזרה שוה, השתא דאתי\u0004 \u0005[עכשיו שבאה]\u0006 ה\u0003גזירה שווה אייתור ליה\u0004 \u0005[נעשו מיותרים],\u0006 שמן המילים \"וכל מעשה עזים\" למדים לכל דבר הנעשה משערות עזים (כמו החבק), ושוב אין צורך ללמוד זאת מריבוי \"או שק\", ומשום כך משמשת לשון ריבוי זו לענין אחר, לדבר הנעשה מזנב הסוס או הפרה.","וממשיכים במדרש ההלכה: \u0003ואין לי אלא\u0004 שהעשוי מזנב סוס נטמא \u0003בשרץ,\u0004 ואולם \u0003בטומאת מת מניין\u0004 שדבר העשוי מהם נטמא\u0003?\u0004","ומתחילה רוצים להוכיח מסברה: \u0003ודין הוא\u0004 שיהא כן, שכן \u0003טימא במת וטימא בשרץ, מה כשטימא בשרץ עשה דבר הבא מזנב הסוס ומזנב הפרה\u0004 שהוא מקבל טומאה \u0003כ\u0004דבר העשוי \u0003מעשה עזים, אף כשטימא במת עשה דבר הבא מזנב הסוס ומזנב הפרה כמעשה עזים.\u0004","ודוחים: \u0003הן\u0004 (אמנם) \u0003אם הרבה\u0004 הכתוב והוסיף פרטים נוספים \u0003בטומאת ערב\u0004 כטומאת שרץ, שהטמא בה טובל קרוב לערב ונטהר — \u0003שהיא מרובה,\u0004 כי רוב הטומאות האחרות הן טומאות מסוג זה, ומן הדין אם כן אף להרבות בה פרטים כדבר הבא מזנב הסוס או הפרה, ואולם האם \u0003נרבה\u0004 אותם דברים אף \u0003בטומאת שבעה שהיא מועטת,\u0004 שאינה אלא במגע המת?!","אלא \u0003תלמוד לומר \"בגד\" ו\"עור\" \"בגד\" ו\"עור\" ל\u0004לימוד בדרך \u0003גזירה שוה.\u0004 וכך יש ללמוד: \u0003נאמר \"בגד\" ו\"עור\" ב\u0004טומאת \u0003שרץ ונאמר \"בגד\" ו\"עור\" ב\u0004טומאת \u0003מת, מה \"בגד\" ו\"עור\" האמור בשרץ עשה\u0004 הכתוב \u0003דבר הבא מזנב הסוס ומזנב הפרה\u0004 לענין קבלת טומאה \u0003כמעשה עזים, אף \"בגד\" ו\"עור\" האמור במת\u0004 מלמדנו ש\u0003עשה\u0004 הכתוב \u0003דבר הבא מזנב הסוס ומזנב הפרה כמעשה עזים.\u0004","ומעירים: \u0003ו\u0004חייבים לומר שבשני הפסוקים הללו המילים \"בגד\" ו\"עור\" הן \u0003מופנה.\u0004 כלומר, אינן צריכות לעניינן ולא באו אלא כדי ללמוד מהן להשוואה זו, שכן גזירה שווה הסומכת על ביטויים שיש להם משמעות רק לצורך גזירה שווה אינה ניתנת לפירכה בדרך הגיונית. \u0003דאי לאו\u0004 \u0005[שאם\u0006 מילים אלה \u0005לא]\u0006 \u0003מופנה\u0004 הן אפשר לדון בהשוואה על פי ההגיון, ו\u0003איכא למיפרך\u0004 \u0005[יש אפשרות לפרוך,\u0006 להקשות\u0005]\u0006 על ההשוואה \u0005כך:\u0006 \u0003מה לשרץ\u0004 שאתה לומד ממנו, הלא חמור הוא, \u0003שכן מטמא\u0004 הוא אף \u0003ב\u0004שיעור קטן \u0003כעדשה,\u0004 מה שאין כן במת שאינו מטמא אלא בכזית ממנו,","אלא ודאי \u0003לאי אפנויי מופני\u0004 \u0005[שהוא מופנה].\u0006 ומוכיחים שאכן מילים אלה מופנות לצורך ההשוואה בלבד: \u0003מכדי\u0004 \u0005[הרי\u0006 טומאת \u0003שרץ איתקש\u0004 \u0005הוקשה,\u0006 הושוותה\u0005]\u0006 \u0003ל\u0004טומאת \u0003שכבת זרע, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004והנוגע בכל טמא נפש או \u0003איש אשר תצא ממנו שכבת זרע\"\u0004 (ויקרא כב, ד), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 \"או \u0003איש אשר יגע בכל שרץ\u0004 אשר יטמא לו או באדם אשר יטמא לו לכל טומאתו\" (ויקרא כב, ה), \u0003וכתיב ביה\u0004 \u0005[ונאמר בו]\u0006 \u0003ב\u0004דיני \u0003שכבת זרע: \"וכל בגד וכל עור אשר יהיה עליו שכבת זרע\u0004 וכובס במים וטמא עד הערב\u0003\"\u0004 (ויקרא טו, יז), וכיון שסמוכים הפסוקים למדים הם בהלכה זה מזה, ואם כן \u0003\"בגד\" ו\"עור\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003ב\u0004טומאת \u0003שרץ למה לי,\u0004 לשם מה נכתבו? אלא ודאי \u0003שמע מינה לאפנויי\u0004 \u0005[למד מזה\u0006 שבא כדי להדגיש שהמילים \u0005מופנות,\u0006 מיותרות\u0005].\u0006","ומעירים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 \u0003מופנה מצד אחד הוא,\u0004 שאמנם המילים \"בגד\" ו\"עור\" האמור בטומאת שרץ אינן הכרחיות במקומן ואפשר היה לדעת את הנלמד ממנו בדרך אחרת, ואולם האמור בטומאת מת חשוב לעניינו, והגזירה השווה הזו מופנה איפוא רק מצד אחד (מצד דיני שרץ). \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 כי גזירה שווה ה\u0003מופנה מצד אחד\u0004 בלבד \u0003למידין\u0004 ממנה \u0003ואין משיבין\u0004 (דוחים על ידי סברה בלבד) עליה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי גזירה שווה כעין זו \u0003למידין\u0004 ממנה \u0003ומשיבין\u0004 עליה, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \"בגד\" ו\"עור\" האמורים ב\u0003מת נמי אפנויי מופנה\u0004 \u0005[גם כן מופנים\u0006 הם\u0005],\u0006 שכן \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003מת אתקש\u0004 \u0005[הוקש,\u0006 הושווה\u0005]\u0006 \u0003לשכבת זרע, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"והנגע בכל טמא נפש או איש אשר תצא ממנו שכבת זרע\"\u0004 (ויקרא כב, ד), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003ב\u0004דין \u0003שכבת זרע: \"וכל בגד וכל עור\"\u0004 (ויקרא טו, יז), אם כן \u0003\"בגד\" ו\"עור\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003ב\u0004טומאת \u0003מת למה לי?\u0004 — \u0003שמע מינה לאפנויי\u0004 \u0005[למד ממנו\u0006 שבא כדי \u0005להפנות]\u0006 להדגיש שמילים אלה מיותרות במקומן, ונועדו לצורך ההשוואה עם דיני השרצים.","כיון שהוזכרו במשא ומתן זה דברים הקשורים במלחמת מדין, דורשים עוד מן הכתובים באותו ענין; \u0003\"ונקרב את קרבן ה' איש אשר מצא כלי זהב אצעדה וצמיד טבעת עגיל וכומז\u0004 לכפר על נפשותינו לפני ה'\u0003\"\u0004 (במדבר לא, נ). \u0003אמר ר' אלעזר: \"עגיל\"\u0004 — \u0003זה דפוס\u0004 (כלי שבו שמים) \u0003של דדין. \"כומז\"\u0004 — \u0003זה דפוס של בית הרחם.\u0004","\u0003אמר רב יוסף: אי הכי, היינו דמתרגמינן\u0004 \u0005[אם כן, זהו שאנחנו מתרגמים]\u0006 \"כומז\" במלה הארמית \u0003\"מחוך\",\u0004 שכוונתו \u0003דבר המביא לידי גיחוך. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: מגופיה דקרא שמע מינה\u0004 \u0005[מגופו של הפסוק למד ממנו]\u0006 מה שימושו של \"כומז\", שכן נדרש \u0003\"כומז\"\u0004 כנוטריקון: \u0003כאן מקום זימה.\u0004","על הנאמר באותו פרק \u0003\"ויקצף משה על פקודי החיל\u0004 שרי האלפים ושרי המאות הבאים מצבא המלחמה\u0003\"\u0004 (במדבר לא, יד), \u0003אמר רב נחמן\u0004 שכך \u0003אמר רבה בר אבוה, אמר להן משה לישראל: שמא חזרתם לקלקולכם הראשון\u0004 כשם שחטאתם בבנות מואב ומדין בשיטים? \u0003אמרו לו: \"\u0004ו\u0003לא נפקד ממנו איש\"\u0004 (במדבר לא, מט), כלומר, כולנו שלמים במעשים כשם שהיינו. \u0003אמר להן: אם כן כפרה למה?\u0004 שהרי תכשיטים אלו הביאו הנשיאים לכפר על נפשותיהם. \u0003אמרו לו: אם\u0004 אמנם \u0003מידי עבירה\u0004 במעשה \u0003יצאנו, מידי הרהור\u0004 עבירה \u0003לא יצאנו! מיד\u0004 החליטו \u0003\"ונקרב את קרבן ה'\".\u0004","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: מפני מה הוצרכו ישראל שבאותו הדור כפרה\u0004 — \u0003מפני\u0004"],["\u0003שזנו\u0004 (נהנו) \u0003עיניהם מן הערוה.\u0004","ועל אותו פסוק המונה את התכשיטים \u0003אמר רב ששת: מפני מה מנה הכתוב תכשיטין שבחוץ,\u0004 כגון צמיד שביד, \u0003עם תכשיטין שבפנים,\u0004 כגון כומז? — \u0003לומר לך\u0004 כי \u0003כל המסתכל\u0004 אפילו \u0003באצבע קטנה של אשה כאילו מסתכל במקום התורפה\u0004 (הערווה), שהרי כפרה זו היתה על שחטאו בהסתכלות.","ועוד בדיני המותר והאסור לצאת בו בשבת. \u0003יוצאה אשה בחוטי שער\u0004 ששמה על ראשה, \u0003בין\u0004 שהם \u0003מ\u0004שערות \u0003שלה\u0004 שהתקינה מהן פיאה, \u0003בין משל חבירתה, בין משל בהמה.\u0004","\u0003ו\u0004יוצאת אשה \u0003ב\u0004תכשיטים הקרויים \u0003\"טוטפת\", ובסרביטין בזמן שהם תפורין\u0004 ואינם נופלים,","וכן \u0003ב\u0004דבר הקרוי \u0003\"כבול\" ובפאה נכרית\u0004 יוצאת בשבת \u0003לחצר,\u0004 אף כי לא לרשות הרבים. וכן יוצאת \u0003במוך שבאזנה, ובמוך שבסנדלה ובמוך שהתקינה לנדתה,\u0004","\u0003ובפילפל, ובגלגל\u0004 (גרגר) \u0003מלח וכל דבר שניתן לתוך פיה\u0004 לרפואה או להרחקת ריח רע, \u0003ובלבד שלא תתן\u0004 דברים אלה לתוך פיה \u0003לכתחלה בשבת, ואם נפל\u0004 — \u0003לא תחזיר.\u0004","\u0003שן תותבת\u0004 (זרה) וכן (רמב\"ן) \u0003שן של זהב\u0004 — \u0003רבי מתיר\u0004 לצאת בה, \u0003וחכמים אוסרים.\u0004","שנינו במשנה שיוצאת אשה בחוטי שיער מכמה סוגים. ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 להשמיע את כולם, \u0003דאי אשמעינן דידה\u0004 \u0005[שאם היה משמיע לנו\u0006 רק שערות \u0005שלה]\u0006 הייתי אומר שיכולה לצאת בהם \u0003משום דלא מאיס\u0004 \u0005[שאינן מאוסות],\u0006 וזהות הן לאלה \u0003שבראשה, ולכן אין כל סיבה שבתוא להסירן מראשה ולטלטלן בידיה ברשות הרבים, אבל\u0004 של \u0003חבירתה דמאיס\u0004 \u0005[שהן מאוסות]\u0006 וצבען שונה מאלה שלה — \u0003אימא\u0004 \u0005[הייתי אומר]\u0006 ש\u0003לא\u0004 תצא בהן, משום החשש שמא תתבייש בהן ותסירן מראשה, ותבוא לטלטלן ברשות הרבים.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 שמותר לה לצאת בשערות \u0003חבירתה\u0004 — הייתי אומר כי מותרת לצאת בהן משום ש\u0003בת מינה היא,\u0004 ולכן אינן מאוסות בעיניה ולא תבוא להסירן, \u0003אבל ב\u0004שערות \u0003בהמה\u0004 כיון ש\u0003לאו בר\u0004 \u0005[שאינה בת]\u0006 \u0003מינה אימא\u0004 \u0005[הייתי אומר]\u0006 ש\u0003לא\u0004 תצא בהן משום החשש שתבוא להסירן, על כן \u0003צריכא\u0004 \u0005[הוצרכה]\u0006 לציין במפורש בכל מקרה.","\u0003תנא\u0004 \u0005[שנויה\u0006 תוספתא\u0005]:\u0006 \u0003ובלבד שלא תצא ילדה\u0004 (צעירה) \u0003ב\u0004שערות של \u0003זקנה, וזקנה ב\u0004שערות \u0003של ילדה.\u0004","ומקשים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003זקנה\u0004 היוצאת \u0003ב\u0004שערות \u0003של ילדה\u0004 — מובן הדבר, כי \u0003שבח הוא לה\u0004 שתראה צעירה. \u0003אלא ילדה ב\u0004שערות \u0003של זקנה אמאי\u0004 \u0005[מדוע]\u0006 תצא כך? והלא \u0003גנאי הוא לה!\u0004 ולשם מה תוסיף אשה לעצמה שערות שיבה? ומשיבים: \u0003איידי דתנא\u0004 \u0005[על ידי,\u0006 מפני \u0005ששנה]\u0006 \u0003זקנה בשל ילדה, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 שלא לצורך \u0003ילדה בשל זקנה.\u0004","שנינו במשנה שיוצאת אשה \u0003בכבול ובפאה נכרית לחצר. אמר רב: כל\u0004 תכשיט ולבוש \u0003שאסרו חכמים לצאת בו\u0004 בשבת \u0003לרשות הרבים אסור לצאת בו\u0004 גם \u0003לחצר,\u0004 מחשש שמא תשכח ותצא לרחוב, \u0003חוץ מכבול ופאה נכרית.\u0004","\u0003ר' ענני בר ששון משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' ישמעאל אמר: הכל,\u0004 כל התכשיטים, דינם לענין היתר היציאה בהם לחצר \u0003ככבול\u0004 שמותרים.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 שמותר לצאת \u0003בכבול ובפיאה נכרית לחצר, בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 — \u0003ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 שרק כבול ופאה נכרית מותר לצאת בהם לחצר, \u0003אלא ל\u0004שיטת \u0003ר' ענני בר ששון קשיא\u0004 \u0005[קשה]!\u0006 ומשיבים: \u0003ר' ענני בר ששון משמיה דמאן קאמר ליה\u0004 \u0005[משמו של מי אמר זאת]\u0006 — \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' ישמעאל בר יוסי,\u0004 ו\u0003ר' ישמעאל בר' יוסי תנא הוא ופליג\u0004 \u0005[וחולק],\u0006 רשות בידו כתנא לחלוק על המשנה, שהרי אף היא חיבור מתורת התנאים.","ושואלים: \u0003ו\u0004לשיטת \u0003רב, מאי שנא הני\u0004 \u0005[מה שונים אלו]\u0006 כבול ופיאה נכרית שאותם התירו? \u0003אמר עולא: כדי שלא תתגנה\u0004 (תמאס) האשה \u0003על בעלה,\u0004 אם תחוייב להיות בלתי מקושטת אף בחצר ביתה. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 על הנאמר \u0003\"והדוה בנדתה\"\u0004 (ויקרא טו, לג), \u0003זקנים הראשונים אמרו\u0004 שפסוק זה בא ללמדנו שתהא הנדה מרוחקת מבעלה בכל הדברים, \u0003שלא תכחול\u0004 את עיניה בכחול, \u0003ו\u0004ש\u0003לא תפקוס\u0004 בצבע אדום בפניה \u0003ולא תתקשט בבגדי צבעונין. עד שבא ר' עקיבא ולימד: אם כן\u0004 אתה עושה — \u0003אתה מגנה על בעלה, ונמצא בעלה מגרשה,\u0004 ולכן אין לעשות הרחקות שתגרומנה לכך. \u0003אלא מה תלמוד לומר \"והדוה בנדתה\"\u0004 — הכוונה: \u0003ב\u0004איסור \u0003נדתה תהא\u0004 אף לאחר שתפסק זיבת הדם \u0003עד שתבא במים\u0004 לטבול.","\u0003אמר רב יהודה אמר רב: כל מקום שאסרו חכמים\u0004 דבר \u0003מפני מראית העין\u0004 — \u0003אפילו בחדרי חדרים\u0004 שאין איש רואה \u0003אסור,\u0004 שלא חלקו חכמים בדבריהם ואסרו בכל מקרה.","ומקשים: והלא \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 ש\u0003לא\u0004 תצא בהמת ישראל בשבת \u0003בזוג\u0004 (פעמון) שבצוארה \u0003אף על פי ש\u0004הוא \u0003פוקק\u0004 ואינו משמיע קול, משום מראית עין, שנראה כמוליכה לשוק. \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003פוקק לה\u0004 לבהמה \u0003זוג בצוארה ומטייל עמה בחצר.\u0004 נמצא שדבר שאסרו חכמים מפני מראית עין, התירוהו בחצר!","ומשיבים: \u0003תנאי היא\u0004 \u0005[\u0006מחלוקת \u0005תנאים היא]\u0006 בדבר זה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006"],["\u0003שוטחן בחמה\u0004 (בשמש), \u0003אבל לא כנגד העם\u0004 (בני אדם) שיבואו לחושדו שכיבס בגדיו בשבת. ו\u0003ר' אליעזר ור' שמעון אוסרין\u0004 אפילו במקום שאינו נראה לרבים. הרי שנחלקו חכמים אם הנאסר מפני מראית העין אסור בכל מקום.","שנינו במשנה שיוצאת אשה בשבת \u0003במוך שבאזנה. תני\u0004 \u0005[שנה]\u0006 \u0003רמי בר יחזקאל: והוא\u0004 דווקא באופן \u0003שקשור\u0004 המוך \u0003באזנה\u0004 ולא תבוא להוציאו.","\u0003ו\u0004כן מה ששנינו היתר שתצא \u0003במוך שבסנדלה תני\u0004 \u0005[שנה]\u0006 \u0003רמי בר יחזקאל: והוא\u0004 דווקא באופן \u0003שקשור לה בסנדלה.\u0004","ועל מה ששנינו במשנה שיכולה האשה לצאת \u0003במוך שהתקינה לה לנדתה, סבר\u0004 \u0005[סבור היה]\u0006 \u0003רמי בר חמא למימר\u0004 \u0005[לומר]\u0006 כי אף \u0003הוא\u0004 הותרה לצאת בו דווקא באופן \u0003שקשורה לה\u0004 המוך \u0003בין יריכותיה. אמר רבא\u0004 מוך זה הותר לה לצאת בו \u0003אף על פי שאינו קשור לה,\u0004 כי \u0003כיון דמאיס\u0004 \u0005[שהוא מאוס]\u0006 \u0003לא אתיא לאיתויי\u0004 \u0005[תבוא להביאו,\u0006 ולטלטלו בידה.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' ירמיה מר' אבא: עשתה לה בית יד\u0004 (כפפה) שתוכל להחזיק בו מוך זה, \u0003מהו\u0004 הדין בכגון זה\u0003?\u0004 האם מאחר ואין בכך חשש מיאוס יש לחשוש שתבוא לטלטלו, או לא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מותר. איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 ש\u0003אמר רב נחמן בר אושעיא\u0004 שכך \u0003אמר ר' יוחנן: עשתה לה בית יד\u0004 — \u0003מותר.\u0004","על מוך זה שבאוזן מסופר כי \u0003ר' יוחנן נפיק בהו לבי מדרשא\u0004 \u0005[יצא בו לבית המדרש],\u0006 \u0003וחלוקין\u0004 היו \u0003עליו חבריו\u0004 על שעשה כן מפני שלא היה קשור באזניו. \u0003ר' ינאי נפיק בהו\u0004 \u0005[יצא בהם]\u0006 \u0003לכרמלית וחלוקין\u0004 היו \u0003עליו כל\u0004 חכמי \u0003דורו.\u0004 ומקשים: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רמי בר יחזקאל: והוא\u0004 שהותר הרי זה דווקא כ\u0003שקשור לה\u0004 המוך \u0003באזנה!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שיצאו \u0003חכמים במוך זה הרי זה באופן דמיהדק\u0004 \u0005[שהוא מהודק]\u0006 ולכן הותר לצאת בו אף שאינו קשור, ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר רמי בר יחזקאל שלא הותר אלא כאשר הוא קשור, הרי זה רק באופן \u0003דלא מיהדק\u0004 \u0005[שאינו מהודק].\u0006","שנינו במשנה שאשה יוצאת \u0003בפלפל ובגלגל מלח\u0004 בפיה. ומסבירים: \u0003פלפל\u0004 מחזיקה בפיה כדי \u0003ל\u0004הפיג את \u0003ריח הפה,\u0004 ו\u0003גלגל\u0004 (גרגר) \u0003מלח לדורשיני\u0004 (כאב שיניים). ומה ששנינו במשנה שאשה יוצאת בשבת ב\u0003כל דבר שנותנת לתוך פיה\u0004 מתפרש שהוא \u0003זנגבילא\u0004 \u0005[זנגביל],\u0006 \u0003אי נמי דרצונא\u0004 \u0005[או גם כן קנמון].\u0006","שנינו במשנה בענין יציאת האשה בשבת ב\u0003שן תותבת\u0004 ו\u0003שן של זהב\u0004 שנחלקו בכך חכמים, \u0003רבי מתיר וחכמים אוסרין. אמר ר' זירא לא שנו\u0004 שנחלקו \u0003אלא\u0004 בשן \u0003של זהב\u0004 שהיא יקרה ועשויה האשה להוציאה מפיה ולהראותה לחברותיה ועלולה לבוא לידי טלטול, \u0003אבל בשל כסף\u0004 שאינה יקרה כל כך ואין חשש שתוציאה מפיה, ל\u0003דברי הכל מותר. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003בשל כסף\u0004 ל\u0003דברי הכל מותר,\u0004 ב\u0003של זהב רבי מתיר וחכמים אוסרין.\u0004","\u0003אמר אביי: רבי ור' אליעזר ור' שמעון בן אלעזר כולהו סבירא להו\u0004 \u0005[כולם סבורים]\u0006 כי \u0003כל מידי דמיגניא ביה\u0004 \u0005[דבר שמתגנה,\u0006 מתכערת \u0005בו]\u0006 \u0003לא אתיא לאחו‍יי\u0004 \u0005[תבוא\u0006 להביאו ו\u0005להראותו].\u0006","ומפרטים: \u0003רבי\u0004 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו\u0006 כאן\u0005].\u0006 \u0003ר' אליעזר\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר פוטר\u0004 אשה היוצאת \u0003בכובלת ובצלוחית של פלייטון,\u0004 שאשה שריחה רע לא תוציא תכשיטים אלה ממקומם להוליכה בידה.","ו\u0003ר' שמעון בן אלעזר\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003כלל אמר ר' שמעון בן אלעזר:\u0004 כל תכשיט ש\u0003הוא למטה\u0004 (מתחת) \u0003מן הסבכה\u0004 המכסה את השערות האשה \u0003יוצאה בו\u0004 בשבת, שודאי לא תתיר את קליעת שערותיה להראותו, \u0003למעלה מן הסבכה\u0004 — \u0003אינה יוצאה בו,\u0004 שכן יש חשש שתוציאו ותטלטלו.","\u0003יוצאה\u0004 אשה \u0003ב\u0004מטבע של \u0003סלע ש\u0004קושרת \u0003על הצינית\u0004 (פצע שברגל). \u0003הבנות\u0004 ה\u0003קטנות יוצאות בחוטין, ואפילו בקיסמין שבאזניהם\u0004 ששמים בנקבים שבאוזן, שכאשר אין עונדים עדיין לילדה עגילים, שמים הוטים או קיסמין כדי שלא יסתמו נקבים אלה. \u0003ערביות\u0004 (נשים יהודיות הגרות בערב) \u0003יוצאות רעולות\u0004 (מכוסות בצעיף על פניהן), \u0003ומדיות פרופות, ו\u0004כן הותר ל\u0003כל אדם\u0004 בכל מקום לצאת בשבת ברעלה או בפריפה, \u0003אלא שדברו חכמים בהוה,\u0004 כלומר, בדברים ובאופנים המצויים. \u0003פורפת\u0004 אשה שאין לה כפתור \u0003על האבן,\u0004 שמכניסה אבן קטנה ועוטפת אותה בחלק מן הבגד ומשתמשת בו כבכפתור, \u0003ו\u0004כן \u0003על האגוז ועל המטבע, ובלבד שלא תפרוף לכתחלה בשבת\u0004 בדברים אלה.","שואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003צינית\u0004 זו ששנינו במשנה שיוצאת האשה בסלע הקשור בו בשבת? ומסבירים: \u0003בת ארעא\u0004 (מכה שבכף הרגל).","ושואלים: \u0003ומאי שנא\u0004 \u0005[ומה שונה,\u0006 מדוע דווקא\u0005]\u0006 שמים על הפצע \u0003סלע? אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003כל מידי דאקושא מעלי\u0004 \u0005[דבר ש\u0006הוא \u0005קשה\u0006 הריהו \u0005מועיל]\u0006 \u0003לה,\u0004 אם כן \u0003ליעבד\u0004 \u0005[יעשה]\u0006 \u0003לה חספא\u0004 \u0005[חרס]\u0006 בלבד! \u0003אלא\u0004 תאמר שהוא \u0003משום שוכתא\u0004 \u0005[חלודה]\u0006 שבמטבע שמועילה — אם כן \u0003ליעבד לה טסא\u0004 \u0005[שיעשו לה טס,\u0006 פיסת כסף קטנה\u0005]!\u0006 \u0003אלא\u0004 תאמר שהוא \u0003משום צורתא\u0004 \u0005[הצורה,\u0006 התבנית שעל המטבע\u0005],\u0006 אם כן \u0003ליעבד\u0004 \u0005[יעשה]\u0006 \u0003לה פולסא\u0004 \u0005[אסימון]!\u0006 \u0003אמר אביי: שמע מינה כולהו מעלין\u0004 \u0005[למד מכאן\u0006 ש\u0005כל\u0006 אלה יחד \u0005מעולים]\u0006 \u0003לה.\u0004","כיון שהוזכר במשנה ש\u0003הבנות יוצאות בחוטין,\u0004 מספרים כי \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל לא שביק\u0004 \u0005[הניח]\u0006 \u0003להן לבנתיה דנפקי\u0004 \u0005[לבנותיו שתצאנה]\u0006 \u0003בחוטין, ולא שביק להו גניאן גבי הדדי\u0004 \u0005[הניח להן לשכב זו אצל זו,\u0006 יחד\u0005],\u0006 \u0003ועביד להו\u0004 \u0005[ועשה להן]\u0006 \u0003מקואות ביומי\u0004 \u0005[בימי,\u0006 בתקופת\u0005]\u0006 \u0003ניסן ומפצי ביומי\u0004 \u0005[ומפצים,\u0006 מחצלות בנהר פרת \u0005בימי,\u0006 בתקופת\u0005]\u0006 \u0003תשרי\u0004 שכיון שהמים רדודים מרובה בהם הטיט, ועשה מחצלות שתוכלנה לטבול בלא להתלכלך.","ודנים בכל פרט לעצמו: \u0003לא שביק להו\u0004 \u0005[הניח\u0006 \u0003להן]\u0004 שתהיינה \u0003יוצאות בחוטין, והאנן תנן\u0004 \u0005[והרי אנחנו שנינו\u0006 במשנתנו\u0005]\u0006 ש\u0003הבנות יוצאות בחוטין!\u0004 ומשיבים: \u0003בנתיה דאבוה\u0004 \u0005[בנותיו של אביו]\u0006 של \u0003שמואל\u0004 בחוטים \u0003צבעונין הוו\u0004 \u0005[היו]\u0006 רוצות לצאת, וחשש שמא בגלל יופיים תבואנה להראותן ולטלטלן.","ועוד, \u0003לא שביק להו גניאן גבי הדדי\u0004 \u0005[הניח להן לשכב זו אצל זו,\u0006 יחד\u0005],\u0006 \u0003לימא\u0004 \u0005[האם נאמר]\u0006 כי דבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב הונא\u0004 בהלכה שאמר. ש\u0003אמר רב הונא: נשים המסוללות\u0004 (מתחככות) \u0003זו בזו\u0004 משום תאות תשמיש —"],["\u0003פסולות לכהונה,\u0004 שהדבר נחשב לזנות וזונה אסורה לכהן (תוספות).","ודוחים: \u0003לא,\u0004 אין הדבר הכרחי, ואילו טעמו של אבי שמואל — משום שהוא \u0003סבר כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא לילפן גופא נוכראה\u0004 \u0005[תלמדנה,\u0006 תתרגלנה, לישון עם \u0005גוף זר],\u0006 ויבואו בסופו של דבר.","\u0003ועביד להו\u0004 \u0005[ועשה להן]\u0006 \u0003מקוה ביומי\u0004 \u0005[בימי,\u0006 בתקופת\u0005]\u0006 \u0003ניסן,\u0004 הרי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב\u0004 ש\u0003אמר רב: מטרא במערבא סהדא רבא\u0004 \u0005[\u0006ל\u0005גשם\u0006 היורד \u0005במערב,\u0006 בארץ ישראל, \u0005העד הגדול]\u0006 הוא נהר ה\u0003פרת,\u0004 שמי הפרת מתרבים לאחר תקופת הגשמים, וגשמי צפון בבל שמשם יורד הפרת מקבילים בעיקרם לגשמים שבארץ ישראל, ולכן מי הפרת המרובים שבתקופת האביב — מי גשמים הם. \u0003וסבר\u0004 \u0005[וסבר היה]\u0006 אבי שמואל \u0003שלא\u0004 תיטהרנה בטבילה \u0003בפרת, משום החשש שמא ירבו הנוטפין\u0004 (מי הגשמים) \u0003על הזוחלין\u0004 (מי הנהר), ולא יטהר הנהר עוד כנהר. כי בדיני המקוה קיימים שני אופני טהרה, האחד הוא הטבילה במקום שניקוו בו מים, כגון מי גשמים, והם עומדים במקומם, והאחר במים הזורמים כדרכם בטבע, כמי מעיין ונהר. ואולם מי גשמים אינם מטהרים כשהם זורמים אלא כשהם קוויים.","\u0003ופליגא\u0004 \u0005[וחלוק הוא]\u0006 על \u0003שמואל\u0004 בנו. ש\u0003אמר שמואל: נהרא מכיפיה מיברך\u0004 \u0005[הנהר מתברך מאפיקו]\u0006 (גאונים), שתוספת המים בנהר אינה בעיקר מן הגשמים אלא ממים תת קרקעיים. \u0003ופליגא דידיה אדידיה,\u0004 \u0005[וחלוקים\u0006 דבריו \u0005על\u0006 דברי \u0005עצמו],\u0006 ש\u0003אמר שמואל: אין המים מטהרין בזוחלין אלא\u0004 מי נהר ה\u0003פרת ביומי\u0004 \u0005[בימי,\u0006 תקופת\u0005]\u0006 \u0003תשרי בלבד,\u0004 שכיון שלא ירדו גשמים בתקופת הקיץ רק אז ברור שהמים הם מי הנהר בלבד.","שנינו במשנה שהאשה \u0003פורפת על האבן,\u0004 אבל לא תפרוף לכתחילה בשבת. ומקשים: \u0003והאמרת רישא\u0004 \u0005[והרי אמרת בראש\u0006 הלכה זו במשנה\u0005]\u0006 ש\u0003\"פורפת\",\u0004 ומשמעו שלכתחילה מותר לה לעשות כן, וכיצד תוסבר הסתירה? \u0003אמר אביי: סיפא אתאן\u0004 \u0005[בסוף\u0006 הלכה זו \u0005הגענו]\u0006 \u0003ל\u0004מקרה של \u0003מטבע\u0004 שהוזכר אף הוא במשנה, ודין זה יוצא דופן, כי מאחר שהמטבע הוא מוקצה משימוש בשבת אין להשתמש בו לכאורה כפריפה, ובכל אופן הותר.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אביי: אשה מהו שתערים ותפרוף\u0004 בגדה \u0003על האגוז\u0004 כדי \u0003להוציא\u0004 אותו בדרך זו בהיתר \u0003לבנה\u0004 ה\u0003קטן\u0004 הנמצא ברשות הרבים \u0003בשבת?\u0004","ומעירים: שאלה זו \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003מערימין,\u0004 שמותר להערים בזמן דליקה בשבת, ומותר ללבוש בגדים מרובים זה על גבי זה כדי להוציאם מבית בוער בשבת. וכמו כן שאלה זו \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003אין מערימין.\u0004","ומפרטים: \u0003תיבעי למאן דאמר\u0004 \u0005[תישאל ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003מערימין בדליקה,\u0004 והנימוק: \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שהותר להערים משום \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא שרית ליה\u0004 \u0005[תתיר לו]\u0006 להערים \u0003אתי לכבויי\u0004 \u0005[יבוא לכבות],\u0006 \u0003אבל הכא אי\u0004 \u0005[כאן אם]\u0006 \u0003לא שרית ליה\u0004 \u0005[תתיר לה]\u0006 לאשה זו להערים ולהוציא בגד בנה לרשות הרבים בדרך פריפה \u0003לא אתי לאפוקי\u0004 \u0005[תבוא להוציא].\u0006","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003אין מערימין בדליקה, התם\u0004 \u0005[שם]\u0006 הוא שנאסר הדבר משום שאף כרגיל \u0003דרך הוצאה\u0004 של בגדים היא אף \u0003בכך,\u0004 בדרך הערמה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 — על ידי פריפה \u0003אין דרך הוצאה בכך,\u0004 ואין בדבר איסור מן התורה כלל, ואם כן \u0003אימא שפיר דמי\u0004 \u0005[אמור\u0006 כי \u0005יפה הדבר,\u0006 מותר\u0005].\u0006 לשאלה זו לא נמצא פתרון, ולכן \u0003תיקו\u0004 במקומה.","\u0003הקיטע\u0004 (קטוע רגל) \u0003יוצא\u0004 בשבת \u0003בקב\u0004 (רגל עשויה עץ) \u0003שלו\u0004 שדינו כמנעל, אלו \u0003דברי ר' מאיר\u0004"],["\u0003ור' יוסי אוסר,\u0004 שאינו מחשיב אותו למנעל.","\u0003ואם יש לו\u0004 לקב \u0003בית קיבול כתיתין\u0004 — מקום חלול בראש הקב שבו שם הקיטע דברים רכים (=כתיתין) שלא להכאיב לגדם \u0003טמא\u0004 (מקבל טומאה) הקב, שאז דינו ככלי קיבול של עץ המקבל טומאה.","וה\u0003סמוכות שלו\u0004 שהם כעין נעליים שעושה מי שנקטעו שתי רגליו ונועלם על ברכיו ועליהן הוא הולך, אם הוא זב הריהן \u0003טמאין מדרס,\u0004 שהם ככלי שדורס (דורך) עליו הזב, ומקבלים טומאה משום כך, \u0003ויוצאין בהן בשבת\u0004 שהן כרגלי הקיטע, ואף \u0003נכנסין בהן בעזרה\u0004 שבבית המקדש, אף שאסור לבוא נעול נעליים לעזרה.","ואילו קיטע שאינו יכול כלל ללכת, ויושב על כסא וגורר עצמו בסמוכות, ה\u0003כסא ו\u0004ה\u0003סמוכות שלו טמאין מדרס, ו\u0004אולם \u0003אין יוצאין בהם בשבת, ואין נכנסין בהן בעזרה.\u0004","ה\u0003לוקטמין\u0004 (אשר תבואר מהותם בגמרא) \u0003טהורין\u0004 מלקבל טומאה כיון שאינם כלי, \u0003ואין יוצאין בהן\u0004 בשבת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: היכי תנן\u0004 \u0005[איך שנינו\u0006 במשנתנו\u0005]?\u0006 האם הגירסה במשנה שהקיטע יוצא בקב ור' יוסי אוסר, או אין הקיטע יוצא ור' יוסי מתיר? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003לא ידענא\u0004 \u0005[אינני יודע].\u0006 ועוד שאלו רבא: \u0003הילכתא מאי\u0004 \u0005[מה ההלכה]\u0006 בענין זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא ידענא\u0004 \u0005[אינני יודע].\u0006","\u0003איתמר\u0004 \u0005[נאמר]\u0006 כי \u0003אמר שמואל\u0004 שגירסת המשנה היא \u0003\"אין הקיטע\u0004 יוצא \u0003\",\u0004 ור' יוסי מתיר. \u0003וכן אמר רב הונא\u0004 שהגירסה \u0003\"אין הקיטע\". אמר\u0004 על כך \u0003רב יוסף: הואיל ואמר שמואל\u0004 כי הגירסה היא \u0003\"אין הקיטע\" ו\u0004כמו כן \u0003אמר\u0004 אף \u0003רב הונא,\u0004 אם כן \u0003אנן נמי ניתני\u0004 \u0005[אנו גם כן נשנה]\u0006 במשנה כגירסה זו \u0003\"אין הקיטע\".\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רבא בר שירא:\u0004 וכי \u0003לא שמיע להו הא דמתני ליה\u0004 \u0005[שמעו הם\u0006 הלכה \u0005זו ששנה\u0006 \u0003לו] רב חנן בר רבא לחייא בר רב קמיה\u0004 \u0005[לפני]\u0006 \u0003רב בקיטונא דבי\u0004 \u0005[בקיטון,\u0006 חדר קטן \u0005של בית]\u0006 \u0003רב,\u0004 שגרס לפניו: \u0003אין הקיטע יוצא\u0004 בשבת \u0003בקב שלו,\u0004 אלו \u0003דברי ר' מאיר, ור' יוסי מתיר. ומחוי ליה\u0004 \u0005[והראה לו]\u0006 \u0003רב\u0004 ברמז: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות, שיש לגרוס שר' יוסי הוא האוסר ור' מאיר הוא המתיר. \u0003אמר רב נחמן בר יצחק, וסימנא\u0004 \u0005[וסימן]\u0006 לזכור מי המתיר והאוסר יהא: \u0003\"סמ\"ך סמ\"ך\",\u0004 שהאות ס' שנמצאת גם במלה \"יוסי\" וגם במלה \"אוסר\" באה להזכיר כי ר' יוסי \u0003הוא האוסר.\u0004","ומעירים: \u0003ואף שמואל\u0004 האומר כי הגירסה היא \"אין הקיטע\" ולדעתו ר' יוסי מתיר, \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 מדבריו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 יבמה \u0003שחלצה\u0004 ליבם \u0003בסנדל שאינו שלו,\u0004 או \u0003בסנדל של עץ, או\u0004 שהיה סנדל \u0003של\u0004 רגל \u0003שמאל ב\u0004רגל \u0003ימין\u0004 — \u0003חליצה\u0004 זו \u0003כשרה.\u0004","\u0003ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור שסנדל של עץ נחשב כנעל? ו\u0003אמר שמואל:\u0004 שיטת \u0003ר' מאיר היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003הקיטע יוצא בקב שלו,\u0004 אלו \u0003דברי ר' מאיר,\u0004 ו\u0003ר' יוסי אוסר,\u0004 והרי אם כן שגרס שמואל לבסוף כגירסת רב.","\u0003ואף רב הונא הדר ביה\u0004 \u0005[חזר בו]\u0006 מגרסתו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003סנדל של סיידין\u0004 שהוא מעין סנדל קלוע מקש או מנצרים לכסות בו את נעלי העור שלא יתקלקלו מן הסיד אם הסייד זב והלך בו, הרי סנדל זה \u0003טמא מדרס,\u0004 שהוא נחשב כנעל. \u0003ואשה חולצת בו, ויוצאים בו בשבת,\u0004 אלו \u0003דברי ר' עקיבא ולא הודו לו\u0004 חכמים.","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003הודו לו! אמר רב הונא: מאן\u0004 \u0005[מיהו]\u0006 החכם עליו נאמר ש\u0003הודו לו\u0004 — \u0003ר' מאיר, ומאן\u0004 \u0005[ומיהו]\u0006 החכם עליו נאמר ש\u0003לא הודו לו\u0004 — \u0003ר' יוסי.\u0004 הרי שאף הוא גרס במשנתנו שר' יוסי אוסר.","\u0003אמר רב יוסף: מאן\u0004 \u0005[מיהו]\u0006 החכם עליו נאמר ש\u0003לא הודו לו\u0004 לר' עקיבא — \u0003ר' יוחנן בן נורי. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כורת של קש ושפופרת של קנים, ר' עקיבא מטמא\u0004 אותם בתורת כלי, שלדעתו הם מקבלים טומאה, \u0003ור' יוחנן בן נורי מטהר.\u0004 והרי שלדעת ר' יוחנן בן נורי דבר העשוי קש אינו נחשב לכלי ראוי לשימוש.","שנינו מקודם ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 ש\u0003סנדל של סיידין טמא מדרס.\u0004 ושואלים: \u0003הא לאו להילוכא עבדי\u0004 \u0005[הרי לא להילוך עשויים\u0006 סנדלים אלו\u0005]!\u0006 \u0003אמר רב אחא בר רב עולא:\u0004 לעיתים הם כן משמשים להילוך, \u0003שכן הסייד מטייל בו\u0004 לעתים \u0003עד שמגיע לביתו,\u0004 ואם כן מתהלכים לפעמים בסנדל זה.","שנינו במשנה ש\u0003אם יש\u0004 בקב \u0003בית קיבול כתיתין\u0004 — \u0003טמא\u0004 (מקבל טומאה). \u0003אמר אביי:\u0004 הכוונה היא ש\u0003טמא טומאת מת,\u0004 שאם נגעה בו טומאה זו הריהן טמא, \u0003ו\u0004אולם \u0003אין\u0004 הוא \u0003טמא\u0004 טומאת \u0003מדרס,\u0004 שאם השתמש זב בקב זה — לא נטמא הקב, כיון שאין הזב יכול להשען עליו בכל כובד משקלו. \u0003רבא אמר:\u0004 קב זה \u0003אף טמא\u0004 טומאת \u0003מדרס.\u0004","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה\u0006 הלכה\u0005]\u0006 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003עגלה של\u0004 ילד \u0003קטן\u0004 שעשויה כדי ללמדו ללכת (תוספות) — \u0003טמא מדרס,\u0004 כיון שבמדת עשוייה היא להישען עליה. \u0003ואביי אמר\u0004 שאין לדמות: \u0003התם\u0004 \u0005[שם]\u0006 בעגלת הקטן — \u0003סמיך עילויה\u0004 \u0005[נשען עליה],\u0006 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בקב הלא \u0003לא סמיך עילויה\u0004 \u0005[אינו נשען עליו\u0006 בשלימות\u0005].\u0006","\u0003אמר אביי: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה\u0006 הלכה\u0005]\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מקל של זקנים טהור מכלום\u0004 (אינו מקבל כל טומאה), והרי שמצאנו כבר שדבר שנסמכים עליו במידה מסויימת אינו נטמא מדרס!","\u0003ורבא\u0004 דוחה, ואומר שיש לחלק בין הדברים: \u0003התם\u0004 \u0005[שם,\u0006 במקל של זקן\u0005]\u0006"],["\u0003לתרוצי סוגיא עבידא\u0004 \u0005[ליישר\u0006 את \u0005פסיעותיו\u0006 ולזקוף את קומתו \u0005נעשה],\u0006 אבל לא להישען עליו ממש, \u0003הכא\u0004 \u0005[כאן]\u0006 בקב — \u0003לסמוך עילויה\u0004 \u0005[עליו]\u0006 \u0003הוא דעבידא\u0004 \u0005[שעשוי]\u0006 הקב, \u0003וסמיך עליה\u0004 \u0005[ו\u0006אכן \u0005נשען עליו].\u0006","שנינו במשנה שסמוכות הזב וכסאו \u0003טמאין מדרס, ואין יוצאין בהן בשבת, ואין נכנסין בהן לעזרה.\u0004","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003ר' יוחנן\u0004 את ההלכה בענין זה בגירסה הפוכה: \u0003\"נכנסין בהן לעזרה\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אני שונה\u0004 שדבר זה \u0003אשה חולצת בו\u0004 כיון שהוא נחשב לנעל לכל דבר, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 ש\u0003נכנסין\u0004 בו לעזרה?! \u0003תני\u0004 \u0005[שנה]\u0006 \u0003\"אין נכנסין בהן לעזרה\".\u0004","שנינו במשנה נזכר ש\u0003לוקטמין טהורה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003לוקטמין? אמר ר' אבהו:\u0004 פירושו — \u0003חמרא דאכפא\u0004 \u0005[חמור שעל הכתפיים]\u0006 שעושים דמות חמור מעץ לשעשוע ונושאים אותו על הכתפיים ונראה כאילו חמור רוכב עליהם. \u0003רבא בר פפא אמר:\u0004 זהו \u0003קשירי,\u0004 כלומר, מעין קביים גבוהים, ששמים מתחת לרגליים להלך בהם בטיט, או לשעשוע. \u0003רבא בר רב הונא אמר:\u0004 זהו \u0003פרמי\u0004 \u0005[מסכות].\u0006","\u0003הבנים\u0004 (ילדים) \u0003יוצאין\u0004 בשבת \u0003בקשרים\u0004 שעושים לסגולה, \u0003ובני מלכים\u0004 — \u0003בזוגין\u0004 (פעמונים), \u0003ו\u0004לא רק הם, \u0003אלא כל אדם\u0004 מותר לצאת בהם, \u0003אלא שדברו חכמים בהווה\u0004 (במצוי, ברגיל).","שנינו במשנה כי הילדים יוצאים בשבת בקשרים. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003קשרים\u0004 אלה? \u0003אמר אדא מרי\u0004 שכך \u0003אמר רב נחמן בר ברוך\u0004 שכך \u0003אמר רב אשי בר אבין\u0004 שכך \u0003אמר רב יהודה:\u0004 אלה הם \u0003קשורי פואה,\u0004 שקושרים את צמח הפואה לרפואה וסגולה.","\u0003אמר אביי, אמרה לי אם\u0004 (אומנתי): \u0003תלתא\u0004 \u0005[שלושה\u0006 קשרים\u0005]\u0006 — \u0003מוקמי\u0004 \u0005[מעמידים]\u0006 את המחלה שלא תגבר, \u0003חמשה\u0004 קשרים — \u0003מסו\u0004 \u0005[מרפאים],\u0006 \u0003שבעה\u0004 — \u0003אפילו לכשפים מעלי\u0004 \u0005[יפים].\u0006","\u0003אמר רב אחא בר יעקב: והוא\u0004 שמועיל הפואה לרפואה הרי זה דווקא באופן \u0003דלא חזי ליה שמשא וסיהרא\u0004 \u0005[שאין\u0006 המתרפא \u0005רואה אותה\u0006 את \u0005השמש והירח],\u0006 שאינו מביט בהם, \u0003ולא חזי מיטרא\u0004 \u0005[ואינו רואה גשם],\u0006 \u0003ולא שמיע ליה\u0004 \u0005[ואינו שומע]\u0006 \u0003קול ברזלא\u0004 \u0005[ברזל],\u0006 \u0003וקל תרנגולתא, וקל ניגרי\u0004 \u0005[וקול תרנגולת וקול פסיעות].\u0006 \u0003אמר רב נחמן בר יצחק: נפל פותא בבירא\u0004 \u0005[נפלה\u0006 סגולת \u0005הפואה בבור],\u0006 שאם הרפואה תלויה בזהירות כזאת — שוב אין אדם יכול להשתמש בה למעשה.","ושואלים: אם כן הוא שאלה הם קישורי פואה הנעשים כסגולה לריפוי מחלות, \u0003מאי איריא\u0004 \u0005[מדוע דווקא]\u0006 ה\u0003בנים\u0004 יכולים לצאת בהם? \u0003אפילו בנות נמי\u0004 \u0005[גם כן]!\u0006 וכן \u0003מאי איריא\u0004 \u0005[מדוע דווקא]\u0006 \u0003קטנים? אפילו גדולים נמי\u0004 \u0005[גם כן]!\u0006","\u0003אלא מאי\u0004 \u0005[מהם]\u0006 \u0003קשרים\u0004 הללו — \u0003כי הא\u0004 \u0005[כמו\u0006 דבר \u0005זה]\u0006 ש\u0003אמר אבין בר הונא\u0004 שכך \u0003אמר רב חמא בר גוריא: בן שיש\u0004 לו \u0003געגועין על אביו\u0004 ואינו יכול להיפרד — \u0003נוטל\u0004 האב \u0003רצועה ממנעל של ימין וקושר לו\u0004 כסגולה \u0003בשמאלו.\u0004 ומשום שגעגועים אלה מצויים בילדים קטנים, ובעיקר בבנים, שהיו מטפלים ומתעסקים בהם יותר מבבנות, אמרו שהבנים הם היוצאים בקשרים. בעניינה של אותה רפואה \u0003אמר רב נחמן בר יצחק: וסימניך\u0004 \u0005[וסימן\u0006 יש \u0005לך]\u0006 על איזה צד לקשור — \u0003תפילין,\u0004 שקושרים באמצעות יד ימין על יד שמאל, \u0003וחילופא\u0004 \u0005[ו\u0006אם עשה \u0005היפך\u0006 הדבר\u0005]\u0006 שקשר רצועה ממנעל שמאל על ימינו — \u0003סכנתא\u0004 \u0005[סכנה]\u0006 היא, משום שבכך יגברו געגועיו יותר מדי.","וכיון שדובר בסגולות וברפואות שונות ובהיתר שימושן בשבת מביאים עוד מדברי אותו חכם בנושאים אלה. \u0003אמר אבין בר הונא\u0004 שכך \u0003אמר רב חמא בר גוריא: סחופי כסא אטיבורי בשבתא\u0004 \u0005[לכפות כוס\u0006 ריקה שהיו בה חמין \u0005על הטבור בשבת\u0006 לרפואה\u0005]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005].\u0006","\u0003ו\u0004עוד \u0003אמר אבין בר הונא\u0004 שכך \u0003אמר רב חמא בר גוריא: מותר לסוך שמן ומלח בשבת.\u0004","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 שכשיצאו \u0003רב הונא מבי\u0004 \u0005[מבית]\u0006 \u0003רב, ורב מבי\u0004 \u0005[מבית]\u0006 \u0003ר' חייא, ור' חייא מבי\u0004 \u0005[מבית]\u0006 \u0003רבי, כי הוו מיבסמי\u0004 \u0005[כאשר היו שתויים\u0006\u0005]\u0006 \u0003מייתי משחא ומילתא, ושייפי להו לגוייתא דידייהו וגוייתא דכרעייהו, ואמרי\u0004 \u0005[היו מביאים שמן ומלח, ומשפשפים אותם בכפות ידיהם וגב רגליהם, והיו אומרים]:\u0006 \u0003\"כי היכי דציל הא מישחא\u0004 — \u0003ליציל חמריה דפלניא בר פלניתא\"\u0004 \u0005[\"כשם שצלול שמן זה\u0006 — כך \u0005יצטלל יינו של פלוני בן פלונית\"].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 הוא \u0003לא\u0004 יכול להביא שמן ומלח, או אינו מועיל — \u0003מייתי שיעא דדנא ושרי ליה במיא, ואמר\u0004 \u0005[יביא מגופת חבית וישרה אותה במים, ויאמר]:\u0006 \u0003\"כי היכי דליציל האי שיעא ליציל חמריה דפלניא בר פלניתא\"\u0004 \u0005[\"כשם שצלולה מגופה זו,\u0006 כך \u0005יצטלל יינו של פלוני בן פלונית\"].\u0006","\u0003ו\u0004עוד \u0003אמר אבין בר הונא\u0004 שכך \u0003אמר רב חמא בר גוריא: מותר לחנק בשבת,\u0004 כלומר, לחבוש בחוזקה צואר שחוליותיו נקעו.","\u0003ו\u0004עוד \u0003אמר אבין בר הונא\u0004 שכך \u0003אמר רב חמא בר גוריא: לפופי ינוקא בשבתא\u0004 \u0005[לחתל\u0006 בחזקה \u0005תינוק\u0006 שנולד \u0005בשבת]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005],\u0006 שיש צורך ליישר על ידי החיתולים איברים שמפני הלידה אינם נמצאים לעתים במקומם הנכון.","על דברים אלו היו גירסות שונות, כי \u0003רב פפא מתני\u0004 \u0005[היה שונה]\u0006 שתי הלכות ב\u0003בנים,\u0004 ילדים, ו\u0003רב זביד מתני\u0004 \u0005[היה שונה]\u0006 הלכה אחת ב\u0003בן.\u0004 ומפרטים: \u0003רב פפא מתני\u0004 \u0005[היה שונה]\u0006 שתי הלכות ב\u0003בנים, ותרוייהו מתני להן\u0004 \u0005[ו\u0006את \u0005שתיהן היה שונה אותן]\u0006 \u0003ב\u0004שם \u0003אבין בר הונא.\u0004 ואילו \u0003רב זביד מתני\u0004 \u0005[היה שונה]\u0006 הלכה אחת ב\u0003בן, קמייתא מתני\u0004 \u0005[\u0006את \u0005הראשונה היה שונה]\u0006 \u0003ב\u0004שם \u0003אבין בר הונא, והאי מתני לה\u0004 \u0005[ו\u0006את \u0005זאת היה שונה אותה]\u0006 \u0003ב\u0004שם \u0003רבה בר בר חנה.\u0004 ש\u0003אמר רבה בר בר חנה : לפופי ינוקא בשבתא\u0004 \u0005[חיתול התינוק בשבת]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005].\u0006","ומביאים עוד דברים שאמר אביי בשם אומנתו כדברי סגולה. \u0003אמר אביי, אמרה לי אם: כל מנייני\u0004 — \u0003בשמא דאימא\u0004 \u0005[המניינים\u0006 והלחשים אומרים אותם — \u0005בשם האם]\u0006 של הנצרך ללחש, \u0003וכל קיטרי\u0004 — \u0003בשמאלא\u0004 \u0005[הקשרים\u0006 שעושים כסגולה — קושרים \u0005ב\u0006צד \u0005שמאל].\u0006","\u0003ו\u0004עוד \u0003אמר אביי, אמרה לי אם: כל מנייני דמפרשי\u0004 \u0005[מנין\u0006 הלחשים \u0005שמפורשים],\u0006 כלומר, לחשים \u0005שמניין הפעמים אותו אמורים לאומרם\u0006 — \u0003כדמפרשי\u0004 \u0005[כשם ש\u0006הם \u0005מפורשים]\u0006 כך צריך אכן לעשות, \u0003ודלא מפרשי\u0004 \u0005[ושאינם מפורשים],\u0006 שלא התפרש כמה פעמים צריך לאומרם — יאמרום \u0003ארבעין וחד זימני\u0004 \u0005[ארבעים ואחת פעמים].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003יוצאין באבן תקומה\u0004 כסגולה כנגד הפלה \u0003בשבת, משום\u0004 (בשם) \u0003ר' מאיר אמרו אף במשקל אבן תקומה.\u0004 כלומר, באבן או חפץ אחר שמשקלו בדיוק כאבן תקומה, שאף הוא מועיל. \u0003ו\u0004דין זה הוא \u0003לא\u0004 בהכרח רק באשה \u0003ש\u0004כבר \u0003הפילה\u0004 עובר אחר קודם לכן ויש חשש שמא תפיל שוב, \u0003אלא\u0004 אפילו לא הפילה מעולם ורק חוששת \u0003שמא תפיל\u0004 עכשיו בראשונה, \u0003ולא\u0004 רק אשה \u0003שעיברה\u0004 (שידוע לה שהיא מעוברת), \u0003אלא\u0004 אפילו חוששת \u0003שמא תתעבר ותפיל. אמר רב יימר בר שלמיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי: והוא דאיכוון ואיתקל\u0004 \u0005[שהזדמן ושקל],\u0006 שמשקל אבן תקומה אינו מועיל כאשר יוצרים אבן אחרת במשקל דומה, אלא רק אם נמצאה באקראי אבן כזאת שמשקלה מכוון. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אביי:\u0004 אם מצא חפץ שלישי \u0003שהוא זהה במשקל\u0004 של דבר שנמצא כבר והוא זהה ל\u0003משקל\u0004 אבן תקומה \u0003מאי\u0004 \u0005[מהו]\u0006 לענין זה, האם יש בו תועלת? לשאלה זו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003ו\u0004עוד \u0003אמר אביי, אמרה לי אם: לאשתא בת יומא\u0004 — \u0003לישקול זוזא חיוורא\u0004 \u0005[ל\u0006ריפוי \u0005קדחת בת יום\u0006 — \u0005יקח דינר חדש],\u0006 \u0003וליזיל למלחתא, וליתקול מתקליה מילחא\u0004 \u0005[וילך ל\u0006בריכות ה\u0005מלח, ויקח משקלו מלח],\u0006 \u0003ולצייריה בחללא דבי צואר בנירא ברקא\u0004 \u0005[ויצררנו בחלל בית צוארו בחוט\u0006 עשוי \u0005שיער].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועילה סגולה ראשונה זו — \u0003ליתוב\u0004 \u0005[ישב]\u0006 על \u0003פרשת דרכים, וכי חזי שומשמנא גמלא דדרי מידי, לישקליה ולישדייה בגובתא דנחשא, וליסתמיה באברא, וליחתמי בשיתין גושפנקי, ולברזוליה, ולידריה, ולימא ליה\u0004 \u0005[וכאשר הוא רואה נמלה גדולה שנושאת דבר מה, יקחנה ויכניסנה בשפופרת של נחושת, ויסתמנה בעופרת, ויחתמנה בששים חותמות, וינענעה, וירימנה, ויאמר לה]:\u0006 \u0003\"טעונך עלי וטעונאי עלך\"\u0004 \u0005[\"משאך עלי ומשאי,\u0006 קדחתי, \u0005עליך\"].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא לרב אשי: ודילמא איניש אשכחיה ואיפסק ביה\u0004 \u0005[ושמא אדם מצא\u0006 כבר נמלה זו \u0005והשתמש בה\u0006 לסגולה זו\u0005],\u0006 ומה יועילנו שיחליף קדחת שלו (משאו) בקדחת של חבירו שהיא עכשיו משא הנמלה? \u0003אלא לימא ליה\u0004 \u0005[יאמר לה]\u0006 לנמלה: \u0003\"טעונאי וטעונך עלך\"\u0004 \u0005[\"משאי ומשאך עליך\"].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 הועילה אף סגולה זו \u0003— לישקול כוזא חדתא, וליזיל לנהרא, ולימא ליה\u0004 \u0005[יקח כד חדש, וילך לנהר, ויאמר לו]:\u0006 \u0003\"נהרא נהרא, אוזפן כוזא דמיא לאורחא דאיקלע\u0004 \u0005[נהר נהר, הלוה לי כד מים לאורח שהזדמן]\u0006 \u0003לי\". וליהדר שב זימני על רישיה, ולשדיין לאחוריה, ולימא ליה\u0004 \u0005[ויסובבנו שבע פעמים על ראשו, וישפכנו לאחוריו, ויאמר לו]:\u0006 \u0003\"נהרא נהרא, שקול מיא דיהבת\u0004 \u0005[קח\u0006 את \u0005המים שנתת]\u0006 \u0003לי, דאורחא דאיקלע\u0004 \u0005[שהאורח שהזדמן]\u0006 \u0003לי ביומיה אתא וביומיה אזל\"\u0004 \u0005[ביומו בא וביומו הלך].\u0006","\u0003אמר רב הונא:\u0004"],["\u0003לאשתא תילתא\u0004 \u0005[לקדחת שלישית],\u0006 שבאה לו כל שלושה ימים לסירוגין, \u0003לייתי\u0004 \u0005[יביא]\u0006 \u0003שבעה סילוי\u0004 \u0005[קוצים]\u0006 \u0003משבעה דיקלי\u0004 \u0005[דקלים],\u0006 \u0003ושבעה ציבי\u0004 \u0005[קיסמים]\u0006 \u0003משבעה כשורי\u0004 \u0005[קורות],\u0006 \u0003ושבעה סיכי\u0004 \u0005[יתידות]\u0006 \u0003משבעה גשורי\u0004 \u0005[גשרים],\u0006 \u0003ושבעה קטימי\u0004 \u0005[\u0006מיני \u0005אפר]\u0006 \u0003משבעה תנורי\u0004 \u0005[תנורים],\u0006 \u0003ושבעה עפרי\u0004 \u0005[\u0006מיני \u0005עפר]\u0006 \u0003משבעה סנרי\u0004 (חלל ציר הדלת), \u0003ושבעה כופרי\u0004 מיני \u0005זפת]\u0006 \u0003משבעה ארבי\u0004 \u0005[ספינות],\u0006 \u0003ושבעה בוני כמוני\u0004 \u0005[גרגירי כמון],\u0006 \u0003ושבעה ביני מדיקנא דכלבא סבא\u0004 \u0005[שערות מזקן כלב זקן],\u0006 \u0003ולציירינהו בחללא דבית צוארא בנירא ברקא\u0004 \u0005[ושיצררן בחלל בית צוארו בחוט של שיער].\u0006","\u0003אמר ר' יוחנן: לאשתא צמירתא לישקל סכינא דכולא פרזלא\u0004 \u0005[ל\u0006ריפוי \u0005קדחת חמה יקח סכין שכולו,\u0006 אף הקת, \u0005ברזל],\u0006 \u0003וליזל להיכא דאיכא וורדינא, וליקטר ביה נירא ברקא\u0004 \u0005[וילך למקום שיש סנה, ויקשור בו חוט שיער].\u0006","ואז ב\u0003יומא קמא ליחרוק ביה פורתא, ולימא\u0004 \u0005[\u0006ב\u0005יום הראשון יחתוך בו קצת, ויאמר]:\u0006 \u0003\"וירא מלאך ה' אליו\u0004 בלבת אש מתוך הסנה וירא והנה הסנה בוער באש והסנה איננו אוכל\u0003\"\u0004 (שמות ג, ב), \u0003למחר ליחרוק ביה פורתא ולימא\u0004 \u0005[יחתוך בו\u0006 עוד \u0005קצת, ויאמר]:\u0006 \u0003\"ויאמר משה אסרה נא ואראה\u0004 את המראה הגדול הזה מדוע לא יבער הסנה\u0003\"\u0004 (שמות ג, ג), \u0003למחר ליחרוק ביה פורתא ולימא\u0004 \u0005[למחר יחתוך בו\u0006 עוד \u0005קצת, ויאמר]:\u0006 \u0003\"וירא ה' כי סר לראות\u0004 ויקרא אליו אלהים מתוך הסנה ויאמר משה משה ויאמר הנני\" (שמות ג, ד).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי ולימא\u0004 \u0005[שיאמר]:\u0006 \u0003\"ויאמר אל תקרב הלום\u0004 של נעליך מעל רגליך כי המקום אשר אתה עומד עלי אדמת קודש הוא \u0003\"\u0004שלפי תכנו מתאים יותר ללחש השבעה זה כנגד הקדחת! \u0003אלא ליומא קמא לימא\u0004 \u0005[ביום הראשון יאמר]\u0006 שני פסוקים ראשונים \u0003\"וירא מלאך ה' אליו\u0004 בלבת אש מתוך הסנה וירא והנה הסנה בוער באש והסנה איננו אוכל \u0003\"\u0004וכן \u0003\"ויאמר משה\u0004 אסורה נא ואראה\", \u0003ולמחר לימא\u0004 \u0005[ולמחרת יאמר]:\u0006 \u0003\"וירא ה' כי סר לראות\", ולמחר\u0004 יאמר: \u0003\"ויאמר ה' אל תקרב הלם\u0004 של נעליך מעל רגליך כי המקום אשר אתה עומד עליו אדמת קודש הוא\" (שמות ג, ה).","\u0003וכי פסק ליה ליתתיה ולפסקי, ולימא הכי\u0004 \u0005[וכאשר חותך אותו ינמיך ויחתכנו, ויאמר כך]:\u0006 \u0003\"הסנה הסנה! לאו\u0004 \u0005[לא]\u0006 \u0003משום דגביהת\u0004 \u0005[שאתה גבוה]\u0006 \u0003מכל אילני\u0004 \u0005[האילנות]\u0006 \u0003אשרי\u0004 \u0005[השרה]\u0006 \u0003הקדוש ברוך הוא שכינתיה עלך\u0004 \u0005[שכינתו עליך],\u0006 \u0003אלא משום דמייכת\u0004 \u0005[שנמוך אתה]\u0006 \u0003מכל אילני\u0004 \u0005[האילנות]\u0006 \u0003אשרי קודשא בריך הוא שכינתיה עלך\u0004 \u0005[השרה הקדוש ברוך הוא שכינתו עליך].\u0006 \u0003וכי היכי דחמיתיה אשתא\u0004 \u0005[וכמו שראתה האש]\u0006 \u0003חנניה מישאל ועזריה ועריקת מן קדמוהי\u0004 \u0005[וברחה מהם],\u0006 \u0003כן תחמיניה אשתא\u0004 \u0005[תראה אש\u0006 הקדחת\u0005]\u0006 את \u0003פלוני בר\u0004 \u0005[בן]\u0006 \u0003פלונית ותיערוק מן קדמוהי\u0004 \u0005[ותברח מלפניו,\u0006 ממנו\u0005]\u0006 \u0003\".\u0004","\u0003לסימטא לימא הכי\u0004 \u0005[ל\u0006ריפוי \u0005שחין יאמר כך]:\u0006 \u0003\"בז, בזייה, מס, מסייא, כס, כסייה, שרלאי, ואמרלאי, אלין מלאכי דאישתלחו מארעא\u0004 \u0005[אלה המלאכים שהשתלחו מארץ]\u0006 \u0003סדום ולאסאה שחינא כאיבין\u0004 \u0005[ו\u0006כל זה היה כדי \u0005לרפא שחינין כואבים],\u0006 \u0003בזך, בזיך, בזבזיך, מסמסיך, כמון, כמיך, עיניך\u0004 (מראך) \u0003ביך\u0004 \u0005[בך]\u0006 (שלא תאדים יותר), \u0003עינך ביך\u0004 \u0005[בך],\u0006 \u0003אתריך\u0004 \u0005[מקומך]\u0006 \u0003בך\u0004 (שלא תרחיב), \u0003זרעיך\u0004 \u0005[זרעך]\u0006 \u0003כקלוט וכפרדה דלא\u0004 \u0005[ שאינה]\u0006 \u0003פרה ולא רביא\u0004 \u0005[ואינה רבה],\u0006 \u0003כך לא תפרה ולא תרבה בגופיה\u0004 \u0005[בגופו]\u0006 של \u0003פלוני בר\u0004 \u0005[בן]\u0006 \u0003פלונית\".\u0004","\u0003לכיפה לימא הכי\u0004 \u0005[ל\u0006ריפוי \u0005פצע יאמר כך]:\u0006 \u0003\"חרב שלופה וקלע נטושה לא\u0004 יהא \u0003שמיה יוכב חולין מכאובין\u0004 \u0005[שמו כאב חולי ומכאוב]\u0006\".","\u0003לשידא לימא הכי\u0004 \u0005[ל\u0006הצלה מ\u0005שד יאמר כך]:\u0006 \u0003\"הוית דפקיק, דפקיק הוית, ליטא תבור ומשומת\u0004 \u0005[מקולל שבור ומוחרם]\u0006 השד הקרוי \u0003בר טיט בר טמא בר טינא, כשמגז מריגז ואיסטמאי\".\u0004","\u0003לשידא\u0004 \u0005[ל\u0006הצלה מ\u0005שד]\u0006 של \u0003בית הכסא לימא הכי\u0004 \u0005[יאמר כך]:\u0006 \u0003\"אקרקפי דארי ואאוסי דגורייתא אשכחתון לשידאי\u0004 \u0005[על ראשו של האריה ועל חטמה של הלביאה מצאנו את השד]\u0006 הקרוי \u0003'בר שיריקא פנדא', במישרא דכרתי חבטיה, בלועא דחמרא חטרתיה\u0004 \u0005[בערוגת הכרישין הפלתיו,\u0006 ו\u0005בלחי החמור היכיתיו].\u0006","שנינו במשנה ש\u0003בני מלכים\u0004 יוצאים \u0003בזגין\u0004 (פעמונים), וכן כל אדם. ושואלים: \u0003מאן\u0004 \u0005[מהיו]\u0006 ה\u0003תנא\u0004 הסבור שכל אדם מישראל רשאי לנהוג בענין הוצאת תכשיטים יקרים כמנהג בני מלכים? \u0003אמר ר' אושעיא:\u0004 שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: כל ישראל בני מלכים הם,\u0004 ולכן אפילו תכשיטים יקרים הולמים כל אדם מישראל, ולא יבוא להראותם או להסירם מפני הבושה. \u0003רבא אמר :\u0004 כאן מדובר \u0003באריג\u0004 \u0005[ב\u0006שהפעמון \u0005ארוג]\u0006 \u0003בכסותו,\u0004 שבכגון זה אין לחשוש שמא יוציאם מן האריג, \u0003ו\u0004כ\u0003דברי הכל\u0004 היא משנה זו.","\u0003יוצאין\u0004 בשבת \u0003בביצת החרגול ובשן שועל ובמסמר מן הצלוב\u0004 (שנתקע במי שנדון למוות בנוסח הרומי, על הצלב) \u0003משום\u0004 סגולה ו\u0003רפואה,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אוסרין\u0004 להשתמש באלה \u0003אף בחול, משום דרכי האמורי,\u0004 שכל אלה הם אמונות תפלות ומנהגי גויים שיש להתרחק מהם.","שנינו במשנה שלדעת ר' מאיר יוצאין בשבת בביצת החרגול ובשן של שועל ובמסמר מן הצלוב לסגולה או רפואה. ואת מהות דברים אלה מסבירים: \u0003יוצאין בביצת החרגול\u0004 — \u0003דעבדי לשיחלא\u0004 \u0005[שעושים\u0006 כסגולה \u0005לכאב אזניים].\u0006 \u0003ובשן של שועל\u0004 — \u0003דעבדי לשינתא\u0004 \u0005[שעושים\u0006 כסגולה \u0005ל\u0006ענין \u0005שינה],\u0006 \u0003דחייא\u0004 \u0005[של\u0006 שועל \u0005חי]\u0006 — \u0003למאן דניים\u0004 \u0005[למי שישן\u0006 יותר מדי\u0005]\u0006 שיתעורר. \u0003דמיתא\u0004 \u0005[של\u0006 שועל \u0005מת]\u0006 — \u0003למאן דלא ניים\u0004 \u0005[למי שאיננו ישן].\u0006 \u0003ובמסמר מן הצלוב\u0004 — \u0003דעבדי לזרפא\u0004 \u0005[שעושים ל\u0006רפואת \u0005זיהום].\u0006","שנינו במשנה כי כל הדברים האמורים אפשר לצאת בהם בשבת \u0003משום רפואה,\u0004 אלו \u0003דברי ר' מאיר.\u0004","על עיקר ההלכה שבמשנה זאת \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003כל דבר שיש בו משום רפואה\u0004 שנראה לעין שהיא מועילה, \u0003אין בו משום דרכי האמורי,\u0004 ואין לחשוש לכך במי הנוהג בכך, אם גוי אם ישראל.","ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 מדברים אלה יוצא שדבר ש\u0003אין בו משום רפואה יש בו משום דרכי האמורי. והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אילן שמשיר פירותיו סוקרו\u0004 (צובעו) \u0003(וצובע אותו) בסיקרא\u0004 \u0005[צבע אדום]\u0006 \u0003וטוענו באבנים. בשלמא\u0004 \u0005[נניח]\u0006 כי יכול הוא ל\u0003טוענו באבנים\u0004 לפי שיש בדבר תועלת ממשית, \u0003כי היכי דליכחוש חיליה\u0004 \u0005[כדי שיחלש כוחו],\u0006 שלעתים משיר אילן את פירותיו מפני ריבוי הפריחה שלו, שאין בכח העץ להבשיל את כל הפירות המרובים היוצאים מהפריחה, ולכן משתמשים באבנים כדי להחליש מעט את כח העץ בשעת פריחתו. \u0003אלא סוקרו בסיקרא מאי\u0004 \u0005[מה,\u0006 איזו\u0005]\u0006 \u0003רפואה קעביד\u0004 \u0005[הוא עושה]\u0006 בכך?","ומסבירים: הדבר נעשה \u0003כי היכי דליחזייה אינשי וליבעו עליה רחמי\u0004 \u0005[כדי שיראוהו בני אדם ויבקשו עליו רחמים].\u0006 \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 על הנאמר \"והצרוע אשר בו הנגע בגדיו יהיו פרומים וראשו יהיה פרוע ועל שפם יעטה \u0003וטמא טמא יקרא\"\u0004 (ויקרא יג, מה): הטעם לכך שקורא ומודיע שהוא טמא, כי \u0003צריך להודיע צערו לרבים, ורבים יבקשו עליו רחמים. אמר רבינא: כמאן תלינן כובסי בדיקלא\u0004 \u0005[כדעת מי תולים אנחנו אשכולות תמרים לא\u0006 בשלים \u0005בדקל]\u0006 המשיר את תמריו — \u0003כי האי תנא\u0004 \u0005[\u0006כדעת \u0005תנא זה]\u0006 שצריך להודיע לרבים את צערו.","\u0003תני תנא\u0004 \u0005[שנה חוזר המשניות]\u0006 \u0003בפרק\u0004 התוספתא על מעשה \u0003אמוראי קמיה\u0004 \u0005[האמורי לפני]\u0006 \u0003ר' חייא בר אבין. אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003כולהו אית בהו\u0004 \u0005[כולם\u0006 הנמנים שם \u0005יש בהם]\u0006 \u0003משום דרכי האמורי, לבר מהני\u0004 \u0005[חוץ מאלה]:\u0006 \u0003מי שיש לו עצם בגרונו מביא\u0004 עצם \u0003מאותו המין\u0004 שנתקע בגרונו \u0003ומניח ליה על קדקדו, ולימא הכי\u0004 \u0005[ויאמר כך]:\u0006 \u0003\"חד חד נחית בלע, בלע נחית חד חד\"\u0004 \u0005[אחד אחד יורד\u0006 ו\u0005בולע, בולע\u0006 ו\u0005יורד אחד אחד]\u0006 \u0003\", ואין בו משום דרכי האמורי.\u0004","\u0003לאדרא לימא הכי\u0004 \u0005[לעצם דג\u0006 שבגרון \u0005יאמר כך]:\u0006 \u0003\"ננעצתא כמחט, ננעלתא כתריס, שייא שייא\u0004 \u0005[רד רד].\u0006"],["מתוך שדנו בדרכי האמורי מביאים ממה ששנינו בפרק \"אמוריים\" ובעוד מקורות דברים בנושא זה. \u0003האומר \"גד גדי, וסנוק לא אשכי ובושכי\u0004 \u0005[התמזל מזלי ועייף אל תהי ביום ובלילה]\u0006 \u0003\"\u0004— \u0003יש בו משום דרכי האמורי. ר' יהודה אומר:\u0004 דבר זה חמור מדרכי האמורי כי \u0003\"גד \" אינו אלא לשון עבודה זרה,\u0004 וכפי \u0003שנאמר:\u0004 \"ואתם עוזבי ה' השכחים את הר קדשי \u0003הערכים לגד שלחן\u0004 והממלאים למני ממסך\" (ישעיהו סה, יא), ויש בכך משום תפילה לעבודה זרה.","ואם בלילה מבקש אדם ש\u0003הוא\u0004 יקרא \u0003בשמה\u0004 של אשתו \u0003והיא בשמו\u0004 כסגולה — \u0003יש בו משום דרכי האמורי.\u0004","האומר \u0003\"דונו דני\"\u0004 \u0005[התחזקו חביותי]\u0006 — \u0003יש בו משום דרכי האמורי. ר' יהודה אומר:\u0004 הרי זה חמור יותר, כי \u0003אין \"דן \" אלא לשון עבודה זרה,\u0004 וכפי \u0003שנאמר: \"הנשבעים באשמת שמרון ואמרו חי אלהיך דן\"\u0004 (עמוס ח, יד).","\u0003האומר לעורב\u0004 שהוא שומעו קורא וחושש מפני סימן רע \u0003\"צרח\", ולעורבתא\u0004 \u0005[ולעורבת]\u0006 אומר \u0003\"שריקי והחזירי לי זנביך לטובה\"\u0004 — \u0003יש בו משום דרכי האמורי.\u0004","וכן \u0003האומר \"שחטו תרנגול זה\u0004 מפני \u0003שקרא ערבית\"\u0004 (בשעות הערב) או \u0003\"\u0004שחטו \u0003תרנגולת\u0004 זו \u0003שקראה גברית\u0004 (כמו תרנגול) — \u0003יש בו משום דרכי האמורי.\u0004","האומר \u0003\"אשתה ואותיר, אשתה ואותיר\"\u0004 כדי שיתרבה היין — \u0003יש בו משום דרכי האמורי.\u0004","\u0003המבקעת ביצים בכותל, והטח\u0004 אותן — \u0003בפני האפרוחים יש בו משום דרכי האמורי.\u0004 \u0003ו\u0004כן \u0003המגיס\u0004 הקדירה \u0003בפני\u0004 ה\u0003אפרוחים\u0004 כסגולה שלא ימותו — \u0003יש בו משום דרכי האמורי.\u0004","","וכן אשה \u0003המרקדת והמונה שבעים ואחד אפרוחים,\u0004 שחוזרת ומונה אותם עד שמגיעה למספר זה \u0003בשביל שלא ימותו\u0004 — \u0003יש בו משום דרכי האמורי.\u0004","האשה \u0003המרקדת לכותח,\u0004 שכשעושה כותת מרקדת כדי שיצליח, \u0003והמשתקת\u0004 את העומדים כסגולה כדי שיתבשלו היטב ה\u0003עדשים, והמצווחת\u0004 כסגולה שיתבשלו ה\u0003גריסין\u0004 — כל אלה \u0003יש בו משום דרכי האמורי.\u0004","\u0003המשתנת בפני קדירתה בשביל שתתבשל מהרה\u0004 — \u0003יש בו משום דרכי האמורי.\u0004 \u0003אבל נותנים קיסם של תות ושברי זכוכית בקדירה בשביל שתתבשל מהרה,\u0004 שבזה אין אמונה תפלה, אלא תועלת ממשית, \u0003וחכמים אוסרין בשברי זכוכית\u0004 לא משום האמונה התפלה, אלא \u0003מפני הסכנה\u0004 שמא לא יסננו אותם היטב אחר כך.","","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003נותנים בול\u0004 (גוש) \u0003של מלח לתוך הנר בשביל שתאיר ותדליק,\u0004 ויש בכך משום תועלת ולא כסגולה, ואין בכך חשש לדרכי האמורי. וכן \u0003נותנים טיט וחרסית תחת הנר בשביל שתמתין ותדליק\u0004 ולא תבער מהרה.","\u0003אמר רב זוטרא: האי מאן דמיכסי שרגא דמשחא ומגלי נפטא קעבר\u0004 \u0005[מי שמכסה את הנר,\u0006 בית הקיבול, \u0005של שמן ומגלה\u0006 בית קיבול \u0005של נפט עובר]\u0006 \u0003משום \"בל תשחית\",\u0004 שעל ידי כך חומר הבעירה כלה מהר בלא תועלת.","האומר בשעת שתיה \u0003\"חמרא וחיי לפום רבנן\"\u0004 \u0005[יין וחיים לפי חכמים]\u0006 — \u0003אין בו משום דרכי האמורי.\u0004 וכן \u0003מעשה בר' עקיבא שעשה משתה לבנו ועל כל כוס וכוס שהביא אמר: \"חמרא וחיי לפום רבנן, חיי וחמרא לפום רבנן ולפום תלמידהון\"\u0004 \u0005[יין וחיים לפי חכמים, חיים ויין לפי חכמים ולפי תלמידיהם].\u0006","","\u0003כלל גדול אמרו\u0004 חכמים בדיני \u0003שבת: כל השוכח עיקר שבת,\u0004 שאיננו יודע כלל שיש מצוות שבת בתורה, \u0003ועשה מלאכות הרבה בשבתות הרבה\u0004 — \u0003אינו חייב\u0004 כאשר נודע לו \u0003אלא\u0004 קרבן \u0003חטאת אחת\u0004 על כל אותן המלאכות. \u0003היודע עיקר שבת\u0004 אלא שנשכח ממנו יום השבת, כגון שטעה בימי השבוע \u0003ועשה מלאכות הרבה בשבתות הרבה\u0004 — \u0003חייב\u0004 כשנודע לו שהיתה זו מלאכה האסורה להביא קרבן חטאת \u0003על כל שבת ושבת.\u0004 ו\u0003היודע ש\u0004היום \u0003הוא שבת\u0004 אלא שלפי שעה שכח איסורן של מלאכות מסויימות, \u0003ועשה מלאכות הרבה בשבתות הרבה\u0004 — \u0003חייב\u0004 להביא קרבן חטאת \u0003על כל\u0004"],["\u0003אב מלאכה ומלאכה\u0004 (סוג מלאכה) שעשה. ואילו \u0003העושה מלאכות הרבה\u0004 שהן \u0003מעין מלאכה אחת,\u0004 כיון שהן נכללות בהגדרה אחת של אב מלאכה מסויים, \u0003אינו חייב אלא חטאת אחת.\u0004","מתחילה באים לברר את לשון המשנה, ושואלים: \u0003מאי טעמא תנא\u0004 \u0005[מה טעם שנה]\u0006 בלשון \u0003\"כלל גדול \"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דקבעי למיתני\u0004 \u0005[שרצה\u0006 התנא \u0005לשנות]\u0006 במשנה בהמשך הפרק \"ו \u0003עוד כלל אחר\u0004 אמרו\" שלא כלל בו אלא שתי הלכות, ועל כן במשנתנו שכללה יותר הלכות \u0003תנא\u0004 \u0005[שנה]\u0006 בה התנא בלשון \u0003\"כלל גדול\". וגבי\u0004 \u0005[ואצל]\u0006 \u0003שביעית נמי\u0004 \u0005[גם כן]\u0006 \u0003משום דקבעי למיתני\u0004 \u0005[שרצה\u0006 התנא \u0005לשנות]\u0006 במשנה (שביעית פ\"ז מ\"ב) לשון \u0003\"עוד כלל אחר \" תנא\u0004 \u0005[שנה]\u0006 שם בתחילת הפרק לשון \u0003\"כלל גדול\",\u0004 ותובן איפוא לשון זו אף במסכת שביעית. \u0003והא גבי\u0004 \u0005[ו\u0006אולם \u0005הרי אצל]\u0006 \u0003מעשר\u0004 שנאמרו שם במשנה (מעשרות פ\"א מ\"א) שני כללים בזה אחר זה, \u0003דקתני\u0004 \u0005[ששנה]\u0006 התנא בהמשך המשנה לשון \"ועוד \u0003כלל אחר\u0004 אמרו\", \u0003ו\u0004אף על פי כן \u0003לא תני\u0004 \u0005[שנה]\u0006 התנא בתחילתה בלשון \u0003\"כלל גדול\",\u0004 אלא \"כלל אמרו\"!","\u0003אמר ר' יוסי בר אבין:\u0004 הביטוי \"כלל גדול\" אכן אינו תלוי במציאותו של כלל נוסף, אלא בחשיבותו של הכלל. ולכן \u0003שבת ושביעית דאית בהו\u0004 \u0005[שיש בהם]\u0006 דינים שונים שחלקם \u0003אבות ו\u0004חלקם \u0003תולדות\u0004 — \u0003תנא\u0004 \u0005[שנה]\u0006 התנא במשנה בלשון \u0003\"\u0004כלל \u0003גדול\",\u0004 ואילו \u0003מעשר דלית\u0004 \u0005[שאין]\u0006 \u0003בה אבות ותולדות,\u0004 אלא לכל דיניו הגדרה זהה \u0003לא תנא\u0004 \u0005[שנה]\u0006 בלשון \u0003\"כלל גדול \".\u0004 ומקשים: \u0003ול\u0004גירסת המשניות של \u0003בר קפרא, דתני\u0004 \u0005[ששנה]\u0006 לשון \u0003\"כלל גדול \" במעשר, מאי\u0004 \u0005[מה,\u0006 אלו\u0005]\u0006 \u0003אבות ומאי\u0004 \u0005[ומה,\u0006 אלו\u0005]\u0006 \u0003תולדות איכא\u0004 \u0005[יש]\u0006 במעשר?","\u0003אלא לאו היינו טעמא\u0004 \u0005[האם לא זהו הטעם]\u0006 שבכל מקום שנאמר \"כלל גדול\" הרי הוא ביחס לכללים אחרים בהלכות אחרות; וכך יש להבין: \u0003גדול עונשו של שבת,\u0004 כלומר, התחום בו חלים דיני שבת והעונשים על חילולה \u0003יותר משל שביעית,\u0004 ש\u0003אילו שבת איתא\u0004 \u0005[ישנה,\u0006 הלכותיה חלות\u0005]\u0006 \u0003בין בתלוש\u0004 מן הקרקע ו\u0003בין במחובר, ואילו שביעית בתלוש ליתא\u0004 \u0005[אינה,\u0006 אין הלכותיה חלות\u0005]\u0006 ו\u0003במחובר איתא\u0004 \u0005[ישנה].\u0006 \u0003ו\u0004כן \u0003גדול עונשה של שביעית יותר מן המעשר,\u0004 ש\u0003אילו שביעית איתא\u0004 \u0005[ישנה]\u0006 מן התורה \u0003בין במאכל אדם\u0004 ו\u0003בין במאכל בהמה, ואילו מעשר במאכל אדם איתא\u0004 \u0005[ישנו]\u0006 ו\u0003במאכל בהמה ליתא\u0004 \u0005[אינו].\u0006","\u0003ול\u0004שיטת \u0003בר קפרא דתני\u0004 \u0005[ששנה]\u0006 לשון \u0003\"כלל גדול \"\u0004אף \u0003במעשר\u0004 יש להבין כך: \u0003גדול עונשו של מעשר יותר משל פיאה,\u0004 ש\u0003אילו\u0004 חובת \u0003מעשר איתא\u0004 \u0005[ישנה,\u0006 חלה\u0005]\u0006 מדברי סופרים גם \u0003בתאנה ו\u0004גם על \u0003ירק, ואילו פיאה ליתא\u0004 \u0005[אינה\u0006 שייכת\u0005]\u0006 \u0003בתאנה ו\u0004ב\u0003ירק. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת פיאה, \u0003כלל אמרו ב\u0004דין \u0003פיאה: כל שהוא אוכל, ונשמר, וגידולו מן הארץ, ולקיטתו כאחת, ומכניסו לקיום\u0004 — \u0003חייב בפיאה.\u0004","ומסבירים מה בא כל פרט בהגדרה זו להדגיש: מה שאמרו \u0003\"אוכל\"\u0004 — הרי זה בא \u0003למעוטי\u0004 \u0005[למעט,\u0006 להוציא\u0005]\u0006 \u0003ספיחי סטיס וקוצה\u0004 שלמעשה שימושם רק לצורך צביעה ולא למאכל, ולכך אין בהם דין פאה. ומה שאמרו \u0003\"ונשמר\"\u0004 — הרי זה בא \u0003למעוטי\u0004 \u0005[למעט,\u0006 להוציא\u0005]\u0006 גידולי \u0003הפקר,\u0004 שכיון שאינם נשמרים הריהם פטורים מן הפיאה. \u0003\"וגידולו מן הארץ\"\u0004 — הרי זה בא \u0003למעוטי\u0004 \u0005[למעט,\u0006 להוציא\u0005]\u0006 \u0003כמיהין ופטריות\u0004 שאינם כשאר הצמחים, ואין כוח גידולם מן האדמה, ולכך אי אפשר לומר עליהם שגידולם מן הארץ. \u0003\"ולקיטתו כאחת\"\u0004 — הרי זה בא \u0003למעוטי\u0004 \u0005[למעט,\u0006 להוציא\u0005]\u0006 \u0003תאנה\u0004 שפירותיה נלקטים במשך זמן רב, לפי שאינם מבשילים בבת אחת. \u0003\"ומכניסו לקיום\"\u0004 — הרי זה בא \u0003למעוטי\u0004 \u0005[למעט,\u0006 להוציא\u0005]\u0006 \u0003ירק,\u0004 שאין אדם אוצר (מקיים) אותו זמן ממושך במחסנים, כיון שאינו נשמר לאורך זמן.","\u0003ואילו גבי\u0004 \u0005[אצל]\u0006 \u0003מעשר תנן\u0004 \u0005[שנויה\u0006 משנה\u0005],\u0006 \u0003כלל אמרו במעשר: כל שהוא אוכל ונשמר וגידולו מן הארץ\u0004 — \u0003חייב במעשר. ואילו\u0004 התנאים של \u0003לקיטתו כאחת ומכניסו לקיום לא תנן\u0004 \u0005[שנינו],\u0006 ומכאן שתאנה וירקות נכנסים בגדר חובת המעשר, ורחב איפוא תחום חלות דיני מעשר מזה של הפיאה.","במשנה דובר בשוכח עיקר שבת, ויש צורך לברר כיצד יתכן שאדם מישראל ישכח את כל עיקרה של שבת. \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 מדברת \u0003בתינוק שנשבה לבין הגוים\u0004 ולא למד מאומה, או \u0003גר שנתגייר לבין הגוים\u0004 ולא ידע את דיני השבת. \u0003אבל\u0004 מי ש\u0003הכיר\u0004 פעם שיש שבת בעולם \u0003ולבסוף שכח\u0004 מאיזה טעם שהוא — \u0003חייב על כל שבת ושבת\u0004 כמי שיודע עיקר שבת. ומעתה באים לברר את השיטה ולמצות את פרטיה. \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003\"השוכח עיקר שבת\", לאו\u0004 \u0005[האם לא]\u0006 \u0003מכלל\u0004 לשון \"השוכח\" אתה למד \u0003דהויא ליה\u0004 \u0005[שהיתה לו]\u0006 \u0003ידיעה מעיקרא\u0004 \u0005[מתחילה]?!\u0006 שהרי שיכחה משמעה שנעלם דבר שהיה ידוע פעם, וקשה איפוא לשיטת רב ושמואל! ודוחים: \u0003לא, מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כל השוכח עיקר שבת\"\u0004 — ש\u0003היתה שכוח ממנו\u0004 מאז ומעולם \u0003עיקרה של שבת,\u0004 שלא ידע ממנה כלל.","ושוב מקשים: \u0003אבל\u0004 אם כן, לשיטה זו אם \u0003הכיר ולבסוף שכח מאי\u0004 \u0005[מה\u0006 יהא דינו\u0005]\u0006 — הריהו \u0003חייב על כל שבת ושבת,\u0004 אם כן \u0003אדתני\u0004 \u0005[עד שהוא שונה]\u0006 במשנה את הדין הבא ש\u0003היודע עיקר שבת ועשה מלאכות הרבה בשבתות הרבה\u0004 שהוא \u0003חייב\u0004 חטאת \u0003על כל שבת ושבת, ליתני\u0004 \u0005[שישנה]\u0006 במקום זאת \u0003\"הכיר ולבסוף שכח\", ו\u0004נבין מעצמנו ש\u0003כל שכן הא\u0004 \u0005[\u0006מקרה \u0005זה]\u0006 שהיודע ממש עיקרה של שבת וודאי שיהא חייב על כל שבת ושבת! ומתרצים: לשיטת רב ושמואל \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 הביטוי \u0003\"היודע עיקר שבת\"\u0004 — \u0003מי שהיה יודע עיקרה של שבת\u0004 פעם אבל עכשיו \u0003שכחה,\u0004 והוא הוא הדין שאפשר להוציא מדברי רב ושמואל."],["\u0003אבל\u0004 אם \u0003לא שכחה\u0004 את עיקרה של השבת, וידע שהיום שבת \u0003מאי\u0004 \u0005[מה]\u0006 יהא דינו — בודאי יהא \u0003חייב על כל מלאכה ומלאכה,\u0004 אם כן \u0003אדתני\u0004 \u0005[עד שהוא שונה\u0006 במשנה\u0005]\u0006 את הדין \u0003בהיודע שהוא שבת ועשה מלאכות הרבה בשבתות הרבה\u0004 שהוא \u0003חייב על כל מלאכה ומלאכה, ליתני\u0004 \u0005[שישנה]\u0006 את הדין ב\u0003היודע עיקר שבת, ו\u0004מכך נבין כי \u0003כל שכן הא\u0004 \u0005[זה],\u0006 שהיודע שהיום שבת ודאי יתחייב על כל מלאכה ומלאכה! \u0003אלא\u0004 בהכרח יש לומר כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 המדברת מענין השוכח, הכוונה היא \u0003כשהכיר ולבסוף שכח. ו\u0004דברי \u0003רב ושמואל נמי\u0004 \u0005[גם כן]\u0006 \u0003כהכיר ולבסוף שכח דמי\u0004 \u0005[נחשב],\u0006 \u0003והכי איתמר\u0004 \u0005[וכך נאמר]\u0006 כך יש להבין, ש\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כי \u0003אפילו תינוק שנשבה בין הגוים\u0004 או \u0003גר שנתגייר לבין הגוים\u0004 — \u0003כהכיר ולבסוף שכח דמי\u0004 \u0005[נחשב],\u0006 \u0003וחייב\u0004 להביא קרבן חטאת על שגגתו, אף שלא ידע מעולם.","\u0003ו\u0004אילו \u0003ר' יוחנן ור' שמעון בן לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כי \u0003דוקא\u0004 ב\u0003הכיר\u0004 פעם שיש שבת בעולם \u0003ולבסוף שכח\u0004 מאיזה טעם שהוא — חייב להביא קרבן, \u0003אבל תינוק שנשבה לבין הגוים\u0004 או \u0003גר שנתגייר לבין הגוים\u0004 — \u0003פטור\u0004 מקרבן, כאנוס. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא הדנה בנושא זה: \u0003כלל גדול אמרו ב\u0004דיני \u0003שבת: כל השוכח עיקר שבת,\u0004 שאיננו יודע כלל שיש מצות שבת בתורה, \u0003ועשה מלאכות הרבה בשבתות הרבה\u0004 — \u0003אינו חייב אלא אחת. כיצד?\u0004 — \u0003תינוק שנשבה לבין הגוים\u0004 ולא למד מאומה, או \u0003גר שנתגייר לבין הגוים\u0004 ואינו יודע דיני שבת, \u0003ועשה מלאכות הרבה בשבתות הרבה\u0004 — \u0003אינו חייב אלא חטאת אחת\u0004 על כל ששגג באיסורי שבת. \u0003ו\u0004כן \u0003חייב על\u0004 כל \u0003דם\u0004 שאכל בימיו בשגגה עד שנודע לו איסורו חטאת \u0003אחת, ועל החלב\u0004 שאכל — חטאת \u0003אחת, ועל עבודה זרה\u0004 שחטא בה — \u0003אחת. ו\u0004אילו החכם \u0003מונבז\u0004 היה \u0003פוטר\u0004 בכל אלה מקרבן כלל.","\u0003וכך היה מונבז דן לפני ר' עקיבא: הואיל ו\u0004העובר \u0003במזיד קרוי\u0004 בתורה \u0003\"חוטא\" ו\u0004אף העובר ב\u0003שוגג קרוי \"חוטא\",\u0004 עלינו להשוותם ככל האפשר, ולומר: \u0003מה מזיד\u0004 הרי זה דווקא באופן \u0003שהיתה לו ידיעה\u0004 קודמת שהדבר אסור — \u0003אף שוגג\u0004 הרי זה דווקא באופן \u0003שהיתה לו ידיעה.\u0004 ומי שלא היתה לו ידיעה קודמת כלל — אינו קרוי שוגג, אלא קרוב הוא להיות אנוס, ופטור לגמרי. \u0003אמר לו ר' עקיבא: הריני מוסיף על דבריך,\u0004 כלומר, אמשיך בקו המחשבה שלך ולפי אותה שיטה, עד למיצוי המסקנות, ונראה אם תסכים למסקנות אלה, ואומר: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מה\u0004 (כשם) ש\u0003מזיד\u0004 משמעו דווקא \u0003שהיתה הידיעה בשעת מעשה\u0004 בעבירה, שבשעה שעבר ידע שהוא חוטא — \u0003אף שוגג\u0004 תאמר \u0003שהיתה לו ידיעה בשעת מעשה,\u0004 וכיון שכן שוב איננו שוגג!","\u0003אמר לו\u0004 מונבז: \u0003הן,\u0004 ואין הדבר מוזר בעיני, ולדעתי אף הגדרה זו נכונה, \u0003וכל שכן שהוספת\u0004 על דברי, ובהגדרת השוגג יש להכניס גם את התנאי של ידיעה בשעת מעשה, וכאשר תבואר עוד שיטתו. \u0003אמר לו:\u0004 השוגג ש\u0003לדבריך,\u0004 כיון שבשעת מעשה יודע העבריין שהדבר אסור \u0003אין זה קרוי שוגג אלא מזיד\u0004 גמור.","ולענייננו: \u0003קתני מיהא\u0004 \u0005[בכל אופן שנינו]\u0006 \u0003כיצד תינוק\u0004 כדוגמא לשוכח עיקר שבת את המקרה של תינוק שנשבה. \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב ושמואל ניחא\u0004 \u0005[נוח\u0006 הדבר\u0005],\u0006 שהרי אף הם רואים תינוק שנשבה כשוגג ששכח עיקר שבת. \u0003אלא לר' יוחנן ולר' שמעון בן לקיש\u0004 הרואים זאת כאונס גמור ופוטרים, \u0003קשיא\u0004 \u0005[קשה],\u0006 שהרי לדעת חכמים במשנה חייב קרבן! \u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003לך\u0004 כתירוץ \u0003ר' יוחנן וריש לקיש: לא מי איכא\u0004 \u0005[האם אין]\u0006 את דעת \u0003מונבז\u0004 ש\u0003פטר\u0004 בכגון זה? \u0003אנן דאמרינן\u0004 \u0005[אנו שאמרנו]\u0006 דברינו — \u0003כמונבז\u0004 אמרנום.","לגופה של שיטת מונבז שואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003מונבז,\u0004 והאם סומך הוא לגמרי על הדימוי הלשוני ששניהם נקראו בלשון הכתוב \"חוטא\"? ומסבירים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004האזרח בבני ישראל ולגר הגר בתוכם \u0003תורה אחת יהיה לכם לעשה בשגגה\"\u0004 (במדבר טו, כט), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 הפסוק \u0003\"והנפש אשר תעשה ביד רמה\u0004 מן האזרח ומן הגר את ה' הוא מגדף ונכרתה הנפש ההיא מקרב עמה\u0003\"\u0004 (במדבר טו, ל), וממה ש\u0003הקיש\u0004 \u0005[השווה]\u0006 הכתוב \u0003שוגג למזיד\u0004 (\"תורה אחת\" וכו') למד אתה כי \u0003מה מזיד\u0004 מדובר באופן \u0003שהיתה לו\u0004 כבר \u0003ידיעה, אף שוגג\u0004 מדובר באופן \u0003שהיתה לו\u0004 כבר \u0003ידיעה.\u0004","ושואלים: \u0003ורבנן, האי\u0004 \u0005[וחכמים,\u0006 פסוק \u0005זה]\u0006 \u0003\"תורה אחת\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 ומשיבים: \u0003מיבעי להו לכדמקרי ליה\u0004 \u0005[צריכים\u0006 הם \u0005לו\u0006 לאותו ענין \u0005שלימד לו]\u0006 \u0003ר' יהושע בן לוי לבריה\u0004 \u0005[לבנו],\u0006 נאמר: \u0003\"תורה אחת יהיה לכם לעשה בשגגה\", וכתיב\u0004 \u0005[ונאמר]:\u0006"],["\u0003\"וכי תשגו ולא תעשו את כל המצות האלה\u0004 אשר דבר ה' אל משה\u0003\"\u0004 (במדבר טו כב), ולמדו חכמים שמקרא זה דן במיוחד בדיני עבודה זרה, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"והנפש אשר תעשה ביד רמה\u0004 את ה' הוא מגדף ונכרתה הנפש ההיא מקרב עמה\u0003\"\u0004 (במדבר טו, פסוק ל), ולמד מכאן כי \u0003הוקשו\u0004 \u0005[הושוו]\u0006 כל המצוות \u0003כולם לעבודה זרה: מה להלן\u0004 בעבודה זרה היא \u0003דבר שחייבים על זדונו כרת,\u0004 כאמור \"ונכרתה הנפש ההיא\", \u0003ו\u0004על \u0003שגגתו חטאת\u0004 כאמור שם. \u0003אף כל דבר שחייבין על זדונו כרת\u0004 הוא שחייבים \u0003על שגגתו חטאת.\u0004","ושואלים: \u0003ואלא מונבז\u0004 המקבל את ההנחה ששוגג כולל גם מי שידע בשעת מעשה שהדבר אסור, לדעתו אם כן \u0003שגגה במאי\u0004 \u0005[במה]?\u0006 שודאי שגג בדבר מה, שאם לא כן הריהו מזיד גמור! ומשיבים: \u0003כגון ששגג בקרבן,\u0004 שאמנם ידע שזו היא עבירה, אך לא ידע שעל חטא זה מביאים קרבן, וכיון שלא ידע את כל העונשים והכפרה על עבירה זו, הריהו נחשב לשוגג, ומביא קרבן חטאת על חטאו. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים על מונבז, לדעתם \u0003שגגת קרבן לא\u0004 \u0005[אין]\u0006 \u0003שמה שגגה.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 אם כן לדעתם \u0003שגגה במאי\u0004 \u0005[במה]\u0006 ומתי יחשב חוסר ידיעה כגורם לשגגה? \u0003ר' יוחנן אמר: כיון ששגג בכרת\u0004 ולא ידע שעונשה של עבירה זו כרת, \u0003אף על פי שהזיד בלאו,\u0004 שידע שיש בכך מצות לא תעשה בתורה — הרי זה שוגג. \u0003וריש לקיש אמר\u0004 שלדעת חכמים אינו נקרא שוגג \u0003עד שישגוג בלאו וכרת,\u0004 שלא ידע כלל שהדבר אסור מן התורה. ו\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון בן לקיש\u0004 — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ואם נפש אחת תחטא בשגגה מעם הארץ בעשותה אחת ממצוות ה' \u0003אשר לא תעשינה ואשם\"\u0004 (ויקרא ד, כז), ומשמעו: \u0003עד שישגוג בלאו וכרת שבה,\u0004 שהרי מן הכתוב נראה שאותו אדם אינו יודע שעשה אחת המצוות אשר לא תיעשינה, כלומר, שיש איסור מן התורה בעשייתן.","ושואלים: \u0003ור' יוחנן האי קרא\u0004 \u0005פסוק זה]\u0006 שהביא \u0003ר' שמעון בן לקיש\u0004 כראיה לדבריו \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה לכדתניא\u0004 \u0005[צריך הוא לו לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 לשון הכתוב \u0003\"מעם הארץ\"\u0004 (ויקרא ד, כז) בא ללמד שרק מקצת החוטאים (חלק מעם הארץ, ולא כולם) מביאים קרבן על חטאתם בשגגה. והכוונה: \u0003פרט למשומד,\u0004 שכאשר הוא חוטא בשגגה אינו חייב כלל להביא קרבן על חטאו זה אפילו אחר שחזר בתשובה גמורה. ואילו \u0003ר' שמעון בן אלעזר אומר משום\u0004 (בשם) \u0003ר' שמעון:\u0004 הלכה זו נלמדת מן המילים \u0003\"אשר לא תעשינה ואשם\",\u0004 וכך יש להבין: \u0003השב מ\u0004עצם \u0003ידיעתו,\u0004 כלומר העושה תשובה כאשר אך נודע לו שעבר עבירה — הוא ש\u0003מביא קרבן על שגגתו,\u0004 אבל מי ש\u0003לא שב מ\u0004עצם \u0003ידיעתו\u0004 את החטא, כמשומד, שגם כשנודעה לו העבירה אינו חושש באותה שעה לחטא — \u0003אינו מביא קרבן על שגגתו,\u0004 ור' יוחנן מבין את הכתוב כר' שמעון.","וממשיכים לדון בנושא, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 מספר \u0003אבות\u0004 ה\u0003מלאכות\u0004 האסורות בשבת הוא \u0003ארבעים חסר אחת\u0004 ואחר כך מובאת במשנה רשימה של כולן. \u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה,\u0004 במשנה זו: \u0003מנינא\u0004 \u0005[מנין]\u0006 זה של ארבעים חסר אחת \u0003למה לי?\u0004 מדוע לא די ברשימת המלאכות האסורות בלא למנות את מספרן? \u0003ואמר ר' יוחנן:\u0004 בא המנין ללמד \u0003שאם עשאן\u0004 את כל המלאכות האסורות \u0003כולן בהעלם אחד,\u0004 שנשכח ממנו האיסור שבדבר — \u0003חייב על כל אחת ואחת,\u0004 ונתנה המשנה איפוא סימן שיש בכך שלושים ותשע חטאות. ולכאורה \u0003היכי משכחת לה\u0004 \u0005[היכן תמצא אותה\u0006 דוגמה\u0005]\u0006 לשכחה של כל איסורי המלאכות כולן — הוי אומר \u0003בזדון שבת,\u0004 שידע אותו אדם ששבת היום, \u0003ושגגת\u0004 האיסור שב\u0003מלאכות,\u0004 שלא ידע שמלאכות אלה אסורות בשבת.","ומעתה \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 כי \u0003כיון ששגג בכרת אף על פי שהזיד בלאו\u0004 קרוי שוגג — \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה\u0006 אפשרות\u0005]\u0006 \u0003כגון\u0004 ש\u0003ידע לה\u0004 \u0005[אותה]\u0006 את ה\u0003שבת\u0004 מצד איסור ה\u0003לאו\u0004 שבתורה, ושגגתו היתה ששכח שיש באיסורי שבת איסור כרת, ומשום כך עבר. \u0003אלא ל\u0004שיטת \u0003ר' שמעון בן לקיש\u0004 ש\u0003אמר\u0004 שאין שוגג אלא \u0003עד שישגוג בלאו ובכרת\u0004 נמצא ששכח לגמרי את כל איסורי המלאכות שבשבת, ואם כן זה שאמרנו כי מדובר באופן ש\u0003ידע ליה\u0004 \u0005[אותה]\u0006 את ה\u0003שבת, יש לשאול: במאי\u0004 \u0005[במה]\u0006 ידע? שאם שכח את כל איסורי המלאכה שבשבת, כיצד אפשר לומר שאותו אדם הזיד בשבת? ומשיבים: ש\u0003ידעה בתחומין,\u0004 שידע שיש בשבת איסור לצאת מחוץ לתחום מסויים \u0003ואליבא\u0004 \u0005[ולשיטת]\u0006 \u0003ר' עקיבא,\u0004 שסבר שהאיסור לצאת בשבת מחוץ לתחום הוא מן התורה, ולא מתקנת חכמים בלבד.","ושואלים: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מיהו\u0006 התנא \u0005ששנה\u0006 למשנה \u0005זו ששנו חכמים]\u0006 \u0003שגג בזה ובזה,\u0004 ששכח גם את ענין השבת וגם את המלאכות — \u0003זהו שוגג\u0004 גמור \u0003האמור בתורה. הזיד בזה ובזה\u0004 — \u0003זו היא מזיד האמור בתורה. שגג בשבת והזיד במלאכות,\u0004 ששכח מענין השבת, אבל ידע כי מלאכות אלה אסורות בשבת, \u0003או ששגג במלאכות והזיד בשבת,\u0004 שלא ידע שמלאכות אלה אסורות, ואולם ידע שהשבת אסורה במלאכה, \u0003או\u0004 אפילו \u0003שאמר: יודע אני שמלאכה זו אסורה\u0004 בשבת, \u0003אבל איני יודע שחייבין עליה קרבן או לא\u0004 — הרי זה \u0003חייב\u0004 בקרבן כדין שוגג. \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 — \u0003כ\u0004שיטת \u0003מונבז,\u0004 שלדעתו שגגה בחוסר ידיעת קרבן אף היא נחשבת כשגגה.","\u0003אמר אביי: הכל מודים בשבועת ביטוי,\u0004 אם נשבע אדם לאסור דבר על עצמו או לקבל עליו חובה \u0003ש\u0004הדין הוא שכאשר הפר את שבועתו \u0003אין חייבין עליה קרבן\u0004 על עבירה זו \u0003עד שישגוג בלאו שבה,\u0004 ששכח שאסור מן התורה לעבור על שבועתו. ושואלים: \u0003\"הכל מודים\"\u0004 זה ששנינו, דעת \u0003מאן\u0004 \u0005[מי]\u0006 היא — ודאי דעת \u0003ר' יוחנן\u0004 היא, שאף שכרגיל אמר שדי בשגגת כרת, בדין זה אף הוא יודה. ואולם הרי בענין שבועה \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שיאמר כך, שהרי \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יוחנן\u0004 שאין צורך שיהא שוגג בלאו, הרי זה \u0003היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 איסור \u0003כרת, אבל הכא דליכא\u0004 \u0005[כאן שאין]\u0006 איסור \u0003כרת\u0004 — \u0003לא\u0004 אמר ר' יוחנן, ובודאי אף הוא יסכים שצריך שישגוג בלאו, ואם כן אין בדברי אביי לכאורה כל חידוש!","ומסבירים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 כי \u0003הואיל ו\u0004זה שהעובר על השבועה בשוגג \u0003חייב קרבן\u0004 — דבר \u0003חידוש הוא,\u0004 שהרי \u0003בכל התורה כולה לא אשכחן\u0004 \u0005[מצאנו]\u0006 איסור \u0003לאו דמייתי עליה\u0004 \u0005[שמביא עליו]\u0006 \u0003קרבן\u0004 אלא אם כן יש בו איסור כרת כשעשה זאת במזיד, \u0003והכא מייתי\u0004 \u0005[ו\u0006אילו \u0005כאן\u0006 הריהו \u0005מביא],\u0006 הייתי אומר \u0003כי\u0004 \u0005[\u0006ש\u0005כאשר]\u0006 \u0003שגג בקרבן\u0004 ולא ידע שחייבים בו \u0003נמי ליחייב\u0004 \u0005[גם כן יתחייב]\u0006 אף לשיטת חכמים החולקים בענין זה על מונבז,"],["על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 אביי שאין הדבר כן. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003איזהו שגגת שבועת\u0004 ביטוי \u0003לשעבר,\u0004 כלומר, כיצד ניתן למצוא דוגמא לאדם שנשבע לשקר על מאורע שהיה בעבר מתוך שגגה, אך לא משום שיכחת המאורע — הרי זה במקרה \u0003שאם אמר \"יודע אני ששבועה זו,\u0004 שהיא לשקר, \u0003אסורה, אבל איני יודע אם חייבין עליה קרבן או לא\"\u0004 — הרי זה \u0003חייב\u0004 בקרבן כשוגג הרי שבשבועת ביטוי אף שגגה בקרבן מוציאה מכלל מזיד! ודוחים: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003מונבז היא,\u0004 שלשיטתו כל שעבר עבירה כאשר לא ידע שיש חובת קרבן עליה הריהו נחשב כשוגג.","למשא ומתן זה בדברי אביי היתה גם \u0003לישנא אחרינא\u0004 \u0005[לשון אחרת],\u0006 שאחרי ציטוט ההלכה בשבועת ביטוי שואלים: משנה זו \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 כי שיטת \u0003מונבז\u0004 היא — והלא \u0003פשיטא\u0004 \u0005[\u0006\u0005פשוט,\u0006 מובן מאליו\u0005]\u0006 הדבר, שכן \u0003השתא\u0004 \u0005[הרי]\u0006 \u0003בכל התורה דלאו\u0004 \u0005[שלא]\u0006 \u0003חידוש הוא אמר\u0004 ש\u0003שגגת קרבן שמה שגגה, הכא\u0004 \u0005[כאן]\u0006 ש\u0003חידוש הוא\u0004 והקרבן בשבועת ביטוי חשוב משאר קרבנות חטאת — \u0003לא כל שכן\u0004 שיהא זה בכלל שגגה?! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא, ותיובתא\u0004 \u0005[וקושיה חמורה]\u0006 היא על \u0003אביי!\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיא חמורה]\u0006 היא ונדחו דבריו.","\u0003ואמר אביי: הכל מודים בתרומה שאין חייבין עליה,\u0004 אם אכלוה בשגגה, \u0003חומש,\u0004 כדין האוכל תרומה בשגגה, \u0003עד שישגוג בלאו\u0004 (לא תעשה) \u0003שבה.\u0004 ושואלים: זה ששנינו \u0003\"הכל מודים\"\u0004 הכוונה ל\u0003מאן\u0004 \u0005[מי]?\u0006 — ודאי הכוונה ל\u0003ר' יוחנן.\u0004 ואולם במקרה זה הלא הוא \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו]! שהרי, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יוחנן\u0004 ששגגה היא כשאין גם שגגה בלאו היה זה \u0003היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003כרת\u0004 כעונש לעבירה זו, אבל \u0003היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003כרת לא\u0004 אמר כן! ומשיבים: בכל זאת יש בכך חידוש, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי כיון שהאוכל תרומה במזיד עונשו מיתה בידי שמים, שמא \u0003מיתה במקום כרת עומדת, וכי\u0004 \u0005[וכאשר]\u0006 \u0003שגג במיתה,\u0004 שאינו יודע שזהו עונשה של עבירה זו, \u0003נמי ליחייב\u0004 \u0005[גם כן יתחייב]\u0006 כשוגג, כשם שחייב השוגג בכרת, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 אביי שאין הדבר כן. ואילו \u0003רבא אמר:\u0004 אכן, \u0003מיתה במקום כרת עומדת וחומש במקום קרבן קאי\u0004 \u0005[עומד],\u0006 שדיני השגגה במקום מיתה וחומש הריהם כבמקרה שיש בו כרת וקרבן.","\u0003אמר רב הונא:\u0004 מי ש\u0003היה מהלך בדרך או במדבר ואינו יודע אימתי\u0004 אמורה לחול \u0003שבת, מונה ששה ימים\u0004 מהיום שנודע לו ששכח את השבת \u0003ומשמר\u0004 אחרי ששה ימים אלה \u0003יום אחד\u0004 כשבת. \u0003חייא בר רב אומר: משמר\u0004 תחילה \u0003יום אחד\u0004 כדין שבת, \u0003ומונה\u0004 אחר כך \u0003ששה\u0004 ימי חול. ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון \u0005נחלקו]\u0006 — \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב הונא, \u0005סבור]\u0006 שנוהגים \u0003כברייתו של עולם,\u0004 שתחילה באים ששת ימי החול, ואחריהם שבת. ואילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חייא בר רב, \u0005סבור]\u0006 שנוהגים \u0003כאדם הראשון,\u0004 שכיון שהוא נברא ביום השישי לבריאת העולם, תחילה שמר שבת אחת ואחריה ששה ימי חול. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על חייא בר רב ממה ששנינו מברייתא: \u0003היה מהלך בדרך ואינו יודע אימתי שבת משמר יום אחד לששה.\u0004 ולכאורה \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 כוונת הדברים כי \u0003מונה ששה ומשמר יום אחד,\u0004 וכשיטת רב הונא?! ודוחים: \u0003לא,\u0004 אפשר לומר כי הכוונה היא ש\u0003משמר יום אחד ומונה ששה.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 רצה התנא לומר לא היה צריך לומר בלשון \u0003\"משמר יום אחד לששה\",\u0004 אלא \u0003\"משמר יום אחד ומונה ששה\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, בבירור. \u0003ועוד\u0004 קשה, שכן \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 במפורש: מי ש\u0003היה מהלך בדרך או במדבר ואינו יודע אימתי שבת, מונה ששה\u0004 ימים \u0003ומשמר יום אחד,\u0004 ו\u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא איפוא על \u0003ר' חייא בר רב!\u0004 ומעירים: אכן \u0003תיובתא\u0004 \u0005[קושיא חמורה]\u0006 היא על חייא בר רב, \u0003תיובתא,\u0004 \u0005[קושיא חמורה],\u0006 היא ונדחו דבריו.","\u0003אמר רבא:\u0004 אותו אדם שאינו יודע אימתי שבת ונוהג שבת לעצמו ביום אחד מימי השבוע, \u0003בכל יום ויום עושה לו\u0004 ומכין לעצמו מזון \u0003כדי פרנסתו, בר מההוא יומא\u0004 \u0005[חוץ מאותו יום]\u0006 שקבע לעצמו כשבת. ומקשים: \u0003וההוא יומא לימות\u0004 \u0005[ובאותו יום ימות]?!\u0006 אלא ודאי הכוונה היא \u0003דעביד\u0004 \u0005[שעושה]\u0006 \u0003מאתמול שתי פרנסות\u0004 לאותו יום וליום שלאחריו. ומקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 על פי האמת \u0003מאתמול שבת הואי\u0004 \u0005[היתה],\u0006 ולא זו בלבד שעשה מלאכה בשבת, אלא אף עשה בה מלאכה עבור יום חול! אלא: ב\u0003כל יום ויום עושה לו פרנסתו\u0004 לאותו היום, ו\u0003אפילו ההוא יומא\u0004 \u0005[אותו יום].\u0006 ואם תתמה: \u0003וההוא יומא במאי מינכר ליה\u0004 \u0005[ואותו היום\u0006 שהוא קובע אותו לו כשבת \u0005במה\u0006 הוא \u0005ניכר לו]?\u0006 יש לומר כי \u0003בקידושא ואבדלתא\u0004 \u0005[בקידוש והבדלה]\u0006 שהוא עושה באותו יום ולמוצאו הוא ניכר\u0005.\u0006","\u0003אמר רבא: אם היה מכיר מקצת היום שיצא בו,\u0004 שאינו זוכר איזה יום בשבוע הוא, אך זוכר שעבר מספר ימים מסויים מיום צאתו, כיון שזוכר, הרי אותו יום בשבוע שיצא בו (אף שאינו יודע איזה יום הוא) \u0003עושה\u0004 בו \u0003מלאכה כל היום כולו\u0004 בלא פקפוק, שבודאי לא יצא מביתו בשבת. על כך מקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הדבר, ומה חידש לנו בכך? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 כי \u0003כיון\u0004 שב\u0003שבת לא נפיק\u0004 \u0005[יצא],\u0006 \u0003במעלי שבתא נמי\u0004 \u0005[בערב שבת גם כן]\u0006 \u0003לא נפיק\u0004 \u0005[יצא],\u0006 \u0003והאי, אי נמי בחמשה בשבתא נפיק\u0004 \u0005[ו\u0006אדם \u0005זה, אם גם כן ב\u0006יום \u0005חמישי יצא]\u0006 — \u0003לישתרי ליה למיעבד\u0004 \u0005[יותר לו לעשות\u0006\u0003] מלאכה\u0004 גמורה \u0003תרי יומי\u0004 \u0005[שני ימים],\u0006 כלומר, ביום השמיני ליציאתו וביום התשיעי, שהם היום בשבוע שיצא בו, והיום שאחריו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי \u0003זימנין דמשכח שיירתא ומקרי ונפיק\u0004 \u0005[פעמים שמוצא שיירה ומזדמן שיוצא]\u0006 אף בערב שבת לדרך, ואין להתיר לו אם כן לעשות מלאכה ביום שאחרי יום צאתו.","שנינו שמשנתנו מחלקת להלכה בין \u0003היודע עיקר שבת,\u0004 לבין מי שאינו יודע. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 מה בסיסם במקרא? \u0003אמר רב נחמן אמר רבה בר אבוה: תרי קראי כתיבי\u0004 \u0005[שני כתובים נאמרו],\u0006 במקום אחד נאמר: \u0003\"ושמרו בני ישראל את השבת\u0004 לעשות את השבת לדורותם ברית עולם\u0003\"\u0004 (שמות לא, טז), \u0003וכתיב\u0004 \u0005[ו\u0006במקום אחר \u0005נאמר]:\u0006 \u0003\"ואת שבתתי תשמרו\u0004 ומקדשי תיראו אני ה'\u0003\"\u0004 (ויקרא כו, ב). \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניתן לפרש מדוע נאמר פעם אחת שבת בלשון יחיד, ופעם אחרת שבת בלשון רבים? יש להבין כך: \u0003\"ושמרו בני ישראל את השבת\"\u0004 — \u0003שמירה אחת לשבתות הרבה,\u0004 שאם עבר פעמים אחדות — מתחייב במקרים מסויימים רק קרבן אחד. ואילו \u0003\"ואת שבתתי תשמרו\"\u0004 — הכוונה ל\u0003שמירה אחת לכל שבת ושבת\u0004 לעצמה, וחטאות מרובות כמספר הפעמים שחילל שבת.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על סברה זו\u0005]\u0006 \u0003רב נחמן בר יצחק: אדרבה\u0004 \u0005[להיפך],\u0006 \u0003איפכא מסתברא\u0004 \u0005[ההיפך מסתבר]\u0006 לומר, ונבין כך: \u0003\"ושמרו בני ישראל את השבת \"\u0004הרי זו \u0003שמירה אחת לכל שבת ושבת\u0004 לחוד. \u0003\"ואת שבתתי תשמרו\"\u0004 כוונתו — \u0003שמירה אחת לשבתות הרבה,\u0004 ומכל מקום אף רב נחמן בר יצחק סבור שמהשוואת פסוקים אלה נלמדת ההלכה שבמשנתנו.","שנינו במשנה שיש הבדל בין \u0003היודע שהוא שבת\u0004 לבין השוכח עיקר שבת ועשה מלאכות."],["\u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[במה שונה ההתחלה,\u0006 השוכח עיקר שבת, \u0005ובמה שונה הסוף,\u0006 היודע עיקר שבת\u0005]?\u0006 \u0003אמר רב ספרא: כאן\u0004 שידע עיקר שבת הרי \u0003מידיעת שבת הוא פורש,\u0004 שכאשר נודע לו שעשה מלאכה, ואומרים לו \"שבת היום\" — פוסק ממלאכתו. \u0003וכאן\u0004 כשנשכחה ממנו המלאכה — \u0003מידיעת מלאכה הוא פורש,\u0004 שכשאומרים לו \"מלאכה זו אסורה\" הריהו פורש מעשייתה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן\u0004 לרב ספרא: \u0003כלום פריש\u0004 \u0005[\u0006הוא \u0005פורש]\u0006 \u0003משבת אלא משום\u0004 שיודע הוא שה\u0003מלאכות\u0004 אסורות בה, והרי אם לא היה יודע שיש איסור במלאכה שהוא עושה לא היה פורש ממנה רק משום ששבת היום. \u0003ו\u0004כן \u0003כלום\u0004 פורש הוא \u0003ממלאכות,\u0004 כשאומרים לו מלאכה זו אסורה, \u0003אלא משום\u0004 שיודע הוא ש\u0003שבת\u0004 היום, והרי אם לא היה יודע ששבת היום לא היה פורש מהמלאכה\u0003.\u0004 ולכן, נימוק זה להבדלי הדינים משום מה שנודע לו לעושה בשגגה לכאורה אינו נכון. \u0003אלא אמר רב נחמן:\u0004 יש לפרש כי ה\u0003קרבן דחייב רחמנא אמאי\u0004 \u0005[שחייבה התורה, על מה]\u0006 חייבה — על ה\u0003שגגה,\u0004 ודנים אם כן בדבר לא על פי מה שנודע לו אלא לפי מה שנשכח (שגג) ממנו. ואם כן \u0003התם חדא שגגה, הכא טובא\u0004 \u0005[שם\u0006 כשיודע רק עיקר שבת \u0005שגגה אחת היתה\u0006 בידו, \u0005כאן הרבה]\u0006 \u0003שגגות הויין\u0004 \u0005[הן]\u0006 ומביא קרבנות כמספר השגגות שהיו בידו.","שנינו במשנה ש\u0003חייב\u0004 קרבן \u0003על כל מלאכה ומלאכה\u0004 שעשה בשבת. ושואלים: \u0003חילוק מלאכות,\u0004 שאם עשה מלאכות רבות האסורות בשבת בהעלם אחד נחשבת כל אחת מהן כעבירה לעצמה לענין עונש \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דבר זה? \u0003אמר שמואל, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ושמרתם את השבת כי קודש היא לכם \u0003מחלליה מות יומת\"\u0004 (שמות לא, יד), ומלשון ריבוי של \"מות יומת\" למדים אנו כי \u0003התורה רבתה מיתות הרבה על חילול אחד,\u0004 שאף שנעשו כמה חילולים בהעלם אחד, כל אחד מהם נחשב לענין עונש כעבירה לעצמו. ומקשים: \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 הלא \u0003במזיד כתיב\u0004 \u0005[נאמר],\u0006 והלא אנו דנים בקרבנות הבאים על השגגה! ומשיבים: \u0003אם אינו ענין ל\u0004ענין \u0003מזיד,\u0004 שהרי פסוק זה לא בא ללמדנו הלכה במזיד, \u0003דכתיב\u0004 \u0005[ש\u0006הרי כבר \u0005נאמר]:\u0006 \u0003\"\u0004ששת ימים תעשה מלאכה וביום השביעי יהיה לכם קודש שבת שבתון לה' \u0003כל העשה\u0004 בו \u0003מלאכה יומת\"\u0004 (שמות לה, ב), על כן \u0003תנהו ענין ל\u0004ענין \u0003שוגג,\u0004 לומר שהוא בא ללמד דין מיתה בחילול שבת באופן כללי לכל ההלכות שבשבת ואף לשוגג. \u0003ומאי\u0004 \u0005[ומה\u0006 משמעות\u0005]\u0006 \u0003\"יומת\"\u0004 שנאמר בכתוב, שהרי העובר בשוגג ודאי אינו חייב מיתה! — \u0003יומת בממון,\u0004 שיצטרך לשלם עבור קרבנות רבים לכפר על חטאיו.","ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו,\u0006 ילמד\u0005]\u0006 \u0003חילוק מלאכות מהיכא דנפקא ליה\u0004 \u0005[מהיכן שיצאה\u0006 הלכה זו \u0005לו]\u0006 \u0003לר' נתן! דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נתן אומר:\u0004 נאמר \u0003\"לא תבערו אש בכל משבתיכם ביום השבת\"\u0004 (שמות לה, ג), ו\u0003מה תלמוד לומר\u0004 בהלכה זו, שהרי עצם איסור ההבערה כלול כבר באיסור המלאכה הכללי בשבת! אלא יש להבין בדרך זו: \u0003לפי שנאמר\u0004 כבר \u0003\"ויקהל משה את כל עדת בני ישראל\u0004 ויאמר אליהם \u0003אלה הדברים\u0004 אשר ציוה ה' לעשות אותם \u0003ששת ימים תעשה מלאכה\u0004 וביום השביעי יהיה לכם קודש שבת שבתון לה'\u0003\"\u0004 (שמות לה, א–ב), והוא לומד בדרך זו: המלים \"אלה הדברים\" המתייחסות לדיני שבת יש בהן הדגשות יתירות שאינן מחוייבות מעצם בניינו של המשפט, ולא באו אלא ללמדנו הלכה. שדי היה לומר \"דבר\" ואם נאמר \u0003\"דברים \"\u0004בלשון רבים, למדנו שנים (שמיעוט רבים שנים), \u0003\"הדברים\"\u0004 מוסיף לפחות שלישי, על ידי ההדגשה שבה\"א הידיעה. \"אלה\" הריהו לפי חשבון הגימטריה של האותיות שלושים ושש, נמצא ש\u0003\"אלה הדברים\"\u0004 מרמזים ל\u0003שלשים ותשע מלאכות שנאמרו למשה בסיני. \u0004","\u0003יכול אם עשאן כולן בהעלם אחד,\u0004 ששכח את האיסור שבכולן ועשאן אינו \u0003חייב\u0004 להביא אלא חטאת \u0003אחת?\u0004 — \u0003תלמוד לומר: \"\u0004ששת ימים תעבוד וביום השביעי תשבות \u0003בחריש ובקציר תשבת\"\u0004 (שמות לד, כא), הרי שיש איסורים מפורטים הן לגבי חרישה והן לגבי קצירה. \u0003ועדיין אני אומר\u0004 (יכול לומר): \u0003על\u0004 ה\u0003חרישה ועל הקצירה חייב שתים\u0004 כפי שנאמר בפירוש, \u0003ועל\u0004 שאר המלאכות \u0003כולן אינו חייב אלא אחת?!\u0004 על כן \u0003תלמוד לומר\u0004 פסוק זה: \u0003\"לא תבערו אש\u0004 בכל מושבותיכם ביום השבת\u0003\"\u0004 (שמות לה, ג), ולמדים בשיטה זו: \u0003הבערה בכלל\u0004 כל המלאכות \u0003היתה, ולמה יצאת\u0004 (יצאה) מכללן שיאמר בה הכתוב איסור מפורש — \u0003להקיש\u0004 (להשוות) \u0003אליה, ולומר לך\u0004 שיש כאן פרט שיצא ללמד כדוגמא על הכלל כולו: \u0003מה הבערה שהיא אב מלאכה וחייבין עליה בפני עצמה, אף כל\u0004 עשייה \u0003שהוא אב מלאכה\u0004 — \u0003חייבין עליה בפני עצמה.\u0004 ומאחר שהביא ר' נתן דרך להוכיח שעל כל מלאכה ומלאכה בשבת יש חיוב מיוחד, מדוע לא יסביר שמואל כר' נתן?","ומשיבים: \u0003שמואל סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' יוסי\u0004 שאינו מקבל דרשה זו של ר' נתן. ששנינו ש\u0003אמר\u0004 ר' יוסי שהאיסור שנאמר ב\u0003הבערה\u0004 — \u0003ללאו יצאת,\u0004 כלומר ללמדנו שהבערה בשבת איננה כשאר כל המלאכות בשבת שחייבים עליהן סקילה או כרת, אלא קלה היא מכולן, והמבעיר אש בשבת עובר רק על איסור \"לא תעשה\" בלבד. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 האיסור שנאמר ב\u0003הבערה\u0004 — \u0003ללאו יצאת,\u0004 אלו \u0003דברי ר' יוסי.\u0004 ואילו \u0003ר' נתן אומר:\u0004 דין הבערה הריהו כשאר כל המלאכות בשבת, אלא ש\u0003לחלק\u0004 בין המלאכות השונות ולהדגיש את החיוב שבכל אחת מהן \u0003יצאת.\u0004","ועוד מקשים על שמואל: אם אמנם סבור הוא כר' יוסי בענין איסור הבערה, \u0003ותיפוק ליה\u0004 \u0005[ותצא,\u0006 תילמד \u0005לו]\u0006 הלכה זו \u0003ל\u0004ענין \u0003חלוק מלאכות מהיכא דנפקא ליה\u0004 \u0005[מהיכן שיצאה,\u0006 נלמדה \u0005לו]\u0006 \u0003ל\u0004שיטת \u0003ר' יוסי\u0004 עצמו! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר,\u0004 נאמר: \u0003\"\u0004דבר אל בני ישראל לאמור נפש כי תחטא בשגגה מכל מצוות ה' אשר לא תעשנה \u0003ועשה מאחת מהנה\"\u0004 (ויקרא ד, ב), ומדיוק הלשון למד הוא: \u0003פעמים שחייבים\u0004 להביא חטאת \u0003אחת על\u0004 העבירות \u0003כולן, ופעמים שחייבין על כל אחת ואחת\u0004 מחלקי העבירה. \u0003ואמר ר' יוסי בר' חנינא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי\u0004 — שהוא דורש את הלשון המיוחדת כאן, שאנו למדים מדיוק הביטוי \"מאחת מהנה\". כי די היה לומר \u0003\"אחת\"\u0004 ונאמר \u0003\"מאחת\",\u0004 וכן די היה לומר \u0003\"הנה\"\u0004 ונאמר \u0003\"מהנה\".\u0004 ולמדים אנו שיש מקרים שעבירה \u0003אחת שהיא\u0004 לגבי העונשים \u0003הנה,\u0004 כלומר רבות. ו\u0003\"הנה\" שהיא אחת.\u0004","ועוד יש להבין: \u0003אחת\u0004 שמשמעו עבירה שלימה, הרי זה לדיני שבת, כגון שכתב שם מלה שלמה שנתכוון לה כמו \u0003שמעון. \"מאחת\"\u0004 משמעו שעשה רק מקצתה של עבירה,"],["כגון שכתב מקצת המלה, למשל האותיות \u0003שם משמעון. \"הנה\"\u0004 משמעו — שעשה את פרטי העבירה העיקריים שהם \u0003אבות\u0004 המלאכה, \u0003\"מהנה\"\u0004 משמעו — דברים משניים הנובעים מן העיקריים והם \u0003תולדות. אחת שהיא הנה,\u0004 שהיא עבירה אחת שהיא רבות — כגון \u0003זדון שבת,\u0004 שידע ששבת היום, \u0003ושגגת מלאכות,\u0004 שלא ידע שמלאכות אלה אסורות, שבחילול שבת זה חייב על כל אב מלאכה. \u0003הנה שהיא אחת\u0004 — \u0003שגגת שבת,\u0004 ששכח את היום, \u0003וזדון מלאכות,\u0004 שידע שמלאכות אלה אסורות בשבת, ואינו חייב עליהן אלא חטאת אחת. הרי שיש לר' יוסי מקור לחילוקים במלאכות שבת, ומדוע לא אמר כך גם \u0003שמואל?\u0004 ומתרצים: לימוד זה של \u0003\"אחת שהיא הנה \" ו\"הנה שהיא אחת\"\u0004 — \u0003לא משמע ליה\u0004 \u0005[שמע אותו],\u0006 לא קבלו.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבא מרב נחמן: העלם זה וזה בידו,\u0004 ששכח ששבת היום וגם שמלאכה זו אסורה בשבת, \u0003מהו\u0004 דינו בכגון זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הרי העלם שבת בידו, ואינו חייב אלא\u0004 חטאת \u0003אחת.\u0004 אמר לו רבא: \u0003אדרבא\u0004 \u0005[להיפך],\u0006 \u0003הרי העלם מלאכות בידו\u0004 ויהא \u0003חייב על כל אחת ואחת\u0004 מן המלאכות שעשה! \u0003אלא אמר רב אשי: חזינן אי\u0004 \u0005[רואים אנו אם],\u0006 \u0003משום\u0004 ידיעת \u0003שבת\u0004 שנודע לו שהיום שבת \u0003קא פריש\u0004 \u0005[פורש]\u0006 מן המלאכה שעושה — \u0003הרי העלם שבת בידו, ואינו חייב אלא אחת, ואי\u0004 \u0005[ואם]\u0006 \u0003משום מלאכה קפריש\u0004 \u0005[הוא פורש]\u0006 — \u0003הרי העלם מלאכות בידו, וחייב על כל אחת ואחת. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: כלום\u0004 הרי הוא \u0003פריש\u0004 \u0005[פורש]\u0006 \u0003משבת אלא משום מלאכות,\u0004 שיודע שאסורה עשיית מלאכה בה, \u0003כלום פריש\u0004 \u0005[פורש]\u0006 \u0003ממלאכות אלא משום שבת,\u0004 שיודע שהיום שבת, שהרי כשאומרים לו לאדם העושה מלאכה, \"שבת היום\" ממילא מבין הוא שהמלאכה שהוא עושה אסורה בשבת, וכן כשאומרים לו \"מלאכה זו אסורה\" ופורש ממנה — הרי זה משום שיודע ששבת היום, \u0003אלא לא שנא\u0004 \u0005[אינו שונה,\u0006 אין הבדל\u0005],\u0006 ואין לראות בכך אלא שגגה אחת.","ועוד דנים בדבר מצד אחר, במשנה מצויה רשימת אבות המלאכות, ומתחילה נאמר בה \u0003אבות מלאכות ארבעים חסר אחת, והוינן\u0004 \u0005[והיינו\u0006 \u0003עוסקים] בה\u0004 במשנה זו, ושאלנו: \u0003מנינא\u0004 \u0005[המנין]\u0006 שהוזכר בה \u0003למה לי? ואמר ר' יוחנן:\u0004 בא המנין ללמד \u0003שאם עשאן כולן בהעלם אחד\u0004 — \u0003חייב על כל אחת ואחת.\u0004 ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי מי ש\u0003העלם זה וזה בידו חייב על כל אחת ואחת\u0004 — \u0003שפיר\u0004 \u0005[יפה\u0006 הדבר, מובן\u0005],\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי מי ש\u0003העלם שבת בידו אינו חייב אלא אחת, היכי משכחת לה\u0004 \u0005[איפה תמצא אותה]\u0006 הזדמנות שישכח אדם את כל המלאכות כולן, ועם זאת יהא בכך \u0003זדון שבת ושגגת\u0004 כל ה\u0003מלאכות?\u0004","\u0003הניחא אי סבר ליה\u0004 \u0005[זה נוח אם יסבור]\u0006 \u0003כ\u0004שיטת \u0003ר' יוחנן\u0004 ש\u0003אמר : כיון ששגג בכרת אף על פי שהזיד בלאו\u0004 הרי זו שגגה, ואז \u0003משכחת לה\u0004 \u0005מוצא אתה\u0006 מקרה כזה כאשר \u0003ידע ליה\u0004 \u0005[אותה]\u0006 את ה\u0003שבת\u0004 רק מצד איסור \u0003לאו\u0004 (לא תעשה) שיש בה, ושגג בכל המלאכות — שלא ידע שענוש כרת עליהן. \u0003אלא אי סבר לה\u0004 \u0005[אם סבור\u0006 \u0003הוא] כ\u0004שיטת \u0003ר' שמעון בן לקיש\u0004 ש\u0003אמר\u0004 שאין שגגה אלא \u0003עד שישגוג בלאו וכרת\u0004 שבה, אם כן יש לתמוה: \u0003דידע ליה\u0004 \u0005שיודע אותה\u0006 את ה\u0003שבת במאי\u0004 \u0005[במה]?\u0006 שאם נעלמו ממנו כל שלושים ותשע המלאכות, ואף אינו יודע שיש בהן איסור לא תעשה, אם כן מה ידיעת שבת יש בידו? ומשיבים: דבר זה יתכן בכל זאת, ש\u0003ידע לה\u0004 \u0005[אותה]\u0006 את השבת משום איסור \u0003תחומין ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003ר' עקיבא\u0004 שמן התורה אסורה היציאה מן התחום בשבת.","\u0003אמר רבא:\u0004 מי ש\u0003קצר וטחן כ\u0004שיעור \u0003גרוגרת,\u0004 שהוא השיעור הקטן ביותר שמתחייבים בו על מלאכת קצירה וטחינה בשבת, ועשה זאת \u0003בשגגת שבת וזדון מלאכות,\u0004 שלא ידע שהיום שבת, ואולם ידע שמלאכות אלה אסורות, \u0003ו\u0004לא נודע לו שחטא עד ש\u0003חזר\u0004 שוב אותו אדם \u0003וקצר וטחן כגרוגרת בזדון שבת ושגגת מלאכות,\u0004 שידע ששבת היום, אבל לא ידע שאלו המלאכות אסורות, \u0003ו\u0004אחרי כן \u0003נודע לו\u0004 שעבר \u0003על קצירה וטחינה של שגגת שבת וזדון מלאכות\u0004 והפריש קרבן חטאת לכפר על חטאו וכאמור צריך להפריש רק חטאת אחת, אף שעשה שני אבות מלאכה באותה שגגה. \u0003ו\u0004לאחר זמן \u0003חזר ונודע לו על\u0004 ה\u0003קצירה ועל\u0004 ה\u0003טחינה\u0004 ששגג בהן כשהיה זה \u0003זדון שבת ושגגת מלאכות,\u0004 והיה דינו להביא איפוא שני קרבנות חטאת, אחד על הקצירה ואחד על הטחינה."],["\u0003קצירה\u0004 בשגגת שבת, \u0003גוררת\u0004 ומכפרת אתה גם את השגגה השניה של ה\u0003קצירה\u0004 שבעשה בשגגת המלאכה שהיה חייב עליה חטאת לעצמה. וכן, החטאת שכיפרה על חטאו שחטא ב\u0003טחינה\u0004 של שגגת שבת \u0003גוררת\u0004 עמה כפרה לשגגת ה\u0003טחינה\u0004 שעשה בשגגת המלאכה. שכן הבאת הקרבן היתה לאחר שעבר שתי עבירות אלה, ואפילו עשה כמה פרטי עבירה בהעלם אחד הריהו מתכפר בקרבן אחד. \u0003אבל\u0004 אם באותו מקרה אירע לו בדרך אחרת, ש\u0003נודע לו על קצירה של זדון שבת ושגגת מלאכות\u0004 והפריש קרבן לכפר על שגגה זו, ואחרי כן נודע לו ששגג בקצירה וטחינה מתוך שכחת השבת. הרי במקרה זה, הכפרה שמביא על ה\u0003קצירה גוררת\u0004 כפרה על ה\u0003קצירה\u0004 הקודמת וגם על ה\u0003טחינה שעמה,\u0004 שהרי בשגגת השבת הקצירה והטחינה כחטא אחד הן, וכפרה באחת מהן מכפרת גם על השנייה, \u0003ו\u0004אילו \u0003טחינה שכנגדה\u0004 שעשה יחד עם הקצירה האחרונה — \u0003במקומה עומדת\u0004 ולא נתכפרה, ולכשתוודע לו יביא קרבן מיוחד לכפר עליה.","ו\u0003אביי אמר : טחינה נמי\u0004 \u0005[גם כן]\u0006 \u0003גוררת טחינה,\u0004 שכן \u0003שם טחינה אחת היא\u0004 וכיון שנתכפרה לו עבירת טחינה אחת, חוזרת ומתכפרת לו אף עבירת הטחינה השנייה, כיון שכולן נעשו בהעלם ובלא שיתגלה הדבר עד אחר מעשה. ושואלים, לעצם הסברה, \u0003ומי אית ליה\u0004 \u0005[והאם יש לו]\u0006 \u0003לרבא\u0004 שיטה זו של כפרה ב\u0003גרירה? והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שיש מחלוקת בדבר, ובמקרה זה מי ש\u0003אכל שני זיתי חלב בהעלם אחד\u0004 כגון שהיו שתי חתיכות חלב אלה משני חלקים בבהמה, והוא חשב שאינם חלב אלא שומן. ועל שגגה זו חייבים קרבן חטאת, \u0003ונודע לו על אחת מהן\u0004 שהוא חלב \u0003וחזר ואכל כזית\u0004 שלישי \u0003בהעלמו של\u0004 החלב ה\u0003שני.\u0004 שעדיין לא נודע לו שאותה חתיכה היא חלב, ואחר אכילת שניהם נודע לו אף עליה. \u0003אמר רבא:\u0004 אם \u0003הביא קרבן על\u0004 ה\u0003ראשון\u0004 — הרי כזית \u0003ראשון ושני מתכפרין\u0004 שהרי חטא בשניהם בהעלם אחד, אך \u0003שלישי אינו מתכפר\u0004 שכן מפסיקה ידיעתו על כזית אחד.","\u0003הביא קרבן על השלישי\u0004 לאחר שנודע לו שחטא בכך, \u0003שלישי ושני מתכפרין,\u0004 שהרי שניהם נעשו בהעלם אחד, אך ה\u0003ראשון\u0004 שהוא בהעלם אחר \u0003אינו מתכפר. הביא קרבן על האמצעי\u0004 — \u0003נתכפרו כולן,\u0004 לפי שגם בכזית הראשון וגם בשלישי היתה העלמה משותפת עם הכזית שני. \u0003אביי אמר: אפילו הביא קרבן על אחד מהן,\u0004 איזה שיהיה — \u0003נתכפרו כולן\u0004 משום גרירה, שכיון שנתכפר אחד מהם גוררת הכפרה גם את האחר שיש לו שותפות עמו בצד מסויים בהעלם. ובכל אופן הרי שרבא אינו מקבל את סברת ה\"גרירה\" בכפרה, ומדוע אומר הוא שקצירה גוררת קצירה? ומשיבים: \u0003בתר\u0004 ש\u0003שמעה\u0004 לסברה זו \u0003מאביי סברה\u0004 \u0005[קיבל אותה].\u0006 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שרבא מקבל את שיטת הגרירה, \u0003טחינה נמי\u0004 \u0005[גם כן]\u0006 \u0003תגרר לטחינה\u0004 מאותו נימוק! ומשיבים: יש לחלק ולומר כי אמנם את סברת \u0003גרירה אית ליה\u0004 \u0005[יש לו,\u0006 הריהו מקבל\u0005],\u0006 ואולם \u0003גרירה\u0004 של \u0003גרירה לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005].\u0006 וכיון שנתכפר אף על טחינה בדרך גרירה, שוב אינה יכולה להוסיף ולגרור עמה כפרת טחינה אחרת.","ומעירים כי \u0003מילתא דפשיטא להו\u0004 \u0005[דבר ש\u0006היה \u0005פשוט להם]\u0006 \u0003לאביי ורבא\u0004 שזדון שבת ושגגת מלאכות מצטרפים לשגגת שבת \u0003מבעיא\u0004 \u0005[היה מסופק]\u0006 \u0003לר' זירא. דבעי\u0004 \u0005[ששאל]\u0006 \u0003ר' זירא מר' אסי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי שאלה זו \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' ירמיה מר' זירא: קצר וטחן\u0004 בשיעור כ\u0003חצי גרוגרת בשגגת שבת וזדון מלאכות,\u0004 כיון שהוא פחות מן השיעור המחייב ודאי אינו חייב עליו מן התורה, \u0003וחזר וקצר וטחן חצי גרוגרת בזדון שבת ושגגת מלאכות, מהו שיצטרפו\u0004 לשיעור אחד, ויביא חטאת כשיוודע לו הדבר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חלוקין\u0004 הם \u0003לחטאות,\u0004 שעל כל סוג שגגה יצטרך להביא חטאת לעצמה, \u0003ולא מצטרפי\u0004 \u0005[ואינם מצטרפים].\u0006","והקשה השואל: \u0003וכל היכא\u0004 \u0005[וכל מקום]\u0006 שהם \u0003חלוקין לחטאות לא מצטרפי\u0004 \u0005[אינם מצטרפים]\u0006 לשיעור אחד? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אכל חלב וחלב,\u0004 כלומר, שני שיעורים של חלב \u0003בהעלם אחד\u0004 — \u0003אינו חייב אלא\u0004 חטאת \u0003אחת. אכל חלב ודם ונותר\u0004 מן הקרבנות לאחר זמנו, שהאוכלו חייב בחטאת, \u0003ופגול\u0004 (קרבן שנפסל פסול חמור וחייב חטאת על אכילתו בשגגה) \u0003בהעלם אחד\u0004 — \u0003חייב\u0004 קרבן חטאת \u0003על כל אחת ואחת,\u0004 ו\u0003זו חומר\u0004 (חומרה) שישנה \u0003במינין הרבה\u0004 של איסורים יותר \u0003מ\u0004ב\u0003מין אחד. ו\u0004אולם \u0003זו חומר במין אחד\u0004 יותר \u0003מ\u0004באכילת \u0003מינין הרבה: שאם אכל חצי זית וחזר ואכל חצי זית ממין אחד\u0004 — \u0003חייב,\u0004 שהם מצטרפים לשיעור אחד, אבל אם אכל כזית \u0003משני מינין\u0004 — \u0003פטור. \u0004","\u0003והוינן\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה\u0004 במשנה זו: זה ששנינו שאם אכל שני חצאי זיתים \u0003ממין אחד\u0004 שהוא \u0003חייב צריכא למימר\u0004 \u0005[צריך לומר]?\u0006 והלוא פשוט הוא שכן הדין, ומה השמיענו בכך? \u0003ואמר ריש לקיש משום\u0004 (בשם) החכם \u0003בר תוטני: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שאכלו\u0004 לאותו זית \u0003בשני תמחויין\u0004 (כלים גדולים), שנתבשל חציו בכל אחד מהם, \u0003ו\u0004הדבר לשיטת \u0003ר' יהושע היא,\u0004 ש\u0003אמר תמחויין מחלקין.\u0004 שהאוכל שני זיתים מדבר האסור בהעלם אחד, אלא שאכל כל אחד מהם בתמחוי מיוחד — חייב להביא קרבן חטאת על כל אחד ואחד. \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003אמר ר' יהושע\u0004 דבריו שתמחויים מחלקים \u0003בין לקולא\u0004 \u0005[להקל]\u0006 \u0003בין לחומרא\u0004 \u0005[להחמיר]\u0006 ולכן האוכל כזית אחד בשני תמחויים — כיון שבכל אחד מהם אכל פחות שכשיעור — ייפטר, על כן \u0003קא משמע לן דלקולא\u0004 \u0005[השמיע לנו ש\u0006לענין \u0005להקל]\u0006 \u0003לא אמר\u0004 ר' יהושע שתמחויים מחלקים ורק \u0003לחומרא קאמר\u0004 \u0005[\u0006לענין \u0005להחמיר אמר].\u0006","\u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003חלוקין ל\u0004ענין מספר \u0003החטאות,\u0004 שהאוכל בשני תמחויים שיעור שלם חייב להביא שתי חטאות לדעת ר' יהושע, \u0003וקא מצטרפי\u0004 \u0005[ו\u0006אף על פי כן \u0005הם מצטרפים]\u0006 אותם שני חצאי שיעור להיות כאיסור אחד! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לר' ירמיה (או ר' אסי לר' זירא לדעה האחרת): \u0003מר ארישא מתני לה וקשיא ליה. אנן אסיפא מתנינן לה, ולא קשיא לן\u0004 \u0005[אדוני על ראשה\u0006 של המשנה \u0005למד אותה\u0006 את תשובתו של ריש לקיש \u0005וקשה לו. אנחנו\u0006 על סופה של המשנה \u0005למדנו אותה ולא קשה לנו].\u0006 וכך אנו לומדים: באותה משנה נאמר בסופה כי האוכל שני חצאי זיתים \u0003משני מינין פטור\u0004 ועל דבר זה שאלנו: וכי דבר זה \u0003צריכא למימר\u0004 \u0005[צריך לומר]?\u0006 והלוא פשוט הוא! \u0003ו\u0004על דבר זה \u0003אמר ריש לקיש משום בר תוטני\u0004 ש\u0003לעולם\u0004 מדובר אפילו כשהיה האיסור \u0003ממין אחד. ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 \u0003\"שני מינין\"\u0004 — מפני \u0003שאכלו בשני תמחויין, ו\u0004לשיטת \u0003ר' יהושע היא\u0004 ש\u0003אמר תמחויין מחלקין. והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]:\u0006 ש\u0003אמר ר' יהושע\u0004 שתמחויים מחלקים \u0003בין לקולא\u0004 \u0005[להקל]\u0006 \u0003בין לחומרא\u0004 \u0005[להחמיר].\u0006","ושואלים: \u0003מדסיפא\u0004 \u0005[מ\u0006אחר ש\u0005בסוף\u0006 במשפט האחרון\u0005]\u0006 מדובר, כפי שפירשנו כאן, ב\u0003מין אחד ו\u0004בשאכל את שני חצאי שיעורו ב\u0003שני תמחויין\u0004"],["\u0003מכלל\u0004 הדברים אתה למד כי \u0003דרישא\u0004 \u0005[בראשה]\u0006 מדובר ב\u0003מין אחד\u0004 שאכלו \u0003בתמחוי אחד.\u0004 ואולם עתה קשה השאלה יותר: שחייב באכילתו שני חצאי זיתי מ\u0003מין אחד\u0004 המונחים ב\u0003תמחוי אחד צריכא למימר\u0004 \u0005[צריך לומר]?!\u0006 \u0003אמר רב הונא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שהיתה לו ידיעה בינתיים.\u0004 שלאחר שאכל חצי זית ראשון נודע לו שהיה בכך איסור, וחזר ונעלם ממנו, ואכל חצי זית שני. ואף שכרגיל ידיעה מחלקת (לענין קרבנות) כל שגגה לחלק שלפני הידיעה ושלאחר הידיעה, \u0003ו\u0004הרי משנה זו כשיטת \u0003רבן גמליאל היא\u0004 ש\u0003אמר: אין ידיעה לחצי שיעור,\u0004 שמאחר שעל חצי שיעור אין חייבים קרבן, לשיטתו ידיעה זו שבינתיים אינה נחשבת, ואינה מחלקת לענין קרבן.","\u0003איתמר\u0004 \u0005[נאמר,\u0006 מחלוקת אמוראים]: מי ש\u0003אכל שני זיתי חלב בהעלם אחד, ונודע לו על\u0004 חטאו \u0003הראשון, וחזר ונודע לו על השני. ר' יוחנן אמר:\u0004 במקרה זה \u0003חייב שתים,\u0004 קרבן על כל אחד ואחד. \u0003וריש לקיש אמר: אינו חייב אלא אחת.\u0004 ושניהם מביאים ראיות לדבריהם; \u0003ר' יוחנן אמר\u0004 ש\u0003חייב\u0004 כיון שנאמר: \"והקריב \u0003על חטאתו\u0004 אשר חטא... \u0003והביא\u0004 את הפר\" (ויקרא ד, ג–ד) ומשמע מכאן שעל כל חטא יש להביא קרבן לעצמו. \u0003ו\u0004אילו \u0003ריש לקיש אמר\u0004 ש\u0003פטור\u0004 כיון שנאמר: \"וכפר עליו הכהן \u0003מחטאתו ונסלח לו\"\u0004 (ויקרא ד, כו), ומשמע שאף אם כפר על מקצת חטאתו (\"מחטאתו\" ולא כולה) נסלח לו על החטא כולו.","ושואלים: \u0003וריש לקיש,\u0004 איך יכול הוא לומר שדי בחטאת אחת, \u0003הכתיב\u0004 \u0005[\u0006ו\u0005הלא נאמר]\u0006 \u0003\"על חטאתו... והביא\"\u0004 ומשיבים: הפסוק \u0003ההוא\u0004 מדבר באופן שנודע לו מהשני \u0003לאחר כפרה,\u0004 ואולם אם נודע לו קודם לכן אכן לצורך הכפרה אינו צריך להביא אלא חטאת אחת. ושואלים: \u0003ולר' יוחנן נמי\u0004 \u0005[גם כן]\u0006 איך יכול הוא לומר שחייב שתים \u0003הכתיב\u0004 \u0005[\u0006ו\u0005הלא נאמר]\u0006 \u0003\"מחטאתו ונסלח לו\"!\u0004 ומשיבים: לשיטת ר' יוחנן \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — ב\u0003כגון שאכל כזית ומחצה, ונודע לו על\u0004 חטאו ב\u0003כזית\u0004 בלבד, \u0003וחזר ואכל כחצי זית אחר בהעלמו של\u0004 ה\u0003שני.\u0004 ומעתה \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003כי ליצטרפו\u0004 \u0005[שיצטרפו]\u0006 שני החצאי זיתים ויביא עליהם קרבן נוסף, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב שבכגון זה כיון שכבר נסלח לו מקצת חטאו — פטור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 מחלוקת זו של ר' יוחנן וריש לקיש האם היא באופן \u0003דאיתידע ליה\u0004 \u0005[שנודע לו]\u0006 לחוטא על החטא השני \u0003קודם הפרשה\u0004 של הקרבן הראשון \u0003פליגי\u0004 \u0005[נחלקו],\u0006 \u0003ובהא פליגי\u0004 \u0005[ובזה נחלקו,\u0006 זה בסיס מחלוקתם\u0005],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 ש\u0003ידיעות\u0004 בלבד \u0003מחלקות,\u0004 שכיון שנודעו לו חטאיו בשתי ידיעות נבדלות — עליו להביא שני קרבנות. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 שרק \u0003הפרשות\u0004 הקרבנות \u0003מחלקות, אבל\u0004 אם נודע לו החטא השני \u0003לאחר הפרשה\u0004 של הקרבן על החטא הראשון \u0003מודי ליה\u0004 \u0005[מודה לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 ש\u0003חייב שתים,\u0004 שהרי כבר הפריש קרבן אחד על חטא ראשון. \u0003או דילמא\u0004 \u0005[שמא]\u0006 באופן \u0003דאיתידע ליה\u0004 \u0005[שנודע לו]\u0006 החטא השני \u0003לאחר הפרשה\u0004 של הקרבן על החטא הראשון \u0003פליגי\u0004 \u0005[נחלקו],\u0006 \u0003ובהא פליגי\u0004 \u0005[ובזה נחלקו],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 ש\u0003הפרשות מחלקות, ומר סבר\u0004 \u0005[וחכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 שרק \u0003כפרות מחלקות,\u0004 שאחר שהוקרב הקרבן ונתכפר לחוטא אפשר לומר שנגמר כח כפרתו של הקרבן, וחטא שנודע לאחר מכן אינו מתכפר בו. \u0003אבל\u0004 אם נודע לו על החטא השני אף \u0003קודם הפרשה מודי ליה\u0004 \u0005[מודה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ש\u0003אינו חייב אלא\u0004 חטאת \u0003אחת. או דילמא\u0004 \u0005[שמא]\u0006 \u0003בין בזו ובין בזו,\u0004 הן קודם הפרשה והן לאחר הפרשה \u0003מחלוקת\u0004 היא ביניהם?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר כי \u0003בין בזו ובין בזו מחלוקת.\u0004 וראייה לדבר: \u0003דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך]\u0006 לומר כי רק במקרה שנודע לו על החטא \u0003השני קודם הפרשה\u0004 של הקרבן על הראשון \u0003פליגי\u0004 \u0005[נחלקו],\u0006 \u0003אבל לאחר הפרשה מודה ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 ש\u0003חייב שתים,\u0004 אם כן \u0003אדמוקים ליה קרא\u0004 \u0005[עד ש\u0006הוא \u0005מעמיד,\u0006 מפרש, \u0005לו\u0006 את \u0005הפסוק]\u0006 הקשה לשיטתו בשנודע לו מהחטא השני \u0003לאחר\u0004 ה\u0003כפרה\u0004 על הראשון, \u0003לוקמיה\u0004 \u0005[יעמידנו]\u0006 בשנודע לו \u0003לאחר הפרשה\u0004 של הקרבן על הראשון! \u0003ו\u0004כן \u0003אי\u0004 \u0005[אם]\u0006 תאמר שרק בשנודע לו החטא השני ל\u0003אחר הפרשה פליגי\u0004 \u0005[נחלקו],\u0006 \u0003אבל\u0004 במקרה שנודע לו \u0003קודם הפרשה מודה ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ש\u0003אינו חייב אלא\u0004 חטאת \u0003אחת,\u0004 אם כן \u0003אדמוקי ליה קרא\u0004 \u0005[עד ש\u0006הוא \u0005מעמיד לו\u0006 את \u0005הפסוק]\u0006 \u0003בכזית ומחצה, לוקמיה\u0004 \u0005[יעמידנו]\u0006 בשנודע לו \u0003קודם הפרשה!\u0004","ואולם רבינא איננו מקבל את ההוכחה הזו, שלדעתו אינה מושלמת; \u0003ודילמא ספוקי מספקא ליה\u0004 \u0005[ושמא מסופק לו]\u0006 הדבר, \u0003ו\u0004בדרך \u0003\"אם תימצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\" קאמר\u0004 \u0005[אמר],\u0006 ובאופן זה: \u0003אם תימצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי בשנודע לו על החטא השני \u0003קודם הפרשה\u0004 על הראשון \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה,\u0004 אם כן \u0003ר' יוחנן היכי מוקי ליה לקרא\u0004 \u0005[איך מעמיד הוא\u0006 את \u0005הפסוק]\u0006 — \u0003בכזית ומחצה. ואם תימצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי בשנודע לו \u0003לאחר הפרשה\u0004 נחלקו, אם כן \u0003ריש לקיש היכי מוקי ליה לקרא\u0004 \u0005[איך מעמיד הוא\u0006 את \u0005הפסוק]\u0006 — \u0003בלאחר כפרה.\u0004","\u0003אמר עולא: למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי לפני שמפריש \u0003אשם ודאי\u0004 שמביא מי שגזל, או מעל בהקדש, או בא על שפחה חרופה, \u0003לא בעיא\u0004 \u0005[אין צורך]\u0006 ב\u0003ידיעה בתחילה\u0004 שידע החוטא בוודאות שחטא,"],["אם כן \u0003בעל חמש בעילות בשפחה חרופה,\u0004 שעל בעילת שפחה חרופה מביא אשם, וכיון שאין צורך בידיעה מתחילה, הרי אף אם נודע לו בין עבירה ועבירה — \u0003אינו חייב אלא אחת.\u0004 שהרי הידיעה אינה נחשבת בקרבן זה ואינה מחלקת באשם. \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על הלכה זו \u0003רב המנונא: אלא מעתה\u0004 אם \u0003בעל\u0004 שפחה חרופה \u0003וחזר ובעל והפריש קרבן, ואמר: המתינו לי\u0004 בהקרבת הקרבן \u0003עד שאבעול\u0004 עוד פעם, שתכופר לו גם עבירה זו, \u0003הכי נמי\u0004 \u0005[האם גם כן]\u0006 נאמר ש\u0003אינו חייב אלא אחת? אמר ליה\u0004 \u0005[לו]\u0006 עולא: \u0003מעשה\u0004 ש\u0003לאחר הפרשה\u0004 של קרבן \u0003קאמרת\u0004 \u0005[אמרת]?!\u0006 ב\u0003מעשה\u0004 ש\u0003לאחר הפרשה לא קאמינא\u0004 \u0005[אמרתי]\u0006 דברי.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 שכדי להפריש \u0003אשם ודאי בעי\u0004 \u0005[צריך]\u0006 שתהיה לחוטא \u0003ידיעה\u0004 גמורה מחטאו \u0003בתחלה,\u0004 אם כן כאשר \u0003בעל חמש בעילות בשפחה חרופה\u0004 — \u0003חייב\u0004 אשם \u0003על כל אחת ואחת,\u0004 שהידיעה באשם מחלקת בין שגגה לשגגה, ועושה כל פרט כעבירה בפני עצמה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב דימי: ו\u0003הרי חטאת, דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שתהא \u0003ידיעה בתחלה\u0004 לדברי הכל, \u0003ופליגי\u0004 \u0005[ו\u0006בכל זאת \u0005חלוקים]\u0006 בדבר זה \u0003ר' יוחנן ור' שמעון בן לקיש\u0004 אם הידיעות שלאחר החטא מחלקות! \u0003אישתיק\u0004 \u0005[שתק]\u0006 רב דימי ולא מצא תשובה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי שניסה למצוא גם הוא הסבר לדבר: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003במעשה\u0004 עבירה שרוצה לעשות החוטא \u0003לאחר הפרשה\u0004 ורוצה לכלול את כפרתו באותו קרבן \u0003קאמרת\u0004 \u0005[אמרת]\u0006 דבריך, \u0003וכ\u0004פי שאמר \u0003רב המנונא?\u0004 נזכר רב דימי ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 לעולא: \u0003אין\u0004 \u0005[כן],\u0006 אכן כך נאמר הדבר מתחילה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, סיכם מקרים אחדים בדיני אשם, ואת חילוקי הדעות שיש לגביהם, ו\u0003אמר: הכל מודים בשפחה חרופה, והכל מודים בשפחה חרופה, ומחלוקת בשפחה חרופה.\u0004 ופירוט דבריו: \u0003הכל מודים בשפחה חרופה\u0004 ש\u0003אינו חייב אלא\u0004 קרבן אשם \u0003אחת\u0004 אפילו בבעילות רבות, באותו מקרה ולפי אותה שיטה שאמר \u0003עולא\u0004 שאם אינו צריך ידיעה בתחילה, אפילו נודע לו בין שגגה לשגגה — מביא קרבן אחד. \u0003והכל מודים בשפחה חרופה\u0004 ש\u0003חייב על כל אחת ואחת\u0004 — אם היה מעשה העבירה לאחר ההפרשה, \u0003כ\u0004דברי \u0003רב המנונא. ומחלוקת בשפחה חרופה למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003אשם ודאי בעי\u0004 \u0005[צריך]\u0006 \u0003ידיעה\u0004 מהחטא \u0003בתחלה\u0004 כדי להתחייב בו, הרי דין האשם כדין החטאת, והרי זו \u0003מחלוקת ר' יוחנן ור' שמעון בן לקיש,\u0004 אם ידיעות מחלקות לקרבנות.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים להלכה בענין זה:"],["\u0003נתכוין\u0004 אדם \u0003להגביה\u0004 את הדבר \u0003התלוש\u0004 מן הקרקע בשבת, \u0003וחתך\u0004 בשוגג \u0003את המחובר\u0004 — \u0003פטור\u0004 אף מלהביא קרבן על שגגתה כיון שלא נתכוון כלל לעשות מעשה של חיתוך (ודבר זה, כשעושה אדם מעשה בלא שיתכוון כלל לעשייה, הוא הנקרא \"מתעסק\") ואין בו חיוב כלל. ואולם מי שנתכוון \u0003לחתוך את\u0004 הדבר \u0003התלוש,\u0004 וטעה \u0003וחתך את המחובר\u0004 ועבר על ידי כך על איסור קצירה בשבת, \u0003רבא אמר:\u0004 גם הוא \u0003פטור. אביי אמר: חייב.\u0004 וביאור דבריהם: \u0003רבא אמר\u0004 ש\u0003פטור\u0004 — \u0003דהא\u0004 \u0005[שהרי]\u0006 הוא \u0003לא נתכוון\u0004 כלל \u0003ל\u0004פעולת \u0003חתיכה דאיסורא\u0004 \u0005[ש\u0006יש בה \u0005איסור],\u0006 שהרי רצה לעשות דבר המותר לגמרי בשבת, ולא שגגה בדיני שבת היתה כאן, אלא חוסר זריזות או טעות בפעולה עצמה. ו\u0003אביי אמר\u0004 שהוא \u0003חייב\u0004 — \u0003דהא קמיכוין\u0004 \u0005[שהרי הוא מתכוין]\u0006 \u0003ל\u0004פעולת \u0003חתיכה בעלמא\u0004 \u0005[כרגיל,\u0006 בדרך כלל\u0005],\u0006 וכיון שנתכוון למלאכה זו, ואירע שעשה איסור — הרי זה שוגג האמור בתורה.","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אומר אני\u0006 דעתי \u0005זו]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 יש \u0003חומר\u0004 (חומרה מיוחדת) באיסורי \u0003שבת משאר מצות, וחומר\u0004 ב\u0003שאר מצות משבת.\u0004 ומבואר שם: \u0003חומר שבת משאר מצות, ש\u0004בהלכות \u0003שבת\u0004 אם \u0003עשה שתים\u0004 מפרטי עבירות שבשבת אף \u0003בהעלם אחד\u0004 — \u0003חייב על כל אחת ואחת, מה שאין כן בשאר מצות,\u0004 שבהן אם עבר כמה פעמים אותה עבירה בהעלם אחד מביא רק קרבן חטאת אחד. \u0003ו\u0004אילו \u0003חומר\u0004 ב\u0003שאר מצות משבת\u0004 — \u0003שבשאר מצות\u0004 אם \u0003שגג בלא מתכוין\u0004 — \u0003חייב, מה שאין כן בשבת.\u0004 וממשמעות הדברים נראה ש\"שגג בלא מתכוון\" הוא המקרה שדיברו בו אביי ורבא, וראייה היא אם כן לשיטת רבא, שבדיני שבת שגגה שבאה מתוך התעסקות בדבר אחר (בלא להתכוון לעשיית אותו איסור) אינה נחשבת לשגגה.","לפני שבאים לדון במסקנותיה של ברייתא זו לענין מחלוקת אביי ורבא, מנתחים אותה לגופה. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003חומר\u0004 בהלכות \u0003שבת משאר מצות, שהשבת\u0004 אם \u0003עשה\u0004 בה \u0003שתים\u0004 (שתי שגגות) \u0003בהעלם אחד\u0004 — \u0003חייב על כל אחת ואחת, מה שאין כן בשאר מצות.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[איך בדיוק היה הדבר]?\u0006 \u0003אילימא דעבד\u0004 \u0005[אם נאמר שעשה]\u0006 בשבת \u0003קצירה וטחינה\u0004 בשוגג, \u0003דכוותה גבי\u0004 \u0005[שכמותה,\u0006 בדומה לה \u0005אצל,\u0006 ביחס\u0005]\u0006 ל\u0003שאר מצות\u0004 במקרה ש\u0003אכל חלב ודם,\u0004 שעשה אז שתי עבירות נפרדות. ואולם אם כן הוא — אין כל הבדל בהלכה, שכן \u0003הכא תרתי מיחייב, והכא תרתי מיחייב\u0004 \u0005[כאן שתיים\u0006 הוא \u0005מתחייב, וכאן שתיים\u0006 הוא \u0005מתחייב].\u0006 \u0003אלא שאר מצות דלא מיחייב\u0004 \u0005[שאינו מתחייב]\u0006 \u0003אלא חדא\u0004 \u0005[\u0006קרבן \u0005אחד]\u0006 \u0003היכי דמי\u0004 \u0005[איך בדיוק היה הדבר]\u0006 — כגון ש\u0003אכל\u0004 פעם אחת \u0003חלב ו\u0004שוב חזר ו\u0003אכל חלב\u0004 בהעלם אחד, \u0003דכוותה גבי\u0004 \u0005[שכמותה,\u0006 בדומה לה \u0005אצל,\u0006 ביחס\u0005]\u0006 ל\u0003שבת\u0004 — \u0003דעבד\u0004 \u0005[שעשה]\u0006 \u0003קצירה וקצירה\u0004 בהעלם אחד, ואולם גם במקרה זה אין הבדל בהלכה, שכן \u0003הכא חדא מיחייב, והכא חדא מיחייב\u0004 \u0005[כאן באחת\u0006 הוא \u0005מתחייב, וכאן באחת\u0006 הוא \u0005מתחייב]!\u0006","ומסבירים: \u0003לעולם\u0004 תאמר שמדובר בכגון \u0003דעבד\u0004 \u0005[שעשה]\u0006 \u0003קצירה וטחינה, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"מה שאין כן בשאר מצות\"\u0004 — אין המדובר בכל המצוות כולן שאין בהן פרטי עבירה שונים, אלא ביחס לאיסור \u0003עבודה זרה,\u0004 שאף בו יש פרטי עבירות שונים זה מזה שבכל אחד מהן חיוב לעצמו, וכפי שאמר \u0003ר' אמי.\u0004 ש\u0003אמר ר' אמי:\u0004 מי ש\u0003זיבח\u0004 לעבודה זרה \u0003וקיטר\u0004 קטורת לפניה \u0003וניסך\u0004 יין לפניה \u0003בהעלמה אחת\u0004 — \u0003אינו חייב אלא\u0004 חטאת \u0003אחת,\u0004 אף שאם עשה כל אחת מעבירות אלה בפני עצמה חייב על כל אחת ואחת, וזוהי החומרה היתירה שבהלכות שבת.","ומקשים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת,\u0006 הסברת\u0005]\u0006 את המשנה — \u0003בעבודה זרה,\u0004 אם כן \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 ונראה אם גם בהמשך הדברים יש הגיון בהסבר זה. שנאמר שם: \u0003חומר בשאר מצות\u0004 שבשבת, \u0003שבשאר מצות\u0004 אם \u0003שגג בלא מתכוין\u0004 — \u0003חייב, מה שאין כן בשבת,\u0004 שאם שגג בה במלאכה בלא שהתכוין לעשותה — פטור, אם כן \u0003האי שגג בלא מתכוין\u0004 ב\u0003עבודה זרה היכי דמי\u0004 \u0005[כיצד היה בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 בכגון ש\u0003כסבור\u0004 אותו אדם ש\u0003בית הכנסת הוא והשתחוה לה\u0004 ונמצא שהשתחווה לעבודה זרה — אין בכך כל עבירה, ש\u0003הרי לבו לשמים\u0004 ואין כאן אף עבירה בשגגה. \u0003ואלא\u0004 תאמר שמדובר באופן \u0003דחזי\u0004 \u0005[שראה]\u0006 \u0003אנדרטא\u0004 (פסל של המלך) \u0003וסגיד\u0004 \u0005[והשתחווה]\u0006 \u0003לה,\u0004 ואולם אף כאן יש לנתח את הדברים בדיוק; \u0003היכי דמי\u0004 \u0005[כיצד היה בדיוק]\u0006? \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן \u0003שקבלה\u0004 לאותה דמות \u0003עליה\u0004 \u0005[על עצמו]\u0006 \u0003באלוה,\u0004 ומשום כך השתחווה — הרי \u0003מזיד הוא\u0004 זה בעבודה זרה. \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר באופן ש\u0003לא קבלה עליה\u0004 \u0005[על עצמו]\u0006 \u0003באלוה,\u0004 והשתחווה מפני הנימוס או כבוד המלכות — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלום הוא,\u0004 ואין בכך עבודה זרה.","\u0003אלא\u0004 תאמר שהשתחווה \u0003מאהבה,\u0004 שרוצה לעשות רצון מישהו שאוהב, \u0003ומיראה\u0004 שירא מפני אדם שכופה אותו לכך, ומשתחוה לפסל. וסבור אותו אדם שאם אינו מתכוון בלבו באמת לעבודה זרה אין בכך איסור, \u0003הניחא\u0004 \u0005[\u0006הסבר \u0005זה נוח]\u0006 \u0003ל\u0004שיטת \u0003אביי\u0004 בנושא זה, ש\u0003אמר\u0004 שהמשתחווה מאהבה ומיראה \u0003חייב. אלא לרבא\u0004 שלדעתו על עבודה זרה מיראה ואהבה \u0003פטור, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שלדעתו אף בזה אין חילוק בין עבודה זרה למצוות שבת! \u0003אלא\u0004 תאמר שהמדובר כאן \u0003באומר\u0004 לעצמו שדבר זה \u0003מותר\u0004 לעשותו, שאותו אדם סבור היה שעבודה זרה מותרת, וטעותו לא שגגה שבשכחה היתה, אלא שגגה שבידיעה בלתי נכונה. ולפיכך \u0003\"מה שאין כן בשבת \"\u0004האמור בברייתא לענין זה משמעו שהאומר מותר לגבי עבירת שבת \u0003פטור. פטור לגמרי.\u0004","אך אם כן הוא, תהא זו סתירה לדברי רבא עצמו, כי \u0003עד כאן לא\u0004 שמענו כי \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבא מרב נחמן\u0004 במקרה של אדם שנעלם ממנו גם איסור השבת וגם איסור המלאכות, \u0003אלא אי לחיובי חדא, אי לחיובי תרתי\u0004 \u0005[אם לחייבו\u0006 חטאת \u0005אחת, אם לחייבו שתיים]\u0006 \u0003אבל מפטרי\u0004 \u0005[לפוטרו]\u0006 \u0003לגמרי\u0004 — \u0003לא\u0004 שאף רבא לא העלה בדעתו שהאומר מותר בשבת ייפטר לגמרי. ואם כן הסבר זה בדברי הברייתא אינו נכון לשיטת רבא."],["\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 ודאי שה\u0003רישא\u0004 \u0005[ראשה\u0006 של הברייתא\u0005]\u0006 דן \u0003ב\u0004השוואה בין שבת ל\u0003עבודה זרה, וסיפא\u0004 \u0005[וסוף\u0006 הברייתא\u0005]\u0006 מדבר \u0003ב\u0004השוואה ל\u0003שאר מצות. ושגג בלא מתכוין בשאר מצות היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 — כגון ש\u0003סבור\u0004 בדבר מסויים ש\u0003שומן הוא,\u0004 ומותר באכילה, \u0003ואכלו,\u0004 ולבסוף נודע שחלב הוא. \u0003מה שאין כן בשבת\u0004 שבכגון זה \u0003פטור,\u0004 שאם \u0003נתכוון לחתוך את התלוש\u0004 ולעשות דבר המותר \u0003וחתך את המחובר\u0004 הרי זה \u0003פטור,\u0004 ואם כן קשה מכאן לדברי אביי! \u0003ו\u0004אילו \u0003אביי\u0004 מסביר ש\u0003שגג בלא מתכוין\u0004 בשאר מצוות \u0003היכי דמי\u0004 \u0005[איך הוא בדיוק]?\u0006 — הריהו במקרה של מתעסק ממש, שהיה לו לאדם דבר בפיו, ו\u0003סבור\u0004 היה ש\u0003רוק הוא, ובלעו\u0004 ולא נתכוון כלל לאכילה ונמצא שבלע חלב, והרי זה חייב בשאר מצוות. \u0003מה שאין כן בשבת\u0004 כיוצא בזה, ש\u0003פטור,\u0004 שאם \u0003נתכוון להגביה את התלוש וחתך את המחובר\u0004 אף אביי מודה ש\u0003פטור. אבל\u0004 מי ש\u0003נתכוון לחתוך את התלוש וחתך את המחובר,\u0004 כיון שנתכוון למלאכת חיתוך — \u0003חייב.\u0004 ואין להוכיח מברייתא זו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 בברייתא שנחלקו אביי ורבא בענין דומה: מי ש\u0003נתכוון לזרוק\u0004 דבר ברשות הרבים \u0003שתים,\u0004 שתי אמות, שמדין תורה אינו חייב, \u0003ו\u0004אירע לו ש\u0003זרק ארבע\u0004 אמות ובכך עבר על איסור מן התורה בטלטול חפץ ארבע אמות ברשות הרבים, \u0003רבא אמר: פטור. אביי אמר: חייב.\u0004 וביאור דבריהם: \u0003רבא אמר\u0004 ש\u0003פטור\u0004 — משום \u0003דלא קמיכוין\u0004 \u0005[שאינו מתכוין]\u0006 \u0003לזריקה\u0004 של \u0003ארבע\u0004 אמות, ולא נתכוון אם כן למעשה של איסור. ו\u0003אביי אמר: חייב, דהא קמיכוין\u0004 \u0005[שהרי\u0006 מכל מקום \u0005התכוין]\u0006 \u0003לזריקה בעלמא\u0004 \u0005[בכלל],\u0006 ומכיון שבסופו של דבר היתה הזריקה \u0005למקום אסור — חייב.\u0006 ועוד נחלקו: \u0003כסבור\u0004 היה אדם שהוא ב\u0003רשות היחיד\u0004 וזרק שם יותר מארבע אמות, \u0003ונמצאת\u0004 בסופו של דבר \u0003רשות הרבים\u0004 — \u0003רבא אמר: פטור, ואביי אמר: חייב.\u0004 וטעמם: \u0003רבא אמר\u0004 ש\u0003פטור\u0004 — \u0003דהא לא מיכוין\u0004 \u0005[אינו מתכוין]\u0006 \u0003לזריקה דאיסורא\u0004 \u0005[ש\u0006יש בה \u0005איסור],\u0006 שהרי ברשות היחיד מותר לו לזרוק חפץ לכל מרחק שירצה. \u0003ואביי אמר\u0004 ש\u0003חייב\u0004 — \u0003דהא קמיכוין\u0004 \u0005[שהרי הוא מתכוין]\u0006 \u0003לזריקה בעלמא\u0004 \u0005[בכלל]\u0006","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 להודיענו את שלוש המחלוקות שביניהם, שאף שהן דומות זו לזו, מכל מקום אינן זהות, ובכל אחת יש חידוש. \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאילו היה משמיע לנו\u0006 רק \u0005את הראשונה]\u0006 בענין הרוצה לחתוך תלוש וחתך את המחובר, הייתי אומר כי דווקא \u0003ב\u0004דין \u0003ההוא,\u0004 במקרה שנתכוין לחתוך את התלוש וחתך את המחובר \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רבא\u0004 שפטור \u0003דהא לא קמיכוין\u0004 \u0005[שהרי אינו מתכוין]\u0006 \u0003ל\u0004פעולת \u0003חתיכה דאיסורא\u0004 \u0005[ש\u0006יש בה \u0005איסור],\u0006 ולא נתכוון אם כן לדבר שיש בו חילול שבת. \u0003אבל\u0004 במקרה שעמד ברשות הרבים ו\u0003נתכוון לזרוק שתים,\u0004 שתי אמות, \u0003וזרק ארבע\u0004 אמות, חמור יותר, שהרי \u0003ארבע בלא תרתי\u0004 \u0005[שתים]\u0006 \u0003לא מיזרקא ליה\u0004 \u0005[אינן נזרקות],\u0006 נמצא שזריקה של שתי אמות אינה דבר נפרד מזריקה של ארבע אמות, אלא חלק ממנה, \u0003ואימא\u0004 \u0005[אמור]\u0006 כי בכגון זה \u0003מודה\u0004 רבא \u0003לאביי,\u0004 כיון שעשה דבר שיש בו צד איסור. \u0003ואי אשמעינן בהא\u0004 \u0005[ואילו השמיענו\u0006 גם \u0005בזו]\u0006 של זריקת שתי אמות, עדיין הייתי אומר כי דווקא \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003רבא\u0004 שפטור — \u0003דהא לא קמיכוין\u0004 \u0005[שהרי אינו מתכוין]\u0006 בכך \u0003לזריקה\u0004 של \u0003ארבע\u0004 אמות, ובפחות מארבע אמות אין זו עבירה, \u0003אבל\u0004 במקרה ש\u0003כסבור\u0004 שהיא \u0003רשות היחיד ונמצא\u0004 שהיא \u0003רשות הרבים, דמכוין\u0004 \u0005[שהתכוין]\u0006 \u0003לזריקה\u0004 של \u0003ארבע\u0004 אמות שהיא זריקת איסור \u0003אימא מודי ליה\u0004 \u0005[מודה\u0006 \u0003לו]\u0004 רבא \u0003לאביי\u0004 שחייב, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 להודיענו שלוש מחלוקות אלה.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003\"אבות מלאכות ארבעים חסר אחת\", והוינן\u0004 \u0005[ועסקנו]\u0006 \u0003בה\u0004 בשאלה זו, ושאלנו: \u0003מנינא\u0004 \u0005[מנין]\u0006 זה ששנינו \u0003למה לי? ואמר ר' יוחנן:\u0004 לומר \u0003שאם עשאן כולם בהעלם אחד\u0004 — \u0003חייב על כל אחת ואחת, בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי\u0004 ש\u0003אמר כי האי גוונא\u0004 \u0005[שב\u0006מקרה \u0005כגון זה]\u0006 שדובר מקודם \u0003חייב, משכחת לה\u0004 \u0005[מוצאים אנו אותה]\u0006 אפשרות באופן ש\u0003ידע דאסורא\u0004 \u0005[שאסורה]\u0006 \u0003שבת\u0004 בעשיית מלאכות שונות \u0003וידע לה\u0004 \u0005[ויודע הוא]\u0006 \u0003איסור מלאכות,\u0004 שיודע על מלאכות מסויימות שהן האסורות בעשייה בשבת, \u0003וקא טעה\u0004 \u0005[\u0006אלא ש\u0005טעה]\u0006 \u0003בשיעורין\u0004 שנתכוון לעשות פחות מכשיעור האיסור, ועלה בידו כשיעור. שלשיטת אביי הרי זו שגגה המחוייבת בקרבן. \u0003אלא לרבא\u0004 ש\u0003אמר\u0004 שבכגון זה \u0003פטור, היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותה]\u0006 אפשרות של \u0003זדון שבת ושגגת מלאכות\u0004 שזכר ששבת היום וידע שאסורות בה מלאכות שונות, ואולם שכח את כל איסורי המלאכות.","\u0003הניחא אי סבר לה\u0004 \u0005זה נוח אם סבור הוא\u0006 \u0003כ\u0004שיטת \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 כי \u0003כיון ששגג\u0004 אדם \u0003ב\u0004עבירה ולא ידע שיש \u0003ב\u0004עשייתה עונש \u0003כרת, אף על פי שהזיד בלאו\u0004 שידע שאסור לעשותה והעושה אותה עובר על מצות לא תעשה — אף זה נקרא שוגג, הרי \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 אפשרות בכגון ש\u0003ידע לה\u0004 \u0005[אותה]\u0006 את ה\u0003שבת\u0004 שידע שאיסורה הוא \u0003בלאו\u0004 (לא תעשה), \u0003אלא אי סבר לה\u0004 \u0005[אם סבור הוא]\u0006 רבא \u0003כ\u0004שיטת \u0003ר' שמעון בן לקיש\u0004 שאמר שאין שגגה אלא \u0003עד שישגוג בלאו וכרת\u0004 שבה, אם כן \u0003שידע לה\u0004 \u0005[אותה]\u0006 את ה\u0003שבת\u0004 שבכך יהיה זדון שבת \u0003במאי\u0004 \u0005[במה]\u0006 מוצא אתה כאן אפשרות כזו? ומשיבים: שיכול להיות ש\u0003ידע לה\u0004 \u0005[אותה]\u0006 \u0003ב\u0004כך שידע שיש בה איסור \u0003תחומין, ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 \u0003ר' עקיבא\u0004 הסבור שאיסור זה מן התורה.","משנה יסודית זו מונה את \u0003אבות\u0004 (יסודות) ה\u0003מלאכות\u0004 האסורות בשבת, שהן \u0003ארבעים חסר אחת,\u0004 והן מסודרות בקבוצות לפי שימושיהן: \u0003הזורע, והחורש, והקוצר, והמעמר\u0004 (אוסף את התבואה לערימה), \u0003והדש\u0004 (מוציא את הגרעין מן המוץ), \u0003והזורה\u0004 את התבואה הנידושה ברוח, ו\u0003הבורר\u0004 את הפסולת מן הראוי לאכילה, ו\u0003הטוחן, והמרקד\u0004 (מסנן את הקמח בנפה), \u0003והלש\u0004 את הבצק, \u0003והאופה.\u0004","ועוד באבות המלאכות: \u0003הגוזז את הצמר,\u0004 ו\u0003המלבנו\u0004 (מכבסו) \u0003והמנפצו\u0004 (סורק ומיישר את גיזת הצמר), \u0003והצובעו, והטווה\u0004 את הצמר, \u0003והמיסך\u0004 (מותח את חוטי השתי בתוך הנול), \u0003והעושה שני בתי נירין\u0004 (שיוצר את הקשרים הראשונים בין חוט השתי ובסיס הנול), \u0003והאורג שני חוטין, והפוצע\u0004 (קורע לצורך המלאכה) \u0003שני חוטין, הקושר\u0004 קשר, \u0003והמתיר\u0004 קשר, \u0003והתופר שתי תפירות\u0004 במחט, וכן \u0003הקורע על מנת לתפור שתי תפירות.\u0004","ואבות נוספים: \u0003הצד\u0004 בעל חיים כגון \u0003צבי,\u0004 ו\u0003השוחטו, והמפשיטו\u0004 ו\u0003המולחו\u0004 את עורו שהוא חלק מן העיבוד, \u0003והמעבד את עורו, והממחקו\u0004 (מחליק ומישר את העור על ידי הורדת שערות ורירים) \u0003והמחתכו\u0004 לחלקים קצובי מידה.","\u0003הכותב שתי אותיות, והמוחק על מנת לכתוב שתי אותיות.\u0004 ועוד: \u0003הבונה\u0004 בנין \u0003והסותר\u0004 אותו, \u0003המכבה\u0004 אש \u0003והמבעיר, המכה בפטיש\u0004 על הכלי בסיום המלאכה ובהבאתה לגמר שכלולה (ר\"ח), ו\u0003המוציא\u0004 חפץ \u0003מרשות לרשות הרי\u0004 כל \u0003אלו אבות\u0004 הן \u0003מלאכות,\u0004 ומניינן \u0003ארבעים חסר אחת.\u0004"],["שנינו במשנה שמספר אבותתת המלאכות הוא ארבעים חסר אחת. ושואלים: \u0003מנינא\u0004 \u0005[המנין]\u0006 \u0003למה לי\u0004 לאומרו? די לרשום את אבות המלאכה, בלי להודיע את מספרם! \u0003אמר ר' יוחנן:\u0004 המנין בא ללמדנו \u0003שאם עשאן כולם בהעלם אחד\u0004 — \u0003חייב על כל אחת ואחת.\u0004","שנינו במשנה בין אבות המלאכות את \u0003הזורע והחורש.\u0004 ושואלים: \u0003מכדי מכרב כרבי ברישא\u0004 \u0005[הלא לחרוש חורשים בתחילה]\u0006 ורק אחר כך זורעים, ואם כן \u0003ליתני\u0004 \u0005[שישנה]\u0006 התנא קודם \u0003חורש והדר ליתני\u0004 \u0005[ואחר ישנה]\u0006 \u0003זורע!\u0004 ומשיבים: ה\u0003תנא\u0004 שכתב את המשנה כמנהג \u0003בארץ ישראל קאי\u0004 \u0005[עומד,\u0006 מתבסס הוא\u0005]\u0006 \u0003דזרעי ברישא והדר כרבי\u0004 \u0005[ש\u0006הם \u0005זורעים בתחילה ואחר כך חורשים],\u0006 שנוהגים בארץ ישראל לחרוש חרישה שניה לאחר הזריעה, כדי לכסות את הזרעים.","\u0003תנא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בענין מלאכת הזורע: \u0003הזורע, והזומר\u0004 את ענפי הגפנים שהוא חלק מהטיפול בעידוד צמיחתם, \u0003והנוטע\u0004 שתיל \u0003והמבריך\u0004 עץ, כגון גפן, שכופף אחד מענפיה לארץ על מנת שיכה שורשים בעודו צמוד לגזעו. \u0003והמרכיב\u0004 אילן באילן — \u0003כולן מלאכה אחת הן,\u0004 שבכולן יש יסוד משותף שהוא הצמחה, סיוע לגידול. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך? ומסבירים כי דבר זה השמיע לנו: ש\u0003העושה\u0004 בשבת בשוגג \u0003מלאכות הרבה מעין מלאכה אחת,\u0004 כגון המלכות האמורות כמו זורע ונוטע \u0003אינו חייב אלא\u0004 חטאת \u0003אחת,\u0004 שהן נחשבות כפרטי אותה מלאכה. \u0003אמר ר' אחא\u0004 שכך \u0003אמר ר' חייא בר אשי\u0004 שכך \u0003אמר ר' אמי: זומר חייב משום\u0004 מלאכת \u0003נוטע, והנוטע והמבריך והמרכיב חייב משום\u0004 מלאכת \u0003זורע.\u0004 ותוהים: וכי המרכיב והמבריך \u0003משום זורע אין\u0004 \u0005[כן]\u0006 חייב, ו\u0003משום נוטע לא?\u0004 והרי מלאכות אלה נעשות בעצים וקרובות יותר לנטיעה. אלא \u0003אימא\u0004 \u0005[אמור,\u0006 תיקן כך\u0005]:\u0006 חייב \u0003אף משום זורע\u0004 שבהלכות שבת אין הבדל בין זריעה ונטיעה.","\u0003אמר רב כהנא:\u0004 מי שהיה \u0003זומר\u0004 אילן \u0003וצריך לעצים\u0004 שהוא זומר, להסקה או לצורך אחר — \u0003חייב שתים,\u0004 שתי חטאות, חטאת \u0003אחת משום\u0004 מלאכת \u0003קוצר,\u0004 שכל התולש דבר מגידולו משום שנזקק לדבר שתלש הרי זה מעין מלאכת הקצירה. \u0003ואחת\u0004 חייב \u0003משום\u0004 מלאכת \u0003נוטע,\u0004 שכן בכך הוא מסייע לצמיחה. ובדומה לכך \u0003אמר רב יוסף: האי מאן דקטל אספסתא\u0004 \u0005[מי שקוצר אספסת]\u0006 \u0003חייב שתים,\u0004 שתי חטאות, \u0003אחת משום קוצר,\u0004 שהוא צריך לאספסת להאכילה לבהמתו, \u0003ואחת משום נוטע,\u0004 שקצירה זו מסייעת לגידול האספסת. וכן \u0003אמר אביי: האי מאן דקניב סילקא\u0004 \u0005[הקוצץ עלי סילקא]\u0006 \u0003חייב שתים, אחת משום קוצר ואחת משום זורע.\u0004","שנינו במשנה בין המלאכות האסורות בשבת גם את \u0003החורש. תנא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 בענין מלאכת החורש: \u0003החורש והחופר והחורץ\u0004 (העושה חריץ בקרקע) \u0003כולן מלאכה אחת הן. אמר רב ששת: היתה לו גבשושית\u0004 של אדמה \u0003ונטלה\u0004 ויישר בכך את השטח, אם היה זה \u0003ב\u0004קרקע ה\u0003בית\u0004 — \u0003חייב משום\u0004 מלאכת \u0003בונה,\u0004 שכן בכך הוא משלים ומתקן את בנין הבית. ואם היה זה \u0003בשדה\u0004 — \u0003חייב משום\u0004 מלאכת \u0003חורש.\u0004 וכן \u0003אמר רבא,\u0004 מי ש\u0003היתה לו גומא וטממה\u0004 (סתמה), אם היה זה \u0003בבית\u0004 — \u0003חייב משום בונה, בשדה\u0004 — חייב \u0003משום חורש.\u0004","\u0003אמר ר' אבא: החופר גומא בשבת ואינו צריך\u0004 את הגומא עצמה \u0003אלא\u0004 שנזקק הוא \u0003לעפרה\u0004 — \u0003פטור עליה,\u0004 על חפירה זו, שאין זו מלאכת חפירה האסורה מן התורה בשבת. \u0003ואפילו ל\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 בדרך כלל שהעושה בשבת \u0003מלאכה שאינה צריכה לגופה,\u0004 שאינו רוצה להשתמש בתוצאותיה הישירות \u0003חייב עליה\u0004 — גם הוא יודה במקרה זה. שכן \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאמר ר' יהודה דווקא ב\u0003מתקן,\u0004 כאשר עושה הוא מלאכה שיש בה משום יצירה ותיקון, אבל \u0003האי\u0004 \u0005[זה]\u0006 שחופר גומא — \u0003מקלקל הוא,\u0004 וכיון שאינו עושה מלאכת תיקון ואף אינו זקוק למלאכה — פטור לדעת הכל.","שנינו במשנה בין המלאכות האסורות בשבת גם את \u0003הקוצר.\u0004 ועל מלאכת הקוצר \u0003תנא\u0004 \u0005[שנינו]\u0006 בתוספתא: \u0003הקוצר,\u0004 ו\u0003הבוצר\u0004 ענבים, \u0003והגודר\u0004 בתמרים \u0003והמסיק\u0004 בזיתים \u0003והאורה\u0004 בתאנים — \u0003כולן מלאכה אחת\u0004 הן, שכולן מלאכת קטיפת פרי. \u0003אמר רב פפא: האי מאן דשדא פיסא לדיקלא ואתר תמרי\u0004 \u0005[מי שזרק צרור לדקל והשיר תמרים]\u0006 \u0003חייב שתים,\u0004 שתי חטאות, \u0003אחת משום תולש,\u0004 שהיא תולדת מלאכת קוצר \u0003ואחת משום מפרק,\u0004 שהיא תולדת מלאכת דש, כלומר, הוצאת דבר הראוי לאכילה מתוך כיסוייו. ואילו \u0003רב אשי אמר:\u0004 במקרה זה פטור, כיון ש\u0003אין דרך תלישה בכך, ואין דרך פריקה בכך,\u0004 ומלאכה שעושה אותה שלא כדרך המקובלת בעשייתה — אינו חייב עליה.","שנינו במשנה בין המלאכות האסורות בשבת גם את \u0003המעמר.\u0004 והוסיף ו\u0003אמר רבא: האי מאן דכניף מילחא ממלחתא\u0004 \u0005[מי שאוסף מלח מבריכות המלח]\u0006 \u0003חייב משום\u0004 מלאכת \u0003מעמר.\u0004 שכן עושה הוא פעולה דומה, שהוא אוסף מן השדה את הדברים שהוא נצרך להם לערימה אחת. \u0003אביי אמר:\u0004 אין הדבר כן, ו\u0003אין\u0004 איסור \u0003עימור\u0004 חל מן התורה \u0003אלא בגידולי קרקע\u0004 בלבד.","בן המלאכות שנשנו במשנה הוזכרה גם מלאכת \u0003הדש. תנא\u0004 \u0005[שנינו]\u0006 בתוספתא: \u0003הדש והמנפץ\u0004 את הפשתן ומוציא אותו מן הכיסוי הקשה של גבעולו, \u0003והמנפט,\u0004 שמוציא את גרעיני צמר הגפן מן הכותנה, \u0003כולן מלאכה אחת הן.\u0004","ברשימת המלאכות השנויה במשנה מוצאים אנו את \u0003הזורה, הבורר, והטוחן והמרקד.\u0004 ושואלים: \u0003היינו\u0004 \u0005[זוהי]\u0006 בדיוק מלאכת \u0003זורה, היינו\u0004 \u0005[זוהי]\u0006 מלאכת \u0003בורר, היינו\u0004 \u0005[זוהי]\u0006 מלאכת \u0003מרקד,\u0004 שכולן דומות זו לזו בדרך עשייתן, וזהות במטרתן, שכולן דרכים שונות להפרדת המאכל מן הפסולת. \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 תירוץ לדבר, וקבעו כלל: \u0003כל מילתא דהויא\u0004 \u0005[דבר שהיה]\u0006 \u0003במשכן,\u0004 שנעשתה מלאכה זו בודאי לצורך המשכן,"]]};
